INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-phra-that-lampang-luang',
      'วัดพระธาตุลำปางหลวง (มหัศจรรย์เงาพระธาตุกลับหัวผ่านรูหน้าต่าง)',
      'Wat Phra That Lampang Luang (Camera Obscura Inverted Shadow Stupa)',
      'sacred',
      'ลำปาง (ไทย)',
      'Lampang (Thailand)',
      'เกาะคา',
      'Ko Kha',
      18.2173,
      99.3887,
      'temple_bell',
      'พระธาตุศักดิ์สิทธิ์ประจำปีฉลูแห่งล้านนา ปรากฏปรากฏการณ์มหัศจรรย์ของเงาพระธาตุกลับหัวที่ทอดผ่านรูรับแสงบนบานหน้าต่างไม้โบราณเข้ามาปรากฏบนผืนผ้าใบภายในวิหารพระพุทธอย่างคมชัดโดยไม่ต้องใช้เลนส์กล้อง ตำนานเล่าว่าพระพุทธเจ้าเคยเสด็จมาโปรดและทรงประทานพระเกศาธาตุบรรจุไว้ในองค์พระธาตุ',
      'A venerated northern Thai temple famed for its natural camera obscura miracle: sunlight streaming through a tiny window aperture casts a sharp inverted color projection of the golden pagoda upon a white canvas screen inside the dark wooden vihara.',
      'สร้างขึ้นในสมัยพระนางจามเทวี ราวพุทธศตวรรษที่ 13 ตัววิหารหลวงเป็นสถาปัตยกรรมไม้ล้านนาโบราณที่สมบูรณ์ที่สุดแห่งหนึ่งในประเทศไทย มีซุ้มประตูโขงและวิหารน้ำแต้มที่ยังคงภาพจิตรกรรมฝาผนังโบราณ',
      'Originating in the 8th century during the Hariphunchai era, it remains one of the finest surviving examples of open-sided classic wooden Lanna religious architecture.',
      'สตรีห้ามก้าวขึ้นสู่วิหารพระพุทธบาทซึ่งเป็นจุดชมเงาพระธาตุกลับหัวตามคติโบราณล้านนา',
      'Women are traditionally requested not to enter the elevated Vihara of the Holy Footprint where the inverted projection appears.',
      'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"วัดพระธาตุลำปางหลวง (มหัศจรรย์เงาพระธาตุกลับหัวผ่านรูหน้าต่าง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"พระธาตุหัวกลับ ดูตรงไหน | วัดพระธาตุลำปางหลวง","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-phra-that-cho-hae',
      'วัดพระธาตุช่อแฮ (พระบรมธาตุศักดิ์สิทธิ์ประจำปีขาลแห่งเมืองแพร่)',
      'Wat Phra That Cho Hae (Sacred Year-of-the-Tiger Relic of Phrae)',
      'sacred',
      'แพร่ (ไทย)',
      'Phrae (Thailand)',
      'เมืองแพร่',
      'Mueang Phrae',
      18.0864,
      100.2045,
      'temple_bell',
      'ปูชนียสถานอันศักดิ์สิทธิ์คู่บ้านคู่เมืองแพร่ ประดิษฐานพระเกศาธาตุและพระบรมสารีริกธาตุส่วนข้อศอกซ้ายของพระพุทธเจ้า องค์เจดีย์ศิลปะเชียงแสนทรงแปดเหลี่ยมบุด้วยทองจังโก้เปล่งประกายสีทองอร่ามบนเนินเขาสูง เป็นพระธาตุประจำปีเกิดของผู้ที่เกิดปีขาล (ปีเสือ)',
      'The paramount sacred stupa of Phrae province, enshrine holy hair relics and the left elbow relic of Gautama Buddha. Built in the 8-sided Chiang Saen style and clad in shimmering Jangko brass-gold sheets atop a scenic hill.',
      'ชื่อ ''ช่อแฮ'' มาจากการที่ขุนลัวะอ้ายก้อมได้นำผ้าแพรไหมชั้นดีมาผูกถวายรอบองค์พระธาตุเมื่อครั้งโบราณกาล มีงานประเพณีไหว้พระธาตุช่อแฮ เมืองแพร่แห่ตุงหลวง ในช่วงวันขึ้น 9 ค่ำ ถึง 15 ค่ำ เดือน 4 (หรือเดือน 6 เหนือ) ของทุกปี',
      'Its name derives from fine silk fabrics offered by Lua chieftains to wrap the sacred spire in antiquity, celebrated with grand annual Lanna Tung banner processions.',
      'ห้ามสวมรองเท้าหรือหมวกขึ้นสู่ลานพระธาตุชั้นใน และห้ามกล่าววาจาลบหลู่ต่อดวงวิญญาณเทวดาผู้พิทักษ์องค์พระธาตุ',
      'Remove footwear and hats before treading upon the inner courtyard dais, and refrain from disrespectful speech near the shrine.',
      'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"วัดพระธาตุช่อแฮ (พระบรมธาตุศักดิ์สิทธิ์ประจำปีขาลแห่งเมืองแพร่)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน “พระธาตุช่อแฮ” พระธาตุปีขาล สิ่งศักดิ์สิทธิ์สำคัญคู่เมืองแพร่ I ร้อยเรื่องเมืองล้านนา","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-phra-that-doi-tung',
      'วัดพระธาตุดอยตุง (ปฐมเจดีย์แห่งล้านนาบนยอดดอยสูง)',
      'Wat Phra That Doi Tung (Primordial Lanna Twin Stupas atop Mount Tung)',
      'sacred',
      'เชียงราย (ไทย)',
      'Chiang Rai (Thailand)',
      'แม่สาย',
      'Mae Sai',
      20.3259,
      99.8333,
      'temple_bell',
      'ปฐมบรมธาตุเจดีย์แห่งอาณาจักรล้านนา ประดิษฐานพระบรมสารีริกธาตุส่วนพระรากขวัญเบื้องซ้าย (ไหปลาร้า) ที่พระมหากัสสปะเถระอัญเชิญมาจากอินเดียมาถวายแด่พระเจ้าอชุตราช ตำนานเล่าว่ามีการปักตุง (ธงตะขาบ) ผืนผ้ายาวนับพันวาบนยอดดอย ชายตุงปลิวไปตกที่ใดก็ถือเป็นขอบเขตพุทธสถานศักดิ์สิทธิ์',
      'The ancient twin golden stupas atop Doi Tung mountain enshrining the left collarbone relic of the Buddha brought from India in the 10th century. Named after the colossal royal Tung flags unfurled from the peak across the valley.',
      'พระมหากษัตริย์แห่งล้านนาทุกพระองค์สืบต่อกันมาจะเสด็จขึ้นมานมัสการพระธาตุดอยตุงเพื่อความเป็นสิริมงคล เป็นพระบรมธาตุประจำปีเกิดของผู้ที่เกิดปีกุน (ปีหมู)',
      'A pilgrimage site for northern kings for a millennium, designated as the spiritual guardian relic for those born in the Year of the Pig.',
      'ห้ามทิ้งขยะหรือส่งเสียงเอะอะรบกวนความสงบของลานปฏิบัติธรรมบนยอดดอยศักดิ์สิทธิ์',
      'Maintain meditative silence and reverence upon the high mountain terrace sanctuary.',
      'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"วัดพระธาตุดอยตุง (ปฐมเจดีย์แห่งล้านนาบนยอดดอยสูง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย | พระธาตุดอยตุง ปฐมเจดีย์แห่งล้านนา ศรัทธากลางม่านหมอก","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-phra-that-hariphunchai',
      'วัดพระธาตุหริภุญชัย วรมหาวิหาร (มหาเจดีย์ทองคำโบราณแห่งลำพูน)',
      'Wat Phra That Hariphunchai (Ancient Mon-Lanna Golden Shrine of Lamphun)',
      'sacred',
      'ลำพูน (ไทย)',
      'Lamphun (Thailand)',
      'เมืองลำพูน',
      'Mueang Lamphun',
      18.5772,
      99.0083,
      'temple_bell',
      'มหาเจดีย์สีทองอร่ามสูง 46 เมตรใจกลางเมืองหริภุญชัยโบราณ ประดิษฐานพระบรมเกศาธาตุและพระบรมสารีริกธาตุบรรจุในโกศทองคำ ยอดเจดีย์หุ้มด้วยทองคำแท้หนักหลายกิโลกรัม มีสถาปัตยกรรมล้านนาผสมผสานมอญโบราณที่ผ่านกาลเวลามากว่าพันปี',
      'A monumental 46-meter gilded chedi in the ancient Mon kingdom of Hariphunchai, enshrining holy cranial and hair relics within nested golden caskets, crowned by a solid gold nine-tiered umbrella.',
      'สร้างขึ้นในรัชสมัยพระเจ้าอาทิตยราช กษัตริย์แห่งหริภุญชัยราว พ.ศ. 1440 เป็นพระธาตุประจำปีเกิดของผู้ที่เกิดปีระกา (ปีไก่) มีประเพณีสรงน้ำพระธาตุด้วยน้ำสรงพระราชทานจากยอดดอยขะม้อ',
      'Erected by King Athitayarat in the late 9th century, featuring holy water lustration rites using pure mineral water sourced from Doi Khamo mountain.',
      'ห้ามสตรีก้าวเข้าไปยังฐานพระธาตุชั้นในสุด และห้ามถ่ายภาพในลักษณะลบหลู่ฐานเจดีย์',
      'Women are requested not to enter the inner golden fence perimeter around the central stupa base.',
      'https://i.ytimg.com/vi/eLlsggjp924/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/eLlsggjp924/hqdefault.jpg","title":"วัดพระธาตุหริภุญชัย วรมหาวิหาร (มหาเจดีย์ทองคำโบราณแห่งลำพูน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=eLlsggjp924","title":"เสน่ห์วัดไทย l พระธาตุหริภุญชัย ดวงใจแห่งชาวลำพูน","thumbnail":"https://i.ytimg.com/vi/eLlsggjp924/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-phra-borommathat-chaiya',
      'วัดพระบรมธาตุไชยาราชวรวิหาร (พุทธศิลป์ศรีวิชัยโบราณพันปีแห่งสุราษฎร์ธานี)',
      'Wat Phra Borommathat Chaiya (Millennium Srivijaya Architectural Masterpiece)',
      'sacred',
      'สุราษฎร์ธานี (ไทย)',
      'Surat Thani (Thailand)',
      'ไชยา',
      'Chaiya',
      9.3857,
      99.1989,
      'temple_bell',
      'เจดีย์ทรงปราสาทศิลาทรายแปดเหลี่ยมยอดแหลมตามแบบพุทธศาสนามหายานยุคอาณาจักรศรีวิชัยโบราณที่สมบูรณ์และงดงามที่สุดในคาบสมุทรมาลายู ภายในประดิษฐานพระบรมสารีริกธาตุ ผนังเจดีย์มีซุ้มพระพุทธรูปปูนปั้นโบราณที่รอดพ้นจากการทำลายล้างของศึกสงครามมานับพันปี',
      'The only surviving intact Srivijayan-style pagoda in southern Thailand, dating back over 1,200 years. Its tiered red sandstone stupa showcases intricate Mahayana Buddhist reliefs and enshrines holy Buddha relics.',
      'สันนิษฐานว่าสร้างขึ้นในสมัยที่เมืองไชยาเป็นศูนย์กลางการค้าและพุทธศาสนาของอาณาจักรศรีวิชัยในพุทธศตวรรษที่ 13-14 เป็นสัญลักษณ์ประจำตราจังหวัดสุราษฎร์ธานี',
      'Constructed during the maritime golden age of Srivijaya, serving as the official provincial emblem and spiritual anchor of Surat Thani.',
      'ห้ามขูดขีดหรือสัมผัสซุ้มปูนปั้นโบราณรอบองค์พระธาตุ',
      'Never touch or scratch the ancient terracotta and stucco sculptures adorning the pagoda niche.',
      'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"วัดพระบรมธาตุไชยาราชวรวิหาร (พุทธศิลป์ศรีวิชัยโบราณพันปีแห่งสุราษฎร์ธานี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดอีกมุม 2,140 ปี “พระบรมธาตุไชยา” ที่หลายคนยังไม่รู้","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-san-chao-pho-suea-phra-nakhon',
      'ศาลเจ้าพ่อเสือ พระนคร (ตั่วเหล่าเอี๊ย เสาชิงช้า ศูนย์รวมศรัทธาปราบสิ่งอัปมงคล)',
      'San Chao Pho Suea (Tiger God Shrine of Phra Nakhon)',
      'sacred',
      'กรุงเทพมหานคร (ไทย)',
      'Bangkok (Thailand)',
      'พระนคร',
      'Phra Nakhon',
      13.7537,
      100.4983,
      'temple_bell',
      'ศาลเจ้าจีนแต้จิ๋วโบราณที่เก่าแก่และทรงอิทธิฤทธิ์ที่สุดแห่งหนึ่งในเกาะรัตนโกสินทร์ ประดิษฐาน ''เหี่ยงเทียนเสี่ยงตี่'' (เจ้าพ่อกวนอูและเจ้าพ่อเสือ) ผู้คนหลั่งไหลมากราบไหว้ขอพรด้านการงาน ปัดเป่าเภทภัย และสะเดาะเคราะห์แก้ปีชงด้วยเนื้อหมูสามชั้นสด ไข่ไก่ และข้าวเหนียวหวาน',
      'One of Bangkok''s oldest and most powerful Teochew Chinese shrines, enshrining the Xuanwu (Tiger Deity). Pilgrims bring offerings of raw pork, eggs, and sweet sticky rice to neutralize misfortune, ward off malevolent spirits, and seek career prosperity.',
      'เดิมตั้งอยู่บริเวณถนนบำรุงเมืองตั้งแต่สมัยรัชกาลที่ 3 ต่อมาในรัชสมัยรัชกาลที่ 5 ได้ทรงโปรดเกล้าฯ ให้ขยายถนน จึงย้ายศาลมาประดิษฐาน ณ บริเวณถนนตะนาว ใกล้เสาชิงช้าจนถึงปัจจุบัน',
      'Established during the reign of King Rama III and relocated to Tanao Road under King Rama V, celebrated for centuries as Bangkok''s premier talismanic protection nexus.',
      'ห้ามก้าวข้ามธรณีประตูศาลเจ้า และควรไหว้เทวดาฟ้าดิน (ทีกง) ก่อนเข้าไปสักการะองค์เทพภายใน',
      'Never step upon the raised wooden entrance threshold, and pay reverence to the Sky Deity altar before entering.',
      'https://i.ytimg.com/vi/MtX3U0SmzVM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/MtX3U0SmzVM/hqdefault.jpg","title":"ศาลเจ้าพ่อเสือ พระนคร (ตั่วเหล่าเอี๊ย เสาชิงช้า ศูนย์รวมศรัทธาปราบสิ่งอัปมงคล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=MtX3U0SmzVM","title":"เรื่องเล่าวันนี้ : ตำนานศาลเจ้าพ่อเสือ \"เสือยอดกตัญญู\"","thumbnail":"https://i.ytimg.com/vi/MtX3U0SmzVM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-leng-noei-yi-yaowarat',
      'วัดมังกรกมลาวาส (วัดเล่งเน่ยยี่ วัดจีนศูนย์กลางสะเดาะเคราะห์แก้ชงเยาวราช)',
      'Wat Mangkon Kamalawat (Wat Leng Noei Yi Yaowarat)',
      'sacred',
      'กรุงเทพมหานคร (ไทย)',
      'Bangkok (Thailand)',
      'สัมพันธวงศ์',
      'Samphanthawong',
      13.7436,
      100.5097,
      'temple_bell',
      'ปฐมอารามฝ่ายจีนนิกายที่ใหญ่ที่สุดในย่านเยาวราช สร้างขึ้นตามหลักฮวงจุ้ยมังกรอันทรงพลัง ประดิษฐานพระพุทธเจ้า 3 พระองค์ (ซำปอฮุกโจ้ว) และทวยเทพจีนกว่า 58 องค์ รวมถึงเทพเจ้าไท้ส่วยเอี๊ย ผู้คุ้มครองดวงชะตาชีวิตประจำปีเกิด',
      'Bangkok''s premier and largest Chinese Mahayana Buddhist temple on Yaowarat Road, constructed on the mythical Dragon''s belly geomantic meridian, housing 58 Taoist and Buddhist deities including Tai Sui, the Grand Duke of Jupiter guardian of destiny.',
      'สร้างขึ้นในสมัยรัชกาลที่ 5 เมื่อปี พ.ศ. 2414 โดยพระยาโชฎึกราชเศรษฐีและพ่อค้าชาวจีน ได้รับพระราชทานนามว่า ''วัดมังกรกมลาวาส'' มีเทศกาลตรุษจีนและพิธีแก้ชงที่คึกคักที่สุดในประเทศไทย',
      'Founded in 1871 under the royal patronage of King Chulalongkorn, renowned as the undisputed center of annual Chinese New Year astrological purification rituals.',
      'ห้ามนำสิ่งของมัวหมองเข้าสู่อาราม และห้ามปักธูปกลับหัว',
      'Do not plant incense sticks upside down, and maintain decorum inside the main sanctum.',
      'https://i.ytimg.com/vi/j3A6iDfF-eI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/j3A6iDfF-eI/hqdefault.jpg","title":"วัดมังกรกมลาวาส (วัดเล่งเน่ยยี่ วัดจีนศูนย์กลางสะเดาะเคราะห์แก้ชงเยาวราช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j3A6iDfF-eI","title":"วัดมังกรกมลาวาส ( วัดเล่งเน่ยยี่)","thumbnail":"https://i.ytimg.com/vi/j3A6iDfF-eI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-wat-chalong-luang-phor-cham',
      'วัดฉลองและบารมีหลวงพ่อแช่ม (พระมหาเกจิผู้ปราบอั้งยี่คุ้มครองเกาะภูเก็ต)',
      'Wat Chalong and Luang Phor Cham (Sacred Guardian Abbot of Phuket)',
      'sacred',
      'ภูเก็ต (ไทย)',
      'Phuket (Thailand)',
      'เมืองภูเก็ต',
      'Mueang Phuket',
      7.8464,
      98.3371,
      'temple_bell',
      'วัดคู่บ้านคู่เมืองภูเก็ตอันเป็นที่พำนักของ ''หลวงพ่อแช่ม'' พระเกจิอาจารย์ผู้มีวิชาอาคมแก่กล้า ผู้ปลุกเสกผ้าประเจียดสีขาวมอบให้ชาวบ้านสวมใส่ต่อสู้กับกบฏอั้งยี่ (กบฏกรรมกรเหมืองแร่ดีบุก) จนได้รับชัยชนะอย่างน่าอัศจรรย์ ผู้คนนิยมมาจุดประทัดแก้บนจนดังก้องลานวัดตลอดทั้งวัน',
      'The grandest temple in Phuket honoring revered Abbot Luang Phor Cham, who consecrated protective white talismans enabling local villagers to repel violent tin-mine rebellions in 1876. Celebrated by continuous fireworks offerings echoing across the sacred pagoda.',
      'พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว รัชกาลที่ 5 ทรงพระราชทานสมณศักดิ์ให้เป็น ''พระครูวิสุทธิวงศาจารย์ญาณมุนี'' มีพระมหาธาตุเจดีย์พระจอมไทยบารมีประกาศประดิษฐานพระบรมสารีริกธาตุจากศรีลังกา',
      'Bestowed royal honors by King Rama V, the temple complex features the Great Holy Stupa enshrining bone relics gifted from Sri Lanka.',
      'ห้ามสวมกางเกงขาสั้นหรือเสื้อสายเดี่ยวเข้าไปในพระมหาเจดีย์ และห้ามนำสัตว์เลี้ยงเข้ามาในเขตศาสนสถาน',
      'Modest attire covering shoulders and knees is strictly mandatory when ascending the grand relic chedi.',
      'https://i.ytimg.com/vi/JMR4smlsqwc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/JMR4smlsqwc/hqdefault.jpg","title":"วัดฉลองและบารมีหลวงพ่อแช่ม (พระมหาเกจิผู้ปราบอั้งยี่คุ้มครองเกาะภูเก็ต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=JMR4smlsqwc","title":"Ep.1 ประวัติหลวงพ่อแช่มวัดฉลองภูเก็ต","thumbnail":"https://i.ytimg.com/vi/JMR4smlsqwc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-khao-khitchakut-footprint',
      'เขาคิชฌกูฏ (รอยพระพุทธบาทศักดิ์สิทธิ์บนยอดผาหินลอยฟ้าแห่งจันทบุรี)',
      'Khao Khitchakut Buddha Footprint (Sacred High-Altitude Granite Sanctum)',
      'sacred',
      'จันทบุรี (ไทย)',
      'Chanthaburi (Thailand)',
      'เขาคิชฌกูฏ',
      'Khao Khitchakut',
      12.8278,
      102.1486,
      'temple_bell',
      'ยอดเขาสูงชันกว่า 1,000 เมตรจากระดับน้ำทะเล ที่ประดิษฐานรอยพระพุทธบาทบนแผ่นศิลาทรายธรรมชาติเคียงข้างก้อนหินยักษ์ทรงกลม ''หินลูกบาตร'' ที่ตั้งตระหง่านอยู่ริมหน้าผาได้อย่างอัศจรรย์โดยไม่ตกลงมา ผู้แสวงบุญนับแสนคนต่างเดินทางมาเดินเท้าฝ่าความสูงชันในคืนวันเพ็ญเพื่อขอพรที่เชื่อว่าจะสัมฤทธิผลเพียง 1 ข้อ',
      'A revered natural granite footprint perched over 1,000 meters above sea level beside the miraculous ''Hin Luk Bat''—a massive gravity-defying spherical boulder balancing on the precipice edge. Open only during the annual spring pilgrimage season.',
      'เปิดให้ขึ้นสักการะปีละครั้งเพียง 2 เดือนเท่านั้น (ช่วงเทศกาลตรุษจีนถึงวันมาฆบูชา) เชื่อกันว่าการขึ้นไปกราบไหว้ด้วยความเพียรพยายามเสมือนการเข้าเฝ้าพระพุทธองค์บนยอดสวรรค์',
      'Thousands ascend through misty mountain switchbacks under starlight to scatter yellow marigold petals across the stone impression.',
      'ห้ามขอพรอธิษฐานเกิน 1 ข้อ และห้ามทิ้งสิ่งของลงสู่หน้าผาหินลูกบาตร',
      'Pilgrims are traditionally instructed to focus their prayers on a single heartfelt wish and never cast items over the sacred drop.',
      'https://i.ytimg.com/vi/TsLbkkvG8KI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TsLbkkvG8KI/hqdefault.jpg","title":"เขาคิชฌกูฏ (รอยพระพุทธบาทศักดิ์สิทธิ์บนยอดผาหินลอยฟ้าแห่งจันทบุรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TsLbkkvG8KI","title":"ตำนานรอยพระพุทธบาทเขาคิชฌกูฏ นมัสการรอยพระพุทธบาทพลวง เขาคิชฌกูฏ จันทบุรี","thumbnail":"https://i.ytimg.com/vi/TsLbkkvG8KI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-shwedagon-pagoda',
      'พระมหาธาตุเจดีย์ชเวดากอง (มหาเจดีย์ทองคำหุ้มเพชรยอดมงกุฎแห่งย่างกุ้ง)',
      'Shwedagon Pagoda (The 2,500-Year Golden Reliquary of Yangon)',
      'sacred',
      'ย่างกุ้ง (พม่า)',
      'Yangon (Myanmar)',
      'ดากอง',
      'Dagon',
      16.7983,
      96.1497,
      'temple_bell',
      'มหาเจดีย์ทองคำแท้ที่ยิ่งใหญ่ที่สุดในโลก สูง 99 เมตร เปล่งประกายสีทองอร่ามบนเนินเขาสิงคุตตระ องค์เจดีย์หุ้มด้วยแผ่นทองคำแท้นับหมื่นแผ่น ยอดฉัตรประดับด้วยเพชรแท้เม็ดใหญ่ขนาด 76 กะรัต และอัญมณีนับหมื่นชิ้น ภายในบรรจุพระเกศาธาตุ 8 เส้นของพระโคตมพุทธเจ้าและบริขารของอดีตพระพุทธเจ้าอีก 3 พระองค์',
      'A 99-meter-tall sovereign pagoda plated with genuine gold plates and crowned with a 76-carat diamond. Enshrines eight strands of hair from Gautama Buddha alongside relics of three previous Buddhas, radiating celestial gold across Yangon.',
      'ตามตำนานสร้างขึ้นเมื่อกว่า 2,500 ปีก่อนโดยสองพ่อค้าพี่น้อง ตปุสสะและภัลลิกะ ที่ได้รับพระราชทานพระเกศาธาตุจากพระพุทธองค์ ถือเป็นศูนย์รวมจิตวิญญาณสูงสุดของชาวพม่า',
      'According to Mon oral tradition, founded by merchant brothers Tapussa and Bhallika upon receiving hair relics directly from the newly enlightened Buddha.',
      'ต้องถอดรองเท้าและถุงเท้าตั้งแต่ก้าวแรกที่บันไดทางขึ้น และต้องเดินเวียนขวา (ทักษิณาวรรต) รอบองค์เจดีย์',
      'All visitors must remove shoes and socks at the temple entrance and circumambulate clockwise.',
      'https://i.ytimg.com/vi/Sghv2U1BROY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Sghv2U1BROY/hqdefault.jpg","title":"พระมหาธาตุเจดีย์ชเวดากอง (มหาเจดีย์ทองคำหุ้มเพชรยอดมงกุฎแห่งย่างกุ้ง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Sghv2U1BROY","title":"ชเวดากอง พระมหาเจดีย์ทองคำศูนย์กลางการจาริกแสวงบุญ แดนสวรรค์ผู้มาเยือน","thumbnail":"https://i.ytimg.com/vi/Sghv2U1BROY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-kyaiktiyo-golden-rock',
      'พระธาตุอินทร์แขวน ไจก์ทิโย (ก้อนหินทองคำลอยริมขอบหน้าผาแห่งรัฐมอญ)',
      'Kyaiktiyo Golden Rock (The Miraculous Gravity-Defying Boulder of Mon)',
      'sacred',
      'รัฐมอญ (พม่า)',
      'Mon State (Myanmar)',
      'ไจก์โท',
      'Kyaikhto',
      17.4819,
      97.0981,
      'temple_bell',
      'ก้อนหินแกรนิตขนาดยักษ์ทรงกลมปิดทองคำเปลวอร่าม ตั้งหมิ่นเหม่ท้าทายแรงโน้มถ่วงอยู่บนริมขอบหน้าผาสูงชันกว่า 1,100 เมตร โดยมีจุดสัมผัสผาหินเพียงเล็กน้อยจนสามารถสอดเส้นด้ายผ่านได้ ตำนานเล่าว่าพระอินทร์ได้นำก้อนหินนี้มาจากใต้บาดาลและนำมาตั้งไว้ โดยมีพระเกศาธาตุของพระพุทธเจ้าค้ำยันไม่ให้หินตกลงไป',
      'A 25-foot gilded granite boulder perched precariously upon an inclined rock cliff edge 1,100 meters high, defying gravity. Legend says it is held in eternal equilibrium by a single precisely placed holy hair relic gifted by an ascetic monk.',
      'เป็น 1 ใน 5 มหาบูชาสถานศักดิ์สิทธิ์สูงสุดของพม่า ผู้ศรัทธาเชื่อว่าหากได้ขึ้นไปปิดทองและอธิษฐานครบ 3 ครั้งจะนำพาความสำเร็จและพ้นจากเคราะห์กรรมทั้งปวง',
      'One of Myanmar''s top Buddhist pilgrimage destinations, enveloped in perpetual highland mists and the scent of burning prayer candles.',
      'สตรีห้ามสัมผัสหรือเข้าไปปิดทองบนก้อนหินพระธาตุโดยเด็ดขาด',
      'Women are strictly prohibited from touching the sacred golden boulder or entering the innermost terrace.',
      'https://i.ytimg.com/vi/tM22TbcrK0M/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/tM22TbcrK0M/hqdefault.jpg","title":"พระธาตุอินทร์แขวน ไจก์ทิโย (ก้อนหินทองคำลอยริมขอบหน้าผาแห่งรัฐมอญ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=tM22TbcrK0M","title":"ไขความลับ!หินศักดิ์สิทธิ์ พระธาตุอินทร์แขวน ความเชื่อและวิทยาศาสตร์ตำนานเรื่องเล่าพลังแห่งปาฏิหาริย์","thumbnail":"https://i.ytimg.com/vi/tM22TbcrK0M/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-vat-phou-champasak',
      'ปราสาทหินวัดพู (มรดกโลกเทวสถานขอมโบราณใต้เงาภูเกล้า จำปาสัก)',
      'Vat Phou Champasak (Ancient Khmer Sanctuary of Mount Phu Kao)',
      'sacred',
      'จำปาสัก (ลาว)',
      'Champasak (Laos)',
      'เมืองจำปาสัก',
      'Champasak',
      14.8489,
      105.8175,
      'temple_bell',
      'เทวสถานขอมโบราณอายุเก่าแก่กว่านครวัด สร้างขึ้นตามไหล่เขาภูเกล้า (ลิงคบรรพต) ซึ่งมียอดเขาธรรมชาติคล้ายศิวลึงค์ศักดิ์สิทธิ์ มีทางเดินหินทรายโบราณขนาบด้วยเสานางเรียงทอดยาวสู่ลานเทวาลัยชั้นบนที่สายน้ำแร่ธรรมชาติไหลผ่านศิวลึงค์หล่อเลี้ยงผู้คนมาช้านาน',
      'A pre-Angkorian Khmer Hindu temple sanctuary dating back to the 5th century, built along the terraced slopes of Mount Phu Kao, whose natural peak resembles a Shiva lingam.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกโดยยูเนสโก เดิมเป็นเทวสถานในศาสนาฮินดูไศวนิกาย ก่อนจะเปลี่ยนผ่านสู่พุทธสถานเถรวาทในสมัยอาณาจักรล้านช้าง มีงานเทศกาลวัดพูในคืนวันเพ็ญเดือน 3',
      'UNESCO World Heritage site demonstrating the fusion of early Cham and Khmer engineering aligned with celestial equinox axes.',
      'ห้ามปีนป่ายซากศิลาแกะสลักรูปนางอัปสราหรือศิวลึงค์โบราณ',
      'Never climb upon ancient carved sandstone lintels or sacred lingam pedestals.',
      'https://i.ytimg.com/vi/3FoGe9Em4RA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/3FoGe9Em4RA/hqdefault.jpg","title":"ปราสาทหินวัดพู (มรดกโลกเทวสถานขอมโบราณใต้เงาภูเกล้า จำปาสัก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=3FoGe9Em4RA","title":"ปราสาทวัดพูอันเก่าแก่  ความมหัศจรรย์ทางธรรมชาติของหลี่ผี คอนพะเพ็ง I ประวัติศาสตร์นอกตำรา EP.84","thumbnail":"https://i.ytimg.com/vi/3FoGe9Em4RA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-banteay-srei-cambodia',
      'ปราสาทบันทายศรี (เพชรน้ำเอกแห่งศิลปะขอมโบราณหินทรายสีชมพู เสียมราฐ)',
      'Banteay Srei (The Citadel of Women & Pink Sandstone Jewel of Angkor)',
      'sacred',
      'เสียมราฐ (กัมพูชา)',
      'Siem Reap (Cambodia)',
      'บันทายศรี',
      'Banteay Srei',
      13.5989,
      103.9631,
      'temple_bell',
      'เทวสถานขอมโบราณขนาดกะทัดรัดที่สร้างจากหินทรายสีชมพูเนื้อละเอียด ลวดลายแกะสลักคมชัดอ่อนช้อยประณีตจนได้รับการขนานนามว่าเป็น ''เพชรน้ำเอกแห่งศิลปะอังกอร์'' ภาพสลักทศกัณฐ์เขย่าเขาไกรลาสและนางเทพอัปสรมีความวิจิตรตระการตาดุจสลักบนเนื้อไม้',
      'A 10th-century Hindu temple dedicated to Lord Shiva, carved from hard rose-pink sandstone that enables microscopic bas-relief detail depicting epics of the Ramayana and Mahabharata.',
      'สร้างขึ้นในรัชสมัยพระเจ้าราเชนทรวรมันที่ 2 โดยพราหมณ์ยัชญวราหะ มิได้สร้างโดยกษัตริย์ จึงมีสเกลที่ย่อมเยาแต่เปี่ยมด้วยจิตวิญญาณแห่งศิลปะชั้นสูง',
      'Consecrated in 967 CE by Brahmin scholar Yajnavaraha, revered as the pinnacle of classical Khmer sculptural mastery.',
      'ห้ามใช้มือลูบคลำรอยแกะสลักหินทรายสีชมพูเพื่อป้องกันการกัดกร่อนจากไขมันผิวหนัง',
      'Refrain from touching the delicate pink sandstone carvings to preserve the ancient relief details.',
      'https://i.ytimg.com/vi/JG6-NS3rDkg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/JG6-NS3rDkg/hqdefault.jpg","title":"ปราสาทบันทายศรี (เพชรน้ำเอกแห่งศิลปะขอมโบราณหินทรายสีชมพู เสียมราฐ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=JG6-NS3rDkg","title":"เสน่ห์มนตรา \"ปราสาทบันทายชมาร์\"  I ท่องเที่ยวนอกตำรา  EP.1    I ประวัติศาสตร์นอกตำรา EP.223","thumbnail":"https://i.ytimg.com/vi/JG6-NS3rDkg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-pura-besakih-mother-temple',
      'ปุระเบซากีห์ (มหาเทวสถานแม่แห่งบาหลีบนเชิงภูเขาไฟอากุง)',
      'Pura Besakih (The Mother Temple of Bali on Mount Agung)',
      'sacred',
      'บาหลี (อินโดนีเซีย)',
      'Bali (Indonesia)',
      'การังอาเซม',
      'Karangasem',
      -8.3742,
      115.4508,
      'temple_bell',
      'มหาเทวสถานฮินดูที่ใหญ่และศักดิ์สิทธิ์ที่สุดบนเกาะบาหลี ประกอบด้วยวิหารย่อยกว่า 86 หลังเรียงลดหลั่นขึ้นไปตามไหล่เขาภูเขาไฟอากุง เมื่อคราวภูเขาไฟอากุงระเบิดครั้งใหญ่ในปี 1963 ลาวาไหลผ่านเฉียดวิหารไปเพียงไม่กี่เมตรอย่างน่าอัศจรรย์โดยไม่ทำลายเทวสถาน',
      'The Mother Temple of Balinese Hinduism, an expansive terraced sanctuary of 23 interconnected temples climbing the misty slopes of Mount Agung. Miraculously spared by flowing lava during the catastrophic 1963 volcanic eruption.',
      'มีอายุย้อนไปกว่าพันปี สถาปัตยกรรมหอคอยหลังคาเมรุหลายชั้นมุงด้วยเส้นใยต้นตาลสีดำขลับ สะท้อนการเชื่อมต่อระหว่างมนุษย์ บรรพบุรุษ และเทพเจ้าแห่งจักรวาล',
      'Dating back to the 8th century, serving as the cosmic focal point for all Balinese ceremonies honoring the Trimurti deities.',
      'ต้องนุ่งผ้าโสร่งและคาดผ้ารัดเอว (เสเลนดัง) อย่างสุภาพเรียบร้อยก่อนเข้าสู่เขตเทวสถาน',
      'All visitors must wear traditional sarong and sash drapery before entering the consecrated temple grounds.',
      'https://i.ytimg.com/vi/GZ_8C6ITJOs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/GZ_8C6ITJOs/hqdefault.jpg","title":"ปุระเบซากีห์ (มหาเทวสถานแม่แห่งบาหลีบนเชิงภูเขาไฟอากุง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=GZ_8C6ITJOs","title":"ปุราเบซากิห์ PuraBesakih |วัดเบซากิห์​ |วัดหลวง​ #บาหลี","thumbnail":"https://i.ytimg.com/vi/GZ_8C6ITJOs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-pura-tanah-lot',
      'ปุระตานะฮ์ลอต (วิหารหินศักดิ์สิทธิ์กลางเกลียวคลื่นทะเลบาหลี)',
      'Pura Tanah Lot (Sacred Oceanic Rock Sanctuary of Bali)',
      'sacred',
      'บาหลี (อินโดนีเซีย)',
      'Bali (Indonesia)',
      'ตาบานัน',
      'Tabanan',
      -8.6212,
      115.0868,
      'temple_bell',
      'วิหารหินโบราณที่ตั้งตระหง่านอยู่บนโขดหินยักษ์กลางทะเลอันดามัน ยามน้ำขึ้นวิหารจะถูกตัดขาดกลายเป็นเกาะลอยกลางเกลียวคลื่นซัดสาด ตำนานเล่าว่านักบวชดังฮยัง นิราร์ธา ได้สร้างวิหารนี้ขึ้นและได้เปลี่ยนสายรัดเอวให้กลายเป็นงูทะเลศักดิ์สิทธิ์คอยพิทักษ์เทวสถานจากปีศาจร้ายใต้ก้นสมุทร',
      'An iconic Balinese sea temple perched on an offshore rock formation constantly carved by ocean waves. Legend claims the founding sage created venomous sea snakes from his sash to guard the sanctuary from dark oceanic entities.',
      'สร้างขึ้นในคริสต์ศตวรรษที่ 16 เป็นหนึ่งใน 7 วิหารริมทะเลศักดิ์สิทธิ์ที่เชื่อมโยงกันเป็นแนวกำแพงเวทมนตร์คุ้มครองเกาะบาหลี มีตาน้ำจืดธรรมชาติผุดขึ้นกลางโขดหินริมทะเลอย่างน่าอัศจรรย์',
      'One of seven sea temples along the southwestern Balinese coast, renowned for its holy freshwater spring emerging miraculously from sea rocks.',
      'ห้ามบุกรุกขึ้นไปยังตัววิหารหลักด้านบนซึ่งสงวนไว้เฉพาะผู้ประกอบพิธีกรรมทางศาสนาเท่านั้น',
      'Entry to the elevated inner sanctum is strictly reserved for Hindu devotees during ceremonial prayer.',
      'https://i.ytimg.com/vi/VQzErsHypbg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/VQzErsHypbg/hqdefault.jpg","title":"ปุระตานะฮ์ลอต (วิหารหินศักดิ์สิทธิ์กลางเกลียวคลื่นทะเลบาหลี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=VQzErsHypbg","title":"เที่ยวบาหลี ดีต่อใจ ชมวิหารทานาล็อต ข้ามเรือไปเกาะนูซา เปนิดา เที่ยวชมวิหารทานาล็อต วิหารกลางน้ำ","thumbnail":"https://i.ytimg.com/vi/VQzErsHypbg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-golden-temple-amritsar',
      'วิหารทองคำศรีหริมันทิรซาฮิบ (ศูนย์รวมจิตวิญญาณแห่งชาวซิกข์ อมฤตสาร์)',
      'The Golden Temple of Amritsar (Sri Harmandir Sahib)',
      'sacred',
      'ปัญจาบ (อินเดีย)',
      'Punjab (India)',
      'อมฤตสาร์',
      'Amritsar',
      31.62,
      74.8765,
      'temple_bell',
      'วิหารหินอ่อนสีขาวบริสุทธิ์หุ้มด้วยทองคำแท้บริสุทธิ์นับร้อยกิโลกรัม ตั้งตระหง่านอยู่ใจกลางสระน้ำศักดิ์สิทธิ์ ''อมฤตสโรวาร์'' (สระน้ำแห่งน้ำอมฤต) ประดิษฐานคัมภีร์คุรุครันถ์ซาฮิบ มีเสียงสวดมนต์ก้องกังวานตลอด 24 ชั่วโมง และมีโรงครัวทาน (ลังการ์) ที่แจกอาหารฟรีแก่ผู้คนทุกศาสนานับแสนคนต่อวัน',
      'The holiest gurdwara of Sikhism, plated with 500 kilograms of pure gold foil, resting serenely in the center of the ''Amrit Sarovar'' (Pool of Nectar). Open to people of all castes and creeds, operating the world''s largest free community kitchen.',
      'ริเริ่มสร้างโดยคุรุรามดาส คุรุองค์ที่ 4 แห่งศาสนาซิกข์ และสร้างเสร็จในสมัยคุรุอรชุนในปี 1604 สถาปัตยกรรมเปิดประตูทั้ง 4 ทิศสื่อถึงการต้อนรับมวลมนุษยชาติอย่างเท่าเทียม',
      'Completed in 1604 with entrances on all four sides, embodying universal egalitarianism and selfless communal service.',
      'ผู้เข้าชมทุกคนต้องโพกผ้าคลุมศีรษะ ถอดรองเท้า ล้างเท้าในบ่อน้ำบริสุทธิ์ และห้ามพกพาแอลกอฮอล์หรือยาสูบเด็ดขาด',
      'Covering the head and washing feet before stepping onto the marble causeway is strictly mandatory; tobacco and alcohol are forbidden.',
      'https://i.ytimg.com/vi/c6-ezVme-yI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/c6-ezVme-yI/hqdefault.jpg","title":"วิหารทองคำศรีหริมันทิรซาฮิบ (ศูนย์รวมจิตวิญญาณแห่งชาวซิกข์ อมฤตสาร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=c6-ezVme-yI","title":"สุวรรณวิหาร เมืองอัมริตสาร์ สัญลักษณ์แห่งศรัทธาของชาวซิกข์ทั้งมวล    I ประวัติศาสตร์นอกตำรา EP. 73","thumbnail":"https://i.ytimg.com/vi/c6-ezVme-yI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-meenakshi-temple-madurai',
      'มหาวิหารมีนากษีอัมมัน (วิหารพันเสาและประติมากรรมเทวรูปหมื่นองค์ มทุไร)',
      'Meenakshi Amman Temple (The Vibrant Dravidian Gopuram Wonder of Madurai)',
      'sacred',
      'ทมิฬนาฑู (อินเดีย)',
      'Tamil Nadu (India)',
      'มทุไร',
      'Madurai',
      9.9195,
      78.1193,
      'temple_bell',
      'มหัศจรรย์แห่งสถาปัตยกรรมดราวิเดียนโบราณใจกลางเมืองมทุไร โดดเด่นด้วยซุ้มโคปุรัม (หอคอยทางเข้า) ทรงปิรามิด 14 หลังสูงเสียดฟ้าที่ประดับประดาด้วยประติมากรรมปูนปั้นทวยเทพ อสูร และสัตว์หิมพานต์ลงสีสันสดใสกว่า 33,000 องค์ ภายในมีห้องโถงพันเสาที่แกะสลักจากหินแกรนิตก้อนเดียว',
      'A colossal Dravidian temple complex dominated by 14 monumental gopuram gateway towers adorned with over 33,000 multi-colored stucco figures of Hindu deities, mythical beasts, and celestial warriors.',
      'อุทิศแด่พระแม่มีนากษี (อวตารของพระปารวตี) และพระสุนทเรศวร (พระศิวะ) ตำนานเล่าว่าเมืองมทุไรก่อตั้งขึ้นตามหยาดน้ำอมฤตที่หยดลงมาจากมวยผมของพระศิวะ',
      'A historic pilgrimage city mentioned in classical Sangam literature dating back over 2,500 years, active day and night with sacred processions.',
      'ห้ามนำอุปกรณ์อิเล็กทรอนิกส์หรือกล้องถ่ายรูปเข้าไปในเขตวิหารชั้นในสุด',
      'Mobile phones and cameras are prohibited inside the innermost sanctum shrines.',
      'https://i.ytimg.com/vi/te52lqxHwzM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/te52lqxHwzM/hqdefault.jpg","title":"มหาวิหารมีนากษีอัมมัน (วิหารพันเสาและประติมากรรมเทวรูปหมื่นองค์ มทุไร)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=te52lqxHwzM","title":"Madurai''s Meenakshi Amman, the deity who fulfills wishes! | Meenakshi Amman & The Marvel Of Madurai","thumbnail":"https://i.ytimg.com/vi/te52lqxHwzM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-todaiji-great-buddha',
      'วัดโทไดจิ (มหาวิหารไม้ที่ใหญ่ที่สุดในโลกและพระพุทธรูปไดบุตสึ นารา)',
      'Todai-ji (Great Eastern Temple & Daibutsu Colossus of Nara)',
      'sacred',
      'นารา (ญี่ปุ่น)',
      'Nara (Japan)',
      'นารา',
      'Nara',
      34.6901,
      135.8398,
      'temple_bell',
      'มหาวิหารไม้โบราณที่ใหญ่ที่สุดในโลก (ไดบุตสึเด็ง) ประดิษฐานพระพุทธรูปสัมฤทธิ์ ''ไดบุตสึ'' (พระไวโรจนะพุทธเจ้า) สูง 15 เมตร หนักกว่า 500 ตัน ภายในวิหารมีเสาไม้ขนาดยักษ์ที่มีรูเจาะลอดผ่านได้ ซึ่งเชื่อกันว่าใครสามารถมุดผ่านรูเสานี้ได้จะพบกับความโชคดีและบรรลุธรรม',
      'The world''s largest historic wooden building housing Japan''s colossal 15-meter bronze Daibutsu (Vairocana Buddha). Famous for its interior pillar with a hole matching the statue''s nostril, granting spiritual enlightenment to those who crawl through.',
      'สร้างขึ้นในรัชสมัยจักรพรรดิโชมุเมื่อปี ค.ศ. 752 เพื่อปกป้องประเทศจากโรคระบาดและภัยธรรมชาติ ลานวัดมีฝูงกวางชิกะศักดิ์สิทธิ์เดินเพ่นพ่านอย่างอิสระตามความเชื่อว่าเป็นผู้ส่งสารของเทพเจ้า',
      'Consecrated in 752 CE during the Nara period, surrounded by thousands of free-roaming sacred sika deer regarded as celestial messengers.',
      'ห้ามใช้แฟลชถ่ายภาพองค์พระพุทธรูปไดบุตสึ และห้ามทำร้ายฝูงกวางศักดิ์สิทธิ์',
      'No flash photography directed at the ancient bronze icon, and treat the sacred temple deer with gentleness.',
      'https://i.ytimg.com/vi/1p-ysPxqNo8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/1p-ysPxqNo8/hqdefault.jpg","title":"วัดโทไดจิ (มหาวิหารไม้ที่ใหญ่ที่สุดในโลกและพระพุทธรูปไดบุตสึ นารา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=1p-ysPxqNo8","title":"อัพเดทวัดหลวงพ่อโต อาคารไม้ใหญ่ที่สุดในโลกจริงหรือ? วัดโทไดจิ เที่ยวญี่ปุ่น นารา Todaiji temple NARA","thumbnail":"https://i.ytimg.com/vi/1p-ysPxqNo8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-fushimi-inari-taisha',
      'ศาลเจ้าฟูชิมิอินาริ (หมื่นเสาโทริอิสีแดงชาดและเทพอินาริสุนัขจิ้งจอก เกียวโต)',
      'Fushimi Inari-Taisha (Ten Thousand Vermilion Torii Gates of Kyoto)',
      'sacred',
      'เกียวโต (ญี่ปุ่น)',
      'Kyoto (Japan)',
      'ฟูชิมิ',
      'Fushimi',
      34.9671,
      135.7727,
      'temple_bell',
      'ศาลเจ้าชินโตที่มีชื่อเสียงที่สุดในญี่ปุ่น โดดเด่นด้วย ''เซ็มบงโทริอิ'' หรืออุโมงค์เสาโทริอิสีแดงชาดกว่าหมื่นต้นที่ทอดยาวคดเคี้ยวขึ้นสู่ยอดเขาอินาริศักดิ์สิทธิ์ ประดิษฐานเทพอินาริ เทพเจ้าแห่งความอุดมสมบูรณ์ ข้าว และธุรกิจ มีรูปปั้นสุนัขจิ้งจอก (คิตสึเนะ) คาบรวงข้าวหรือลูกแก้วคอยพิทักษ์อยู่ทุกหนแห่ง',
      'The head shrine of Inari, the Shinto deity of agriculture and business prosperity, featuring an awe-inspiring labyrinth of over 10,000 vermilion torii gates winding up the sacred forested mountain, guarded by white stone fox messengers.',
      'ก่อตั้งขึ้นเมื่อปี ค.ศ. 711 ก่อนที่เกียวโตจะกลายเป็นเมืองหลวงของญี่ปุ่น เสาโทริอิแต่ละต้นมาจากการบริจาคของพ่อค้าและบริษัทธุรกิจเพื่อขอความสำเร็จและความเจริญรุ่งเรือง',
      'Established in 711 CE, each vermilion gate is inscribed with the donor''s name celebrating gratitude for fulfilled prayers and commercial triumph.',
      'ห้ามขีดเขียนลงบนเสาโทริอิ และห้ามเดินนอกเส้นทางเดินป่าศักดิ์สิทธิ์ยามวิกาล',
      'Never deface or scratch the sacred torii wood, and stay on the designated mountain trail after dark.',
      'https://i.ytimg.com/vi/TyInTq1lMbs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TyInTq1lMbs/hqdefault.jpg","title":"ศาลเจ้าฟูชิมิอินาริ (หมื่นเสาโทริอิสีแดงชาดและเทพอินาริสุนัขจิ้งจอก เกียวโต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TyInTq1lMbs","title":"เอ่อ แปลกดี : ตำนาน “เสาแดงหมื่นต้น ศาลเจ้าฟุชิมิ อินะริ ไทฉะ”","thumbnail":"https://i.ytimg.com/vi/TyInTq1lMbs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-st-peters-basilica-vatican',
      'มหาวิหารนักบุญเปโตร (ศูนย์กลางแห่งคริสตจักรโรมันคาทอลิก นครวาติกัน)',
      'St. Peter''s Basilica (The Papal Heart of Christendom, Vatican City)',
      'sacred',
      'วาติกัน (อิตาลี)',
      'Vatican City (Italy)',
      'นครรัฐวาติกัน',
      'Vatican City',
      41.9022,
      12.4539,
      'temple_bell',
      'มหาวิหารที่ยิ่งใหญ่และศักดิ์สิทธิ์ที่สุดของคริสตจักรโรมันคาทอลิก สร้างขึ้นเหนือหลุมฝังศพของนักบุญเปโตร อัครสาวกองค์เอกของพระเยซูคริสต์ โดดเด่นด้วยโดมขนาดยักษ์ที่ออกแบบโดยมีเกลันเจโล และประติมากรรมหินอ่อน ''ปีเอตา'' อันสะกดอารมณ์ สะท้อนศรัทธาและความงามแห่งยุคเรเนสซองส์',
      'The supreme renaissance church of the Catholic world built over the tomb of Saint Peter the Apostle. Crowning Michelangelo''s soaring dome and housing the marble masterpiece Pieta alongside the gilded papal baldachin.',
      'เริ่มสร้างขึ้นตั้งแต่ยุคจักรพรรดิคอนสแตนตินในคริสต์ศตวรรษที่ 4 ก่อนจะถูกรื้อสร้างใหม่ในศตวรรษที่ 16-17 โดยสุดยอดสถาปนิกและศิลปินแห่งยุค ทั้งบรามันเต มีเกลันเจโล และแบร์นินี',
      'Consecrated in 1626 atop the ancient Vatican necropolis, standing as an enduring symbol of spiritual apostolic continuity.',
      'ต้องแต่งกายสุภาพเรียบร้อย ห้ามเปิดไหล่หรือสวมกระโปรง/กางเกงเหนือเข่า',
      'Strict dress code: shoulders and knees must be fully covered to enter the papal basilica.',
      'https://i.ytimg.com/vi/jevJQ_U2iIs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jevJQ_U2iIs/hqdefault.jpg","title":"มหาวิหารนักบุญเปโตร (ศูนย์กลางแห่งคริสตจักรโรมันคาทอลิก นครวาติกัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jevJQ_U2iIs","title":"วาติกัน​ ประเทศเล็ก​ที่สุดในโลก และ​ ศักดิ์สิทธิ์ศักสิทธิ​ที่สุดของ​ศาสนา​คริสต์​ คาทอลิก​ | VLOG","thumbnail":"https://i.ytimg.com/vi/jevJQ_U2iIs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-pret-wat-suthat',
      'เปรตวัดสุทัศน์ (ตำนานเสียงหวีดร้องยามค่ำคืนข้างเสาชิงช้า)',
      'Preta of Wat Suthat (The Giant Weeping Hunger Shade of Old Bangkok)',
      'ghost',
      'กรุงเทพมหานคร (ไทย)',
      'Bangkok (Thailand)',
      'พระนคร',
      'Phra Nakhon',
      13.7511,
      100.5015,
      'whisper',
      'ตำนานเปรตอสุรกายรูปร่างสูงตระหง่านเสียดฟ้า แขนขายาวเก้งก้าง ปากเล็กเท่ารูเข็ม ส่งเสียงกรีดร้องโหยหวนขอส่วนบุญในคืนเดือนมืดข้างเสาชิงช้าและลานวัดสุทัศนเทพวราราม ชาวบ้านในอดีตมักมองเห็นเงาร่างผอมโซสูงเท่าต้นตาลทาบกับผนังวิหารหลวง',
      'A legendary colossal hunger spirit (Preta) haunting the courtyard of Wat Suthat and the Giant Swing. Standing tall as palm trees with needle-thin mouths, emitting high-pitched chilling wails pleading for spiritual merits on moonless nights.',
      'มีที่มาจากความเชื่อไตรภูมิพระร่วงเรื่องผลกรรมของผู้ที่ตระหนี่ถี่เหนียวหรือทำร้ายบิดามารดา เกิดเป็นสำนวนอมตะ ''แร้งวัดสระเกศ เปรตวัดสุทัศน์'' ซึ่งเปรียบเปรยกับเงาของเสาชิงช้าที่สะท้อนทาบในม่านหมอกยามเช้าตรู่',
      'Rooted in Buddhist karmic scriptures and immortalized in Siamese lore alongside the vultures of Wat Saket, describing the spectral suffering of those consumed by greed or filial transgressions.',
      'ห้ามส่งเสียงผิวปากล้อเลียนเสียงหวีดร้องของเปรต หรือขว้างปาสิ่งของในยามวิกาลรอบลานเสาชิงช้า',
      'Do not whistle mockingly or cast stones into the dark near the Giant Swing square at night.',
      'https://i.ytimg.com/vi/vgHTsjDMH4E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/vgHTsjDMH4E/hqdefault.jpg","title":"เปรตวัดสุทัศน์ (ตำนานเสียงหวีดร้องยามค่ำคืนข้างเสาชิงช้า)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=vgHTsjDMH4E","title":"ความจริงของตำนาน..เปรตวัดสุทัศน์ - คุณต้า แฟนพันธุ์แท้วัดไทย | อังคารคลุมโปง Close Up SS2 EP.13","thumbnail":"https://i.ytimg.com/vi/vgHTsjDMH4E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-nang-tani-banana-spirit',
      'นางตานี (วิญญาณพรายสาวงามผู้พิทักษ์ดงกล้วยตานี)',
      'Nang Tani (The Banana Blossom Maiden Spirit)',
      'ghost',
      'พระนครศรีอยุธยา (ไทย)',
      'Ayutthaya (Thailand)',
      'บางปะอิน',
      'Bang Pa-in',
      14.2272,
      100.5828,
      'whisper',
      'พรายสาวงามในวรรณคดีพื้นบ้านไทย สิงสถิตอยู่ในดงกล้วยตานี ปรากฏกายในชุดไทยสไบเขียวตองอ่อน ผิวขาวผุดผ่อง กลิ่นหอมระรวยเหมือนดอกกล้วยตานียามแย้มบาน มักปรากฏตัวในคืนวันเพ็ญเพื่อมอบโชคลาภหรือตักเตือนผู้ล่วงเกินดงกล้วย',
      'A renowned female spirit in Thai animist folklore dwelling inside wild Lady Finger banana groves. She manifests as an ethereal maiden draped in vibrant green traditional silk with the fragrance of blooming flowers under full moon glow.',
      'ความเชื่อโบราณถือว่ากล้วยตานีมีตานีพราย ห้ามปลูกไว้ใกล้ตัวเรือน และห้ามตัดโค่นต้นกล้วยตานีที่มีปลีกล้วยประหลาดโดยไม่ทำพิธีขอขมา มีการทำพิธี ''สู่ขวัญกล้วยตานี'' เพื่อขอพรและโชคลาภ',
      'Rooted in ancient agrarian animism where sacred groves are protected. Traditional households never plant wild banana trees adjacent to bedrooms to prevent spiritual entanglement.',
      'ห้ามปัสสาวะรดโคนต้นกล้วยตานี หรือทำร้ายลำต้นที่มีผ้าสามสีผูกไว้',
      'Never urinate near sacred banana trunks or damage trees wrapped in ceremonial tri-color cloths.',
      'https://i.ytimg.com/vi/ZysjK0lMxF0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ZysjK0lMxF0/hqdefault.jpg","title":"นางตานี (วิญญาณพรายสาวงามผู้พิทักษ์ดงกล้วยตานี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ZysjK0lMxF0","title":"นางตานี ตำนานผีพรายแห่งต้นกล้วยตานี I ห้อง STORY","thumbnail":"https://i.ytimg.com/vi/ZysjK0lMxF0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-nang-takian-gold-tree',
      'เจ้าแม่นางตะเคียนทอง (ดวงวิญญาณศักดิ์สิทธิ์ผู้สถิตในท่อนไม้ตะเคียนโบราณ)',
      'Nang Ta-khian (Sacred Guardian Dryad of the Ancient Hopea Tree)',
      'ghost',
      'สุพรรณบุรี (ไทย)',
      'Suphan Buri (Thailand)',
      'อู่ทอง',
      'U Thong',
      14.3736,
      99.8895,
      'whisper',
      'รุกขเทวดาหรือพรายไม้สตรีผู้ทรงฤทธิ์ สถิตในต้นตะเคียนทองขนาดใหญ่อายุนับร้อยปี เมื่อต้นไม้ถูกโค่นหรือขุดพบจากก้นแม่น้ำ ผู้คนจะนำขึ้นมาทำพิธีบวงสรวง ขอโชคลาภและเลขมงคล ปรากฏกลิ่นหอมของแป้งร่ำและเสียงกรุ๊งกริ๊งของกำไลข้อเท้าในยามดึก',
      'A revered and powerful tree dryad in Thai folklore inhabiting ancient Ironwood (Hopea odorata) trees. When sunken sacred trunks are unearthed from riverbeds, devotees flock to offer fragrant powders and silk garlands.',
      'ชาวสยามโบราณห้ามนำไม้ตะเคียนมาสร้างบ้านเรือนเด็ดขาดเพราะเชื่อว่ามีจิตวิญญาณของนางตะเคียนสิงสถิต ยกเว้นการนำไปสร้างเสาเอกของโบสถ์หรือเรือพระราชพิธี',
      'Taboo dictates that Ironwood timbers cannot be used for domestic residential construction due to intense latent spiritual energy, reserved solely for sacred royal barges and monastery pillars.',
      'ห้ามก้าวข้ามท่อนไม้ตะเคียนทอง หรือนำเศษไม้ตะเคียนไปใช้เผาไฟ',
      'Never step over excavated sacred Ta-khian trunks or utilize sacred wood fragments as mundane firewood.',
      'https://i.ytimg.com/vi/jUDvyn3CupU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jUDvyn3CupU/hqdefault.jpg","title":"เจ้าแม่นางตะเคียนทอง (ดวงวิญญาณศักดิ์สิทธิ์ผู้สถิตในท่อนไม้ตะเคียนโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jUDvyn3CupU","title":"นางตะเคียนกับแม่ย่านางเรือ | ทำไมผีในต้นไม้กลายเป็นเทพประจำเรือ (7 นาที)","thumbnail":"https://i.ytimg.com/vi/jUDvyn3CupU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-white-lady-balete-drive',
      'ผีสาวชุดขาวแห่งถนนบาเลเต (วิญญาณอาฆาตใต้ต้นไทรฟิลิปปินส์)',
      'The White Lady of Balete Drive (The Haunted Banyan of Quezon City)',
      'ghost',
      'เกซอนซิตี (ฟิลิปปินส์)',
      'Quezon City (Philippines)',
      'บาเลเตไดรฟ์',
      'Balete Drive',
      14.6224,
      121.0336,
      'creepy_wind',
      'วิญญาณหญิงสาวในชุดเดรสสีขาวบริสุทธิ์ เส้นผมยาวสลวยสีดำปิดบังใบหน้า ปรากฏตัวริมถนนสายร่มรื่นที่เรียงรายด้วยต้นบาเลเต (ต้นไทร) โบราณ คนขับแท็กซี่ยามดึกมักพบเห็นเธอยืนโบกรถ แต่เมื่อมองผ่านกระจกหลังจะพบร่างโปร่งแสงนั่งนิ่งอยู่ที่เบาะหลังโดยไม่มีใบหน้า',
      'The most famous ghost legend of the Philippines along Balete Drive, framed by massive mystical Balete (strangler fig) trees. Motorists late at night glimpse a pale woman hailing a ride, only to look into the rearview mirror and see her faceless spectral form in the back seat.',
      'เชื่อว่าเป็นดวงวิญญาณของหญิงสาวที่ถูกทำร้ายจนเสียชีวิตในช่วงทศวรรษ 1950 บนถนนสายนี้ หรือเป็นภูตพรายตามความเชื่อพื้นเมืองฟิลิปปินส์ที่อาศัยอยู่ใต้ต้นไทรศักดิ์สิทธิ์',
      'Dating back to the 1950s, folklorists merge pre-colonial animist beliefs of guardian nature spirits (Engkanto) residing within sacred balete trees with tragic urban tragedy lore.',
      'ห้ามบีบแตรทักทายหรือจ้องมองกระจกหลังเมื่อขับผ่านต้นบาเลเตยักษ์ในยามเที่ยงคืน',
      'Avoid honking or staring fixatedly into your rearview mirror while cruising past large banyans on Balete Drive at midnight.',
      'https://i.ytimg.com/vi/4oWFq-tRBSs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/4oWFq-tRBSs/hqdefault.jpg","title":"ผีสาวชุดขาวแห่งถนนบาเลเต (วิญญาณอาฆาตใต้ต้นไทรฟิลิปปินส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=4oWFq-tRBSs","title":"The White Lady of Balete Drive - Philippine Urban Legend","thumbnail":"https://i.ytimg.com/vi/4oWFq-tRBSs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-mul-gwishin-water-ghost',
      'มุลกวีชิน (ผีพรายน้ำลากเหยื่อแห่งแม่น้ำฮัน)',
      'Mul Gwishin (The Waterbound Spirits of the Han River)',
      'ghost',
      'โซล (เกาหลีใต้)',
      'Seoul (South Korea)',
      'แม่น้ำฮัน',
      'Han River',
      37.5283,
      126.9328,
      'water_spirit',
      'วิญญาณผู้เสียชีวิตจากการจมน้ำในวัฒนธรรมเกาหลี ร่างกายเปียกโชก ผิวซีดเผือด แขนยืดยาวผิดธรรมชาติซ่อนอยู่ใต้น้ำเย็นยะเยือก เชื่อว่าต้องดึงผู้คนลงไปจมน้ำแทนที่ตนจึงจะสามารถไปสู่สุคติได้',
      'Traditional Korean water ghosts of drowning victims. Trapped in the freezing depths with drenched robes and extended pale arms, they drag solitary swimmers beneath swirling currents to trade places and liberate their souls.',
      'มีรากฐานมาจากความเชื่อชามันนิซึมเกาหลี (มูกโย) ซึ่งต้องจัดพิธี ''กุต'' เพื่อปลดปล่อยวิญญาณที่จมน้ำให้ข้ามแม่น้ำแห่งความตายสู่ภพภูมิหน้า',
      'Deeply entrenched in Korean shamanic rites (Gut), where special water rituals are performed by Mudang shamans to cut spiritual bonds and appease lonely aquatic shades.',
      'ห้ามว่ายน้ำตามลำพังยามพลบค่ำในบริเวณน้ำวนหรือจุดที่มีกระแสน้ำไหลเชี่ยว',
      'Never swim alone at dusk in deep whirlpools or turbulent currents along Korean waterways.',
      'https://i.ytimg.com/vi/YHVHUkvM78Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/YHVHUkvM78Y/hqdefault.jpg","title":"มุลกวีชิน (ผีพรายน้ำลากเหยื่อแห่งแม่น้ำฮัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=YHVHUkvM78Y","title":"South Korean Water Ghost or  Mul Gwishin 물귀신 🧡","thumbnail":"https://i.ytimg.com/vi/YHVHUkvM78Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-dalgyal-gwishin-faceless',
      'ดัลกยัลกวีชิน (ผีไข่ไร้หน้าแห่งภูเขาและป่าลึก)',
      'Dalgyal Gwishin (The Faceless Egg Ghost of Ancient Korea)',
      'ghost',
      'คังวอนโด (เกาหลีใต้)',
      'Gangwon-do (South Korea)',
      'ซอรักซาน',
      'Seoraksan',
      38.1195,
      128.4656,
      'whisper',
      'หนึ่งในผีที่น่าสะพรึงกลัวที่สุดในคติชนเกาหลี ปรากฏเป็นร่างมนุษย์ที่ใบหน้าเรียบเนียนไร้ตา จมูก และปาก เหมือนผิวไข่ต้ม ผู้ใดที่สบตากับมันจะประสบเคราะห์ร้ายรุนแรงหรือล้มป่วยจนถึงแก่ชีวิตทันที',
      'The infamous Faceless Egg Ghost of Korean folklore. Appearing along desolate mountain trails, it possesses a completely smooth face devoid of eyes, nose, or mouth like a peeled egg; encountering one forebodes fatal doom.',
      'เชื่อว่าเป็นวิญญาณของผู้ที่เสียชีวิตโดยไร้ทายาทและไม่มีใครทำพิธีเซ่นไหว้บรรพบุรุษ จึงสูญเสียอัตลักษณ์ความเป็นมนุษย์และกลายเป็นตัวแทนของความว่างเปล่าอันน่าสยดสยอง',
      'Represents ancestral displacement in Confucian cosmology—spirits who died without descendants to perform ancestor veneration, degenerating into featureless void manifestations.',
      'หากพบคนแปลกหน้ายืนหันหลังบนเส้นทางเดินป่ากลางดึก ห้ามเรียกทักหรือเดินเข้าไปสะกิด',
      'If encountering a motionless silhouette facing away in deep mountain trails, do not tap their shoulder or speak.',
      'https://i.ytimg.com/vi/CUqYJ_2yuLY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/CUqYJ_2yuLY/hqdefault.jpg","title":"ดัลกยัลกวีชิน (ผีไข่ไร้หน้าแห่งภูเขาและป่าลึก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=CUqYJ_2yuLY","title":"PART 2: DALGYAL GWISHIN (달걀귀신) II ANG MULTONG WALANG MUKHA II KOREAN URBAN LEGEND (EGG GHOST)","thumbnail":"https://i.ytimg.com/vi/CUqYJ_2yuLY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-rokurokubi-long-neck',
      'โรคุโรคุบิ (ผีคอยาวแห่งเอโดะ)',
      'Rokurokubi (The Slithering Long-Necked Yokai)',
      'ghost',
      'โตเกียว (ญี่ปุ่น)',
      'Tokyo (Japan)',
      'อาซากุสะ',
      'Asakusa',
      35.7148,
      139.7967,
      'creepy_wind',
      'โยไคหญิงสาวที่กลางวันใช้ชีวิตเหมือนมนุษย์ปกติ แต่ยามค่ำคืนเมื่อหลับสนิท คอของเธอจะยืดยาวออกเป็นเส้นเหมือนสายเชือก เลื้อยไปรอบบ้านหรือออกไปเลียน้ำมันตะเกียงและสอดส่องหาเหยื่อ',
      'Classic Japanese supernatural entity appearing as an ordinary human woman by day, whose neck stretches to impossible lengths at night while sleeping, coiling across rafters to lap lamp oil or observe human secrets.',
      'ได้รับการบันทึกในวรรณกรรมและภาพพิมพ์คลาสสิกสมัยเอโดะ เช่น ผลงานของโทริยามะ เซกิเอ็ง ในหนังสือ ''กาสุ เฮียกกิ ยาเกียว'' สะท้อนความเชื่อเรื่องผลกรรมหรือพลังจิตวิญญาณที่หลุดออกจากร่าง',
      'Immortalized in Edo-period illustrated bestiaries by Toriyama Sekien, often portrayed as a karmic affliction or soul projection (Ikiryo) leaving the corporeal vessel during slumber.',
      'ห้ามขยับตัวย้ายร่างของหญิงสาวที่สงสัยว่าเป็นโรคุโรคุบิขณะที่คอกำลังยืดยาว เพราะอาจทำให้หัวหาทางกลับเข้าร่างไม่ได้',
      'Never displace the sleeping body of a suspected Rokurokubi while the neck is extended, as the head may become eternally severed.',
      'https://i.ytimg.com/vi/__-3FWE9fW8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/__-3FWE9fW8/hqdefault.jpg","title":"โรคุโรคุบิ (ผีคอยาวแห่งเอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=__-3FWE9fW8","title":"ROKUROKUBI Animated Horror Story | Japanese Urban Legend Animation","thumbnail":"https://i.ytimg.com/vi/__-3FWE9fW8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-umibozu-giant-sea-monk',
      'อุมิโบซุ (พระสงฆ์ยักษ์ทมิฬแห่งผืนสมุทร)',
      'Umibozu (The Colossal Black Sea Monk Specter)',
      'ghost',
      'ชิซูโอกะ (ญี่ปุ่น)',
      'Shizuoka (Japan)',
      'อ่าวซูรูงะ',
      'Suruga Bay',
      34.85,
      138.5,
      'water_spirit',
      'วิญญาณอสุรกายยักษ์สีดำมะเมื่อมที่โผล่ขึ้นมาจากใต้ผืนทะเลอันเงียบสงบ ลำตัวใหญ่โตเสียดฟ้า ศีรษะกลมเกลี้ยงคล้ายพระสงฆ์ ดวงตากลมโตส่องประกายสีทอง มักเข้าทำลายเรือเดินสมุทรหรือขอถังน้ำจากกะลาสีเพื่อตักน้ำจมเรือ',
      'A gargantuan maritime specter rising silently from sudden calm ocean waters. Pitch black with a smooth monk-like dome and radiant glowing eyes, it commands turbulent waves and demands wooden ladles from sailors to flood their vessel.',
      'กะลาสีญี่ปุ่นโบราณแก้เคล็ดด้วยการมอบถังน้ำที่เจาะก้นทะลุ เพื่อให้อุมิโบซุตักน้ำไม่สำเร็จและเปิดโอกาสให้เรือแล่นหนีพ้น',
      'Seafarers historically outwitted the phantom by offering bottomless wooden barrels, giving crews time to maneuver safely away while the entity attempted futile scoops.',
      'ห้ามพูดคุยถึงความลึกของทะเลหรือเรียกขานชื่ออุมิโบซุขณะเดินเรือในทะเลสงัดยามค่ำ',
      'Never discuss ocean depths or utter the name Umibozu when sailing across eerie calm midnight waters.',
      'https://i.ytimg.com/vi/hYy-yrMqsWs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/hYy-yrMqsWs/hqdefault.jpg","title":"อุมิโบซุ (พระสงฆ์ยักษ์ทมิฬแห่งผืนสมุทร)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=hYy-yrMqsWs","title":"Umibozu, A Japanese Folklore Sea Creature - ''The Sea Monk''","thumbnail":"https://i.ytimg.com/vi/hYy-yrMqsWs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-gashadokuro-giant-skeleton',
      'กาชาโดคุโระ (โครงกระดูกยักษ์พันศพแห่งสงคราม)',
      'Gashadokuro (The Colossal Skeletal Titan of Starvation)',
      'ghost',
      'เกียวโต (ญี่ปุ่น)',
      'Kyoto (Japan)',
      'เทือกเขาฮิเอ',
      'Mount Hiei',
      35.0664,
      135.8406,
      'creepy_wind',
      'โครงกระดูกยักษ์สูงใหญ่กว่า 15 เท่าของมนุษย์ปกติ ก่อตัวขึ้นจากกระดูกของทหารและชาวบ้านนับพันที่ล้มตายจากสงครามหรือความอดอยากและไม่ได้รับการประกอบพิธีศพ ก้าวเดินในความมืดพร้อมเสียงกระดูกกระทบกันดัง ''กาชะ-กาชะ'' และกัดศีรษะของผู้คน',
      'A colossal skeleton fifteen times taller than an average human, coalesced from the residual malice of unburied casualties from famine and war. Wanders moonlit fields with a terrifying bone-clattering rattle to bite off traveler heads.',
      'ปรากฏในตำนานเจ้าหญิงทากิยาฉะ บุตรสาวของไทระ โนะ มาซาคาโดะ ซึ่งใช้เวทมนตร์อัญเชิญโครงกระดูกยักษ์มาแก้แค้นราชสำนักเกียวโต',
      'Famously depicted in Utagawa Kuniyoshi''s iconic ukiyo-e print ''Mitsukuni Defying the Skeleton Spectre'', summoned by sorceress Princess Takiyasha.',
      'หากได้ยินเสียงหวีดหวิวในหูดังลั่นในทุ่งกว้างยามค่ำคืน ให้รีบหมอบซ่อนตัวและสวดมนต์ทันที',
      'If hearing an inexplicable high-pitched ringing in your ears in nocturnal open fields, dive for cover and chant warding sutras.',
      'https://i.ytimg.com/vi/mge8be9KAY4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/mge8be9KAY4/hqdefault.jpg","title":"กาชาโดคุโระ (โครงกระดูกยักษ์พันศพแห่งสงคราม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=mge8be9KAY4","title":"Gashadokuro (餓者髑髏) – The Bone-Crushing Legend of Japan’s Giant Skeleton | Yokai Horror Tale","thumbnail":"https://i.ytimg.com/vi/mge8be9KAY4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-kage-onna-shadow-woman',
      'คาเงะอนนะ (เงาสตรีลี้ลับบนฉากกั้นโชจิ)',
      'Kage-onna (The Phantom Shadow Maiden of Paper Shoji)',
      'ghost',
      'โอซาก้า (ญี่ปุ่น)',
      'Osaka (Japan)',
      'เท็นโนจิ',
      'Tennoji',
      34.6533,
      135.5133,
      'whisper',
      'วิญญาณเงาของสตรีโบราณที่ทาบลงบนฉากกั้นกระดาษโชจิในคืนเดือนเพ็ญ ปรากฏเป็นรูปสตรีสวมชุดกิโมโนกำลังหวีผมหรือเต้นรำอย่างอ่อนช้อย แต่เมื่อเปิดฉากกั้นออกกลับไม่พบใครอยู่ในห้อง',
      'An eerie paper-screen shadow apparition. On moonlit nights, the silhouette of an elegant woman in a traditional kimono appears cast upon shoji screens, brushing her hair without any physical caster.',
      'เป็นโยไคที่สะท้อนความเหงาและความทรงจำที่หลงเหลืออยู่ในบ้านเรือนโบราณ ไม่ทำร้ายผู้คนแต่สร้างความเย็นยะเยือกแก่ผู้พบเห็น',
      'Documented in folkloric compilations like the Konjaku Hyakki Shui, embodying harmless yet melancholic residual psychic imprints in aging wooden residences.',
      'ห้ามฉีกหรือทำลายกระดาษฉากกั้นขณะที่เงากำลังปรากฏ',
      'Never pierce or tear the shoji paper screen while the phantom shadow is cast upon it.',
      'https://i.ytimg.com/vi/VLgDVQSygfQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/VLgDVQSygfQ/hqdefault.jpg","title":"คาเงะอนนะ (เงาสตรีลี้ลับบนฉากกั้นโชจิ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=VLgDVQSygfQ","title":"Yokai - Kage Onna #japan #japanese #yokai #ghost #woman #spirit #haunted","thumbnail":"https://i.ytimg.com/vi/VLgDVQSygfQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-hampton-court-catherine-howard',
      'วิญญาณแคทเธอรีน ฮาวเวิร์ด แห่งพระราชวังแฮมป์ตันคอร์ต',
      'Catherine Howard’s Screaming Ghost of Hampton Court Palace',
      'ghost',
      'ลอนดอน (สหราชอาณาจักร)',
      'London (United Kingdom)',
      'ริชมอนด์ อะพอน เทมส์',
      'Richmond upon Thames',
      51.4036,
      -0.3378,
      'whisper',
      'วิญญาณพระมเหสีองค์ที่ 5 ของพระเจ้าเฮนรีที่ 8 ผู้ถูกสำเร็จโทษด้วยการตัดศีรษะในหอคอยลอนดอน วิญญาณของเธอยังคงวิ่งกรีดร้องโหยหวนไปตาม ''ระเบียงเสียงกรีดร้อง'' (Haunted Gallery) เพื่อวิงวอนขอชีวิตจากกษัตริย์',
      'The tragic ghost of King Henry VIII''s fifth wife, executed for treason. Her spectral apparition in white drapery sprints down the palace''s Haunted Gallery, recreating her desperate final plea for royal clemency.',
      'เป็นหนึ่งในการพบเห็นวิญญาณที่มีชื่อเสียงที่สุดในประวัติศาสตร์อังกฤษ บันทึกโดยเจ้าหน้าที่สำนักพระราชวังและนักท่องเที่ยวที่ได้ยินเสียงสะอื้นไห้และอุณหภูมิห้องที่ลดฮวบ',
      'A cornerstone of British royal hauntings, documented continuously across centuries by palace guards, antiquarians, and modern visitors experiencing sudden icy corridors.',
      'ห้ามยืนขวางทางเดินระเบียงโถงยามพลบค่ำในพระราชวัง',
      'Never linger blocking the Haunted Gallery walkway at twilight hours.',
      'https://i.ytimg.com/vi/lne_ye2UYBo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/lne_ye2UYBo/hqdefault.jpg","title":"วิญญาณแคทเธอรีน ฮาวเวิร์ด แห่งพระราชวังแฮมป์ตันคอร์ต"},{"type":"youtube","url":"https://www.youtube.com/watch?v=lne_ye2UYBo","title":"Hampton Court Palace CCTV ghost \"Skeletor\"","thumbnail":"https://i.ytimg.com/vi/lne_ye2UYBo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-glamis-castle-monster',
      'ความลับและวิญญาณแห่งปราสาทกลามิส',
      'The Secret Chambers and Phantoms of Glamis Castle',
      'ghost',
      'แองกัส (สกอตแลนด์)',
      'Angus (Scotland)',
      'กลามิส',
      'Glamis',
      56.6203,
      -3.0022,
      'creepy_wind',
      'ปราสาทโบราณที่ได้รับการขนานนามว่าหลอนที่สุดในสกอตแลนด์ มีตำนานห้องลับที่ซ่อนสัตว์ประหลาดแห่งกลามิส และวิญญาณ ''เกรย์เลดี้'' (เลดี้เจเน็ต ดักลาส) ที่ถูกเผาทั้งเป็นในข้อหาเป็นแม่มด',
      'One of Scotland''s most haunted ancestral fortresses, shrouded in whispers of a walled-off secret chamber harboring the Monster of Glamis and the kneeling ghost of Lady Janet Douglas burned for witchcraft.',
      'มีประวัติศาสตร์ยาวนานตั้งแต่ศตวรรษที่ 14 เป็นสถานที่เกิดของสมเด็จพระราชินีเอลิซาเบธ พระราชชนนี และเป็นฉากหลังของบทละครแม็คเบ็ธของเชกสเปียร์',
      'Ancestral home to the Earls of Strathmore and Kinghorne, woven into Shakespearean lore and verified paranormal investigations by the Society for Psychical Research.',
      'ห้ามพยายามนับจำนวนหน้าต่างเพื่อค้นหาตำแหน่งห้องลับที่ถูกปิดตาย',
      'Do not attempt to count castle exterior windows against interior rooms to locate sealed vaults.',
      'https://i.ytimg.com/vi/6Rmoa0fH-KU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/6Rmoa0fH-KU/hqdefault.jpg","title":"ความลับและวิญญาณแห่งปราสาทกลามิส"},{"type":"youtube","url":"https://www.youtube.com/watch?v=6Rmoa0fH-KU","title":"The HORRIFYING Secrets of Scotland’s Most HAUNTED Castle","thumbnail":"https://i.ytimg.com/vi/6Rmoa0fH-KU/hqdefault.jpg"}]'
    );

