      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-edinburgh-castle-headless-drummer',
      'มือกลองไร้หัวแห่งปราสาทเอดินบะระ',
      'The Headless Drummer Boy of Edinburgh Castle',
      'ghost',
      'เอดินบะระ (สกอตแลนด์)',
      'Edinburgh (Scotland)',
      'รอยัลไมล์',
      'Royal Mile',
      55.9486,
      -3.1999,
      'creepy_wind',
      'เสียงรัวกลองลึกลับที่ดังก้องจากป้อมปราการหินโบราณบนยอดภูเขาไฟดับสนิท ตามมาด้วยการปรากฏตัวของร่างเด็กหนุ่มทหารในชุดโบราณที่ไม่มีศีรษะ ถือไม้ตีกลองรัวเป็นจังหวะเตือนภัยการรุกราน',
      'A spectral drummer boy pacing the parapets of the ancient volcanic rock citadel. Lacking a head and beating frantic snare rhythms, his haunting cadence historically portends impending siege or national turmoil.',
      'ได้รับการบันทึกครั้งแรกในปี ค.ศ. 1650 ก่อนที่กองทัพของโอลิเวอร์ ครอมเวลล์ จะเข้าโจมตีและยึดปราสาทเอดินบะระได้สำเร็จ',
      'First recorded in historical archives in 1650 prior to Oliver Cromwell''s successful assault, establishing the drummer as a potent omen of siege and transformation.',
      'ห้ามเลียนแบบเสียงรัวกลองทหารบนเชิงเทินปราสาทยามค่ำคืน',
      'Never mimic military march cadences along the battlements of Castle Rock at dusk.',
      'https://i.ytimg.com/vi/PIa_gETzhXY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/PIa_gETzhXY/hqdefault.jpg","title":"มือกลองไร้หัวแห่งปราสาทเอดินบะระ"},{"type":"youtube","url":"https://www.youtube.com/watch?v=PIa_gETzhXY","title":"Edinburgh Castle''s Headless Drummer Boy Still Warns of Attack 👻🥁","thumbnail":"https://i.ytimg.com/vi/PIa_gETzhXY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
