      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-leap-castle-elemental',
      'ภูตอสูรอีลีเมนทัลแห่งปราสาทลีพ',
      'The Malignant Elemental of Leap Castle',
      'ghost',
      'เคาน์ตีออฟฟาลี (ไอร์แลนด์)',
      'County Offaly (Ireland)',
      'คูลดอร์รี',
      'Coolderry',
      53.0286,
      -7.8083,
      'creepy_wind',
      'ปราสาทที่มีประวัติศาสตร์การนองเลือดและหอคอยทมิฬ ปรากฏตนของสิ่งมีชีวิตเร้นลับขนาดเท่าแกะแต่มีใบหน้าเน่าเปื่อยคล้ายมนุษย์ มีกลิ่นกำมะถันและซากศพโชยรุนแรง แผ่รังสีแห่งความหวาดกลัวไปทั่วห้องโถง',
      'Ireland''s most notoriously haunted fortress, scarred by fratricidal bloodbaths. It harbors ''The Elemental''—a repulsive hunched entity smelling of sulfur and decaying flesh with hollow eyes that radiates palpable dread.',
      'สร้างโดยตระกูลโอแคร์รอลล์ในศตวรรษที่ 15 มี ''หลุมหนามสังหาร'' (Oubliette) ที่ค้นพบโครงกระดูกมนุษย์มากกว่าสามเกวียนซ่อนอยู่หลังกำแพงโบสถ์เลือด',
      'Constructed over ancient druidic grounds by the O''Carroll clan, notorious for the Bloody Chapel and a spiked oubliette containing hundreds of victims'' skeletal remains.',
      'ห้ามเข้าไปสำรวจห้องโถงโบสถ์เลือดตามลำพังในความมืด',
      'Never enter the Bloody Chapel chamber unescorted in total darkness.',
      'https://i.ytimg.com/vi/fF-2cp0-zR8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/fF-2cp0-zR8/hqdefault.jpg","title":"ภูตอสูรอีลีเมนทัลแห่งปราสาทลีพ"},{"type":"youtube","url":"https://www.youtube.com/watch?v=fF-2cp0-zR8","title":"The Disturbing True Story of Leap Castle | The World''s Most Haunted Castle","thumbnail":"https://i.ytimg.com/vi/fF-2cp0-zR8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
