      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-green-lady-chateau-brissac',
      'สตรีชุดเขียวแห่งปราสาทบริสซัค',
      'The Green Lady (La Dame Verte) of Château de Brissac',
      'ghost',
      'เมน-เอ-ลัวร์ (ฝรั่งเศส)',
      'Maine-et-Loire (France)',
      'บริสซัค-ก็องเซ',
      'Brissac-Quincé',
      47.3533,
      -0.4503,
      'whisper',
      'วิญญาณหญิงสูงศักดิ์ในชุดเดรสสีเขียวหรูหรา ใบหน้าเป็นโพรงกลวงเน่าเปื่อยไร้ลูกตาและจมูก ล่องลอยไปตามห้องหอคอยและโบสถ์น้อยของปราสาทที่สูงที่สุดในหุบเขาแม่น้ำลัวร์ พร้อมส่งเสียงครางคร่ำครวญน่าเวทนา',
      'The spectral resident of the towering seven-story Château de Brissac. Draped in an elegant green velvet gown with gaping skeletal facial cavities, her mournful weeping echoes across the castle chapel at dawn.',
      'คือชาร์ล็อตต์ เดอ เบรเซ บุตรสาวนอกสมรสของพระเจ้าชาร์ลส์ที่ 7 ซึ่งถูกสามีจับได้ว่ามีชู้และถูกสังหารอย่างโหดเหี้ยมในห้องนอนของปราสาทเมื่อปี ค.ศ. 1477',
      'Identified as Charlotte de Brézé, murdered in 1477 by her husband Jacques de Brézé upon discovering her infidelity in the castle''s upper bedchamber.',
      'ห้ามส่องกระจกโบราณในหอคอยห้องนอนใหญ่หลังเวลาเที่ยงคืน',
      'Do not gaze into the antique gilded mirrors of the master tower after midnight.',
      'https://i.ytimg.com/vi/BAkw4TbbiiY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/BAkw4TbbiiY/hqdefault.jpg","title":"สตรีชุดเขียวแห่งปราสาทบริสซัค"},{"type":"youtube","url":"https://www.youtube.com/watch?v=BAkw4TbbiiY","title":"The Green Lady of Château de Brissac: France''s Most Haunted Castle True Story","thumbnail":"https://i.ytimg.com/vi/BAkw4TbbiiY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-catacombs-of-paris-ghosts',
      'วิญญาณสุสานใต้ดินปารีส (อาณาจักรคนตาย 6 ล้านศพ)',
      'The Whispering Shades of the Catacombs of Paris',
      'ghost',
      'ปารีส (ฝรั่งเศส)',
      'Paris (France)',
      'มงต์ปาร์นาส',
      'Montparnasse',
      48.8338,
      2.3324,
      'whisper',
      'อุโมงค์เหมืองหินปูนใต้ดินความยาวกว่า 300 กิโลเมตรที่บรรจุหัวกะโหลกและกระดูกมนุษย์มากกว่า 6 ล้านร่าง ผู้บุกรุกเส้นทางลับมักได้ยินเสียงกระซิบเรียกชื่อจากความมืดมิด ไฟฉายดับลงกะทันหัน และหลงทางในเขาวงกตไร้ที่สิ้นสุด',
      'An underground ossuary containing over six million skeletal remains beneath the boulevards of Paris. Explorers in forbidden tunnels report phantom torchlights, disembodied whispers echoing from bone walls, and losing all sense of direction.',
      'สร้างขึ้นในปลายศตวรรษที่ 18 เพื่อแก้ปัญหาสุสานล้นเมืองและโรคระบาด ป้ายเหนือทางเข้าจารึกว่า ''หยุด! นี่คืออาณาจักรแห่งความตาย''',
      'Established in 1786 to alleviate overflowing city graveyards, lined with artfully stacked ossuary motifs and warning inscriptions: ''Stop! This is the Empire of Death''.',
      'ห้ามหยิบจับ ย้ายตำแหน่ง หรือนำกระดูกมนุษย์ออกจากสุสานใต้ดินเด็ดขาด',
      'Never touch, dislodge, or pocket human bones from the ossuary corridors.',
      'https://i.ytimg.com/vi/6bgL8pCocVI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/6bgL8pCocVI/hqdefault.jpg","title":"วิญญาณสุสานใต้ดินปารีส (อาณาจักรคนตาย 6 ล้านศพ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=6bgL8pCocVI","title":"After 25 Years, The Catacombs Lost Footage Mystery Is Solved","thumbnail":"https://i.ytimg.com/vi/6bgL8pCocVI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-poveglia-island-plague',
      'เกาะโพเวเกลีย (เกาะกักกันโรคและวิญญาณคนบาปแห่งเวนิส)',
      'Poveglia Island (The Plague Quarantine and Mad Asylum Isle)',
      'ghost',
      'เวนิส (อิตาลี)',
      'Venice (Italy)',
      'ลากูนเวนิส',
      'Venetian Lagoon',
      45.3828,
      12.3314,
      'creepy_wind',
      'เกาะต้องห้ามกลางทะเลสาบเวนิสที่ดินกว่า 50% เป็นเถ้ากระดูกมนุษย์จากผู้ป่วยกาฬโรคและคนไข้จิตเวชในอดีต เรือกอนโดลาไม่ยอมเข้าใกล้ เสียงระฆังหอคอยยังคงดังก้องในความเงียบทั้งที่ระฆังถูกถอดออกไปแล้วหลายทศวรรษ',
      'A quarantined island in the Venetian Lagoon where over 100,000 plague victims were incinerated, later converted into an asylum with an abusive chief physician. The tower bell still tolls across misty waters despite being removed long ago.',
      'ในยุคกาฬโรคระบาดหนัก ผู้ต้องสงสัยว่าติดเชื้อจะถูกนำมาทิ้งไว้ที่นี่จนเสียชีวิต ต่อมาในทศวรรษ 1920 ถูกใช้เป็นโรงพยาบาลจิตเวชที่มีการทดลองผ่าตัดสมองมนุษย์อย่างโหดเหี้ยม',
      'Functioned as a Black Death lazaretto from 1776, followed by a psychiatric asylum whose director reportedly leapt from the bell tower after claiming madness from phantom torment.',
      'ห้ามลักลอบขึ้นเกาะโดยไม่ได้รับอนุญาตจากทางการเวนิส',
      'Strictly forbidden by Venetian authorities to dock or enter the island without scientific clearance.',
      'https://i.ytimg.com/vi/0wfXn-bbUo8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0wfXn-bbUo8/hqdefault.jpg","title":"เกาะโพเวเกลีย (เกาะกักกันโรคและวิญญาณคนบาปแห่งเวนิส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0wfXn-bbUo8","title":"Poveglia Island: The World''s Most Lied About Place","thumbnail":"https://i.ytimg.com/vi/0wfXn-bbUo8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-st-augustine-lighthouse-ghosts',
      'วิญญาณประภาคารเซนต์ออกัสติน',
      'The Phantoms of the St. Augustine Lighthouse',
      'ghost',
      'ฟลอริดา (สหรัฐอเมริกา)',
      'Florida (United States)',
      'เซนต์ออกัสติน',
      'St. Augustine',
      29.8906,
      -81.2889,
      'water_spirit',
      'ประภาคารเก่าแก่ที่สุดในฟลอริดา มีบันไดวนเหล็ก 219 ขั้น ผู้ดูแลและนักท่องเที่ยวรายงานการพบเห็นเงาดำของเด็กหญิงสองคนในชุดศตวรรษที่ 19 วิ่งเล่นรอบบันได เสียงหัวเราะสดใส และกลิ่นควันซิการ์ของผู้ดูแลประภาคารผู้ล่วงลับ',
      'Florida’s oldest brick lighthouse standing over Anastasia Island. Visitors climbing its 219 cast-iron spiral steps encounter laughing apparitions of two sisters who drowned in 1873 and the lingering cigar scent of former keeper Peter Rasmussen.',
      'ในปี 1873 บุตรสาวของหัวหน้าช่างก่อสร้างประภาคารเล่นรถรางขนดินจนพลัดตกลงไปในอ่าวและจมน้ำเสียชีวิตอย่างน่าสลดใจ กลายเป็นวิญญาณพิทักษ์ประภาคารมาจนถึงปัจจุบัน',
      'Tied to the tragic 1873 drowning of young sisters Mary and Eliza Pittee while riding an excavation supply rail cart, memorialized through ongoing historical society paranormal research.',
      'ห้ามวิ่งเล่นส่งเสียงดังหรือล้อเลียนเสียงหัวเราะของเด็กบนบันไดวนหอคอย',
      'Do not mock children''s giggles or run recklessly along the spiral iron staircase.',
      'https://i.ytimg.com/vi/437eKqGwBQc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/437eKqGwBQc/hqdefault.jpg","title":"วิญญาณประภาคารเซนต์ออกัสติน"},{"type":"youtube","url":"https://www.youtube.com/watch?v=437eKqGwBQc","title":"My Terrifying Experience ALONE at Haunted Lighthouse","thumbnail":"https://i.ytimg.com/vi/437eKqGwBQc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-lizzie-borden-axe-murders',
      'บ้านฆาตกรรมขวานลิซซี บอร์เดน',
      'The Lizzie Borden Axe Murder House',
      'ghost',
      'แมสซาชูเซตส์ (สหรัฐอเมริกา)',
      'Massachusetts (United States)',
      'ฟอลล์ริเวอร์',
      'Fall River',
      41.6989,
      -71.1561,
      'whisper',
      'บ้านไม้สไตล์วิกตอเรียนสถานที่เกิดเหตุคดีฆาตกรรมสะเทือนขวัญในปี 1892 เมื่อแอนดรูว์และแอบบี บอร์เดน ถูกฟันด้วยขวานจนเสียชีวิตอย่างสยดสยอง แขกที่เข้าพักค้างคืนในปัจจุบันมักพบเห็นรอยยุบตัวบนเตียง เสียงเดินก้อง และเงาของสตรีถือขวาน',
      'The historic Victorian residence where Andrew and Abby Borden were brutally slain with a hatchet in August 1892. Now a bed-and-breakfast, guests experience indentations on pillows, phantom crying, and shadow figures in the murder suites.',
      'แม้ลิซซี บอร์เดน บุตรสาวจะถูกนำตัวขึ้นศาลแต่คณะลูกขุนตัดสินให้พ้นผิด คดีนี้จึงกลายเป็นหนึ่งในปริศนาคดีฆาตกรรมที่โด่งดังที่สุดในประวัติศาสตร์อาชญากรรมอเมริกัน',
      'Though Lizzie Borden was tried and acquitted, the unsolved double homicide inspired indelible folklore nursery rhymes and continuous residual psychical impressions.',
      'ห้ามนำขวานหรือของมีคมเข้ามาเล่นล้อเลียนในห้องนอนชั้นสอง',
      'Never brandish edged tools or conduct mock trials in the John Morse bedchamber.',
      'https://i.ytimg.com/vi/2RTtN5vGYrI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/2RTtN5vGYrI/hqdefault.jpg","title":"บ้านฆาตกรรมขวานลิซซี บอร์เดน"},{"type":"youtube","url":"https://www.youtube.com/watch?v=2RTtN5vGYrI","title":"Lizzie Borden House in Fall River, Massachusetts","thumbnail":"https://i.ytimg.com/vi/2RTtN5vGYrI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-waverly-hills-tunnel-ghosts',
      'อุโมงค์มรณะแห่งเวเวอร์ลีฮิลส์ ซานาโทเรียม',
      'The Body Chute and Spirits of Waverly Hills Sanatorium',
      'ghost',
      'เคนทักกี (สหรัฐอเมริกา)',
      'Kentucky (United States)',
      'ลุยส์วิลล์',
      'Louisville',
      38.1301,
      -85.8427,
      'creepy_wind',
      'โรงพยาบาลรักษาวัณโรคโบราณที่มีผู้เสียชีวิตมากกว่า 60,000 ราย มี ''อุโมงค์ลำเลียงศพ'' (Death Tunnel) ความยาว 150 เมตรที่ใช้เข็นศพออกไปยามค่ำคืน ผู้สำรวจมักพบเห็นลูกบอลไฟ เงาดำคืบคลาน และเสียงไอแห้งๆ ของผู้ป่วยดังก้องในความมืด',
      'A historic tuberculosis sanatorium renowned for its 500-foot underground ''Body Chute'' tunnel designed to discreetly transport deceased patients. Investigators document shadow figures, disembodied coughing, and moving orbs.',
      'สร้างขึ้นในปี 1910 ท่ามกลางวิกฤตการระบาดของ ''กาฬโรคสีขาว'' (วัณโรค) ในช่วงที่ยังไม่มียาปฏิชีวนะ ผู้ป่วยต้องทนกับการรักษาอันเจ็บปวดและการกักตัวอย่างโดดเดี่ยว',
      'Opened in 1910 during the height of the White Plague outbreak in Jefferson County, functioning as a self-contained quarantine community with its own tragic memorial history.',
      'ห้ามเดินในอุโมงค์ลำเลียงศพโดยปราศจากแสงสว่างและเครื่องตรวจจับก๊าซ',
      'Do not traverse the subterranean Body Chute without active illumination and atmospheric sensors.',
      'https://i.ytimg.com/vi/XJpI3gkr5gI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XJpI3gkr5gI/hqdefault.jpg","title":"อุโมงค์มรณะแห่งเวเวอร์ลีฮิลส์ ซานาโทเรียม"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XJpI3gkr5gI","title":"The Hospital That Had a Body Chute: Waverly Hills Explained by a Mortician","thumbnail":"https://i.ytimg.com/vi/XJpI3gkr5gI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-loch-morar-morag',
      'โมแร็ก (สัตว์ประหลาดแห่งทะเลสาบมอราร์)',
      'Morag (The Mysterious Monster of Loch Morar)',
      'monster',
      'ไฮแลนด์ (สกอตแลนด์)',
      'Highlands (Scotland)',
      'มอราร์',
      'Morar',
      56.96,
      -5.68,
      'water_spirit',
      'สัตว์ประหลาดในทะเลสาบน้ำจืดที่ลึกที่สุดในอังกฤษ (ลึกกว่า 310 เมตร) ลำตัวยาวกว่า 9 เมตร ผิวหนังสีน้ำตาลเข้ม มีโหนก 3 โหนกโผล่พ้นผิวน้ำ และหัวคล้ายงูยักษ์ เคยพุ่งเข้าชนเรือของชาวประมงท้องถิ่นในปี 1969 จนเป็นข่าวโด่งดังไปทั่วโลก',
      'The prehistoric aquatic cryptid inhabiting Loch Morar, Britain’s deepest body of freshwater (310m). Described as a 30-foot serpentine creature with undulating dorsal humps and a blunt reptilian head, famously striking fishermen in 1969.',
      'ชาวเกลิกโบราณถือว่าโมแร็กเป็นพรายน้ำหรือลางบอกเหตุร้าย หากใครพบเห็นโมแร็กขึ้นมาเหนือน้ำ แปลว่าจะเกิดการเสียชีวิตของสมาชิกตระกูลใหญ่ในแถบมอราร์',
      'Deeply rooted in Highland Gaelic lore as an omen of death or familial tragedy, studied extensively by the Loch Ness Investigation Bureau in the 1970s.',
      'ห้ามทอดสมอเรือข้ามคืนบริเวณร่องน้ำลึกกลางทะเลสาบมอราร์',
      'Never drop overnight anchors over the 1,000-foot central trench of Loch Morar.',
      'https://i.ytimg.com/vi/rwQyqi4pFBo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/rwQyqi4pFBo/hqdefault.jpg","title":"โมแร็ก (สัตว์ประหลาดแห่งทะเลสาบมอราร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=rwQyqi4pFBo","title":"Morag The Loch Morar Monster | Mythical creatures and fantastic beasts","thumbnail":"https://i.ytimg.com/vi/rwQyqi4pFBo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-flatwoods-monster-braxton',
      'สัตว์ประหลาดแฟลตวูดส์ (สิ่งมีชีวิตร่างยักษ์หัวสวมหมวกคลุมฮูด)',
      'The Flatwoods Monster (The Braxton County Green Phantom)',
      'monster',
      'เวสต์เวอร์จิเนีย (สหรัฐอเมริกา)',
      'West Virginia (United States)',
      'แบรกซ์ตันเคาน์ตี',
      'Braxton County',
      38.7214,
      -80.6517,
      'creepy_wind',
      'สิ่งมีชีวิตลึกลับความสูงกว่า 3 เมตรที่ปรากฏตัวหลังการตกของลูกไฟประหลาดในปี 1952 มีหัวรูปทรงคล้ายไพ่โพดำหรือฮูดทรงแหลม ดวงตาสีส้มเรืองแสง สวมกระโปรงโลหะสีเข้ม ลอยตัวเหนือพื้นดินพร้อมปล่อยละอองหมอกพิษกลิ่นฉุนที่ทำให้พยานหมดสติและล้มป่วย',
      'A ten-foot-tall extraterrestrial or cryptid encounter from September 1952. Sporting a spade-shaped cowl hood, glowing orange eye-slits, and dark pleated skirt, gliding silently amidst a nauseating chemical mist.',
      'เป็นหนึ่งในคดีสิ่งมีชีวิตต่างดาวที่ได้รับการบันทึกและสืบสวนอย่างเป็นทางการโดยกองทัพอากาศสหรัฐฯ ในโครงการ Project Blue Book จนกลายเป็นสัญลักษณ์ป๊อปคัลเจอร์ของเวสต์เวอร์จิเนีย',
      'Investigated under Project Blue Book and featured in global ufology annals, memorialized today with town museums and iconic roadside ceramic chair monuments.',
      'ห้ามสูดดมละอองหมอกสีแดงอมดำที่มีกลิ่นคล้ายกำมะถันในป่าทึบของแฟลตวูดส์',
      'Never inhale sulfurous reddish-black mist hovering low in Flatwoods woodlands.',
      'https://i.ytimg.com/vi/fN_Kti0P6Gw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/fN_Kti0P6Gw/hqdefault.jpg","title":"สัตว์ประหลาดแฟลตวูดส์ (สิ่งมีชีวิตร่างยักษ์หัวสวมหมวกคลุมฮูด)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=fN_Kti0P6Gw","title":"The Terrifying True Story of The Flatwoods Monster | Real or Hoax?","thumbnail":"https://i.ytimg.com/vi/fN_Kti0P6Gw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-dover-demon-massachusetts',
      'ปีศาจโดเวอร์ (สิ่งมีชีวิตหัวโตผิวสีส้มลึกลับ)',
      'The Dover Demon (The Bizarre Orange-Skinned Entity)',
      'monster',
      'แมสซาชูเซตส์ (สหรัฐอเมริกา)',
      'Massachusetts (United States)',
      'โดเวอร์',
      'Dover',
      42.2459,
      -71.2828,
      'whisper',
      'สิ่งมีชีวิตประหลาดที่ถูกพบเห็นโดยกลุ่มวัยรุ่นในคืนเดือนเมษายน 1977 ร่างกายผอมเก้งก้าง ศีรษะกลมโตคล้ายแตงโมไร้ผม ผิวหนังสีส้มอมชมพูเหมือนกระดาษทราย นิ้วมือเรียวยาวเกาะอยู่บนกำแพงหินริมถนน ดวงตาสีส้มส่องสว่างสะท้อนไฟหน้ารถ',
      'A bizarre humanoid cryptid sighted over 25 hours in April 1977 by independent teenage witnesses. Featuring a hairless bulbous head, glowing tapetum eyes, sandpaper-peach skin, and tendril-like elongated fingers grasping stone walls.',
      'สืบสวนโดยนักวิทยาแวมไพร์และสัตว์ลึกลับชื่อดัง ลอเรน โคลแมน ซึ่งสัมภาษณ์พยานทุกคนและพบว่าภาพสเก็ตช์ตรงกันอย่างน่าทึ่งโดยไม่มีการเตี๊ยมกัน',
      'Investigated by cryptozoologist Loren Coleman, who coined the term ''Dover Demon'' after analyzing identical independent witness sketches across Farm Street and Springdale Avenue.',
      'ห้ามจอดรถชะลอเลียบกำแพงหินโบราณบนถนนฟาร์มสตรีทในคืนเดือนมืด',
      'Do not idle vehicles alongside stone fences on Farm Street during late April nights.',
      'https://i.ytimg.com/vi/SqkLJK-X0L8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SqkLJK-X0L8/hqdefault.jpg","title":"ปีศาจโดเวอร์ (สิ่งมีชีวิตหัวโตผิวสีส้มลึกลับ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SqkLJK-X0L8","title":"Five decades later, the Dover Demon remains a Massachusetts mystery","thumbnail":"https://i.ytimg.com/vi/SqkLJK-X0L8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-beast-of-bray-road',
      'อสูรกายแห่งถนนเบรย์โรด (มนุษย์หมาป่าวิสคอนซิน)',
      'The Beast of Bray Road (The Wisconsin Werewolf)',
      'monster',
      'วิสคอนซิน (สหรัฐอเมริกา)',
      'Wisconsin (United States)',
      'เอลก์ฮอร์น',
      'Elkhorn',
      42.6728,
      -88.5434,
      'creepy_wind',
      'สัตว์ร้ายสรีระกึ่งมนุษย์กึ่งสุนัขป่าขนาดมหึมา สูงกว่า 2 เมตร ยืนสองขาได้อย่างคล่องแคล่ว ขนสีน้ำตาลเทาดกหนา แผงคอกำยำ ดวงตาสะท้อนแสงสีเหลืองอำพัน มักปรากฏตัวริมถนนลูกรังเพื่อกินซากสัตว์และกระโจนใส่รถยนต์ที่วิ่งผ่าน',
      'A terrifying bipedal canid cryptid terrorizing rural Walworth County since the late 1980s. Standing seven feet tall with wolf-like muzzle, muscular humanoid torso, and sharp curved claws tearing into roadside game.',
      'ได้รับความสนใจจากสื่อระดับชาติหลังจากนักข่าวท้องถิ่น ลินดา ก็อดฟรีย์ ตีพิมพ์บทสัมภาษณ์พยานหลายสิบคนที่เผชิญหน้ากับมนุษย์หมาป่าตัวจริงบนถนนเบรย์โรด',
      'Brought to national prominence by journalist Linda Godfrey in 1991, chronicling numerous credible police, farmer, and motorist sightings of upright wolf-men in Wisconsin.',
      'ห้ามลงจากรถเพื่อตรวจสอบซากกวางริมถนนเบรย์โรดในยามค่ำคืน',
      'Never exit your automobile to examine roadside deer carcasses along Bray Road after dark.',
      'https://i.ytimg.com/vi/Z01AvN0MxaE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Z01AvN0MxaE/hqdefault.jpg","title":"อสูรกายแห่งถนนเบรย์โรด (มนุษย์หมาป่าวิสคอนซิน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Z01AvN0MxaE","title":"The Mystery of the Beast of Bray Road in Elkhorn, WI","thumbnail":"https://i.ytimg.com/vi/Z01AvN0MxaE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-jersey-devil-pine-barrens',
      'ปีศาจเจอร์ซีย์ (บุตรคนที่ 13 แห่งป่าสนไพน์แบร์เรนส์)',
      'The Jersey Devil of the Pine Barrens',
      'monster',
      'นิวเจอร์ซีย์ (สหรัฐอเมริกา)',
      'New Jersey (United States)',
      'ไพน์แบร์เรนส์',
      'Pine Barrens',
      39.8143,
      -74.4985,
      'creepy_wind',
      'อสุรกายมีปีกบินในตำนานที่มีหัวคล้ายม้าหรือจิงโจ้ มีเขาแพะ ลำตัวคล้ายงูหรือจิงโจ้ ขาหลังเป็นกีบม้า และปีกพังผืดคล้ายค้างคาว บินร่อนเหนือยอดไม้พร้อมส่งเสียงกรีดร้องแหลมสูงจนสัตว์เลี้ยงหวาดผวา',
      'The legendary bipedal flying cryptid with kangaroo-like posture, horse-like head, bat wings, cloven hooves, and a serpentine tail, screeching through the dense, acidic cedar swamps of South Jersey.',
      'ตามตำนานเล่าว่าเกิดจากคำสาปของ ''แม่ลีดส์'' ในปี 1735 เมื่อเธอรู้ว่ากำลังตั้งครรภ์บุตรคนที่ 13 จึงเอ่ยปากสาปว่าขอให้เป็นปีศาจ ทันทีที่คลอด ทารกได้กลายร่างเป็นอสูรกายและบินหนีขึ้นปล่องไฟ',
      'Traced to the 1735 folklore curse of Mother Leeds in Estellville, generating widespread mass panic in January 1909 when schools closed across Delaware Valley due to mysterious hoofprints in snow.',
      'ห้ามตั้งแคมป์ลึกเข้าไปในป่าสนไพน์แบร์เรนส์นอกเขตที่กำหนดไว้',
      'Do not camp deep off-trail in the Pine Barrens pygmy forests without emergency beacons.',
      'https://i.ytimg.com/vi/TsTSNy3ttac/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TsTSNy3ttac/hqdefault.jpg","title":"ปีศาจเจอร์ซีย์ (บุตรคนที่ 13 แห่งป่าสนไพน์แบร์เรนส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TsTSNy3ttac","title":"The Jersey Devil: Myth or Nightmare?! | The UnXplained (Season 6) | History","thumbnail":"https://i.ytimg.com/vi/TsTSNy3ttac/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-lizard-man-scape-ore',
      'มนุษย์กิ้งก่าแห่งหนองน้ำสเคปออร์',
      'The Lizard Man of Scape Ore Swamp',
      'monster',
      'เซาท์แคโรไลนา (สหรัฐอเมริกา)',
      'South Carolina (United States)',
      'บิชอปวิลล์',
      'Bishopville',
      34.2185,
      -80.2445,
      'water_spirit',
      'สัตว์ประหลาดครึ่งคนครึ่งสัตว์เลื้อยคลาน สูงกว่า 2.1 เมตร ผิวหนังเป็นเกล็ดสีเขียวขรุขระ มีสามนิ้วมือขนาดใหญ่พร้อมกรงเล็บแหลมคมยาวสีดำ และดวงตาสีแดงฉาน เคยพุ่งเข้าขย้ำและฉีกทึ้งกระโปรงหน้ารถยนต์ของวัยรุ่นที่จอดเปลี่ยนยางริมบึง',
      'A seven-foot bipedal reptilian cryptid covered in swamp-green scaly hide with three large clawed pads per extremity and piercing red eyes, famously mauling motor vehicles in Lee County in 1988.',
      'เหตุการณ์เกิดขึ้นในเดือนมิถุนายน 1988 เมื่อคริสโตเฟอร์ เดวิส เผชิญหน้ากับมัน เจ้าหน้าที่ตำรวจท้องถิ่นพบรอยพิมพ์เท้าขนาด 35 เซนติเมตร 3 นิ้ว และรอยฟันกัดบนกันชนรถยนต์',
      'Documented by Sheriff Liston Truesdale in 1988 with plaster casts of 14-inch three-toed footprints and verifiable sheet-metal gouges on damaged pickup trucks.',
      'ห้ามลงจากรถเพื่อเปลี่ยนยางริมถนนตัดผ่านบึงสเคปออร์ยามพลบค่ำโดยไม่มีไฟส่องสว่าง',
      'Never perform roadside tire changes alongside Scape Ore swamp bottoms after sunset.',
      'https://i.ytimg.com/vi/zCkrTiwqxx8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zCkrTiwqxx8/hqdefault.jpg","title":"มนุษย์กิ้งก่าแห่งหนองน้ำสเคปออร์"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zCkrTiwqxx8","title":"The Secret of Scape Ore Swamp","thumbnail":"https://i.ytimg.com/vi/zCkrTiwqxx8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-chupacabra-canovanas-pr',
      'ชูปาคาบรา (อสูรดูดเลือดแพะแห่งเปอร์โตริโก)',
      'El Chupacabra (The Goat-Sucker of Canóvanas)',
      'monster',
      'คาโนวานาส (เปอร์โตริโก)',
      'Canovanas (Puerto Rico)',
      'เอลยุงเก',
      'El Yunque',
      18.3794,
      -65.901,
      'jungle_curse',
      'อสูรกายกระโดดได้คล้ายจิงโจ้ มีหนามแหลมหรือสันครีบเรียงรายบนแผ่นหลัง ดวงตาสีแดงเพลิงเรืองแสง และเขี้ยวแหลมสองคู่ที่ใช้เจาะคอสัตว์เลี้ยงเพื่อดูดเลือดจนแห้งสนิทโดยไม่มีร่องรอยการฉีกเนื้อ',
      'The original 1995 Puerto Rican bipedal cryptid with quill-lined spine, reptilian skin, and crimson alien eyes. Renowned for draining livestock blood completely dry through surgical puncture wounds.',
      'เริ่มรายงานครั้งแรกในเดือนมีนาคม 1995 ในเมืองคาโนวานาส เมื่อแกะและแพะหลายสิบตัวถูกพบเป็นศพเลือดหมดตัว ต่อมาข่าวลือแพร่สะพัดไปทั่วลาตินอเมริกาและตอนใต้ของสหรัฐฯ',
      'First witnessed by Madelyne Tolentino in Canóvanas in 1995, inspiring Latin American folkloric panic before mutating into mangy coyote sightings across mainland North America.',
      'ห้ามปล่อยฝูงแพะหรือสัตว์เลี้ยงไว้กลางทุ่งโล่งในคืนที่มีพายุฝนฟ้าคะนอง',
      'Do not leave livestock pens unbolted near rainforest margins during heavy tropical squalls.',
      'https://i.ytimg.com/vi/d-jkZE8AdLA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/d-jkZE8AdLA/hqdefault.jpg","title":"ชูปาคาบรา (อสูรดูดเลือดแพะแห่งเปอร์โตริโก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=d-jkZE8AdLA","title":"El Chupacabras, a Modern Mystery | Monstrum","thumbnail":"https://i.ytimg.com/vi/d-jkZE8AdLA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-mapinguari-amazon-beast',
      'มาปิงกวารี (สัตว์ยักษ์ดึกดำบรรพ์ปากกลางท้องแห่งแอมะซอน)',
      'Mapinguari (The Cyclops Sloth Beast of the Amazon Basin)',
      'monster',
      'อามาโซนัส (บราซิล)',
      'Amazonas (Brazil)',
      'ลุ่มน้ำจูรูอา',
      'Jurua River',
      -4.85,
      -66.8833,
      'jungle_curse',
      'อสูรกายร่างยักษ์ขนสีแดงหนาทึบ สูงกว่า 2 เมตรครึ่ง มีกรงเล็บโค้งขนาดมหึมาที่งองุ้มเข้าด้านใน กลิ่นสาบเน่าเหม็นรุนแรงจนทำให้คนสลบ ตำนานพื้นเมืองเล่าว่ามีตาเดียวตรงกลางหน้าผากและมีปากยักษ์อยู่ตรงกลางหน้าท้อง',
      'A formidable Amazonian cryptid resembling a surviving ground sloth (Megatherium). Standing over eight feet tall with matted reddish fur, inward-curving claws, an unbearable stench, and a gaping mouth upon its abdomen.',
      'ชนเผ่าพื้นเมืองในป่าแอมะซอนและนักชีววิทยาเชื่อว่าอาจเป็นความทรงจำทางพันธุกรรมหรือซากสัตว์ที่รอดชีวิตของ ''สลอธยักษ์ดึกดำบรรพ์'' ที่เคยท่องป่าอเมริกาใต้ในยุคไพลสโตซีน',
      'Hypothesized by cryptozoologists like David Oren to be an extant relict population of giant ground sloths preserved in the dense canopy of the Southwestern Amazon basin.',
      'หากได้ยินเสียงคำรามก้องสะท้านและได้กลิ่นซากสัตว์เน่าคละคลุ้งในดงทึบ ให้รีบปีนขึ้นที่สูงหรือถอยหนีทันที',
      'If a nauseating necrotic stench precedes a heavy bipedal crashing sound in dense canopy, retreat immediately upwind.',
      'https://i.ytimg.com/vi/yb2fBc9Ro1c/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yb2fBc9Ro1c/hqdefault.jpg","title":"มาปิงกวารี (สัตว์ยักษ์ดึกดำบรรพ์ปากกลางท้องแห่งแอมะซอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yb2fBc9Ro1c","title":"Mapinguari, the Giant Sloth Monster - Cryptid Profile","thumbnail":"https://i.ytimg.com/vi/yb2fBc9Ro1c/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curupira-backward-feet',
      'กูรูปีรา (ภูตพิทักษ์ป่าเท้ากลับหลังแห่งบราซิล)',
      'Curupira (The Backward-Footed Guardian of Brazilian Jungles)',
      'monster',
      'ปารา (บราซิล)',
      'Pará (Brazil)',
      'ทาปาโฮส',
      'Tapajós',
      -2.4431,
      -54.7083,
      'jungle_curse',
      'สิ่งมีชีวิตกึ่งมนุษย์ขนาดเล็กผมสีแดงเพลิงดั่งเปลวไฟ จุดเด่นคือเท้าหมุนกลับหลัง 180 องศา ทำให้รอยเท้าที่ทิ้งไว้บนพื้นดินหลอกพรานป่าให้เดินผิดทิศทางเสมอ ทำหน้าที่ปกป้องสัตว์ป่าและลงทัณฑ์ผู้ที่ล่าสัตว์เกินความจำเป็น',
      'A fiery-haired jungle protector in Brazilian indigenous folklore whose feet are turned completely backward to deceive poachers with misleading tracks, creating illusory whistles to disorient greedy hunters.',
      'บันทึกครั้งแรกโดยมิชชันนารีชาวโปรตุเกส โฮเซ เด อันชีเอตา ในปี 1560 ถือเป็นหนึ่งในตำนานพื้นบ้านที่เก่าแก่และได้รับการเคารพมากที่สุดในบราซิล',
      'Documented in 1560 by Jesuit priest Father José de Anchieta, representing pre-Columbian Tupi-Guarani ecological balance and forest stewardship.',
      'ห้ามล่าสัตว์ป่าตัวเมียที่กำลังตั้งครรภ์หรือตัดต้นไม้ใหญ่โดยไม่วางยาสูบเซ่นสรวง',
      'Never hunt pregnant game or fell elder jungle trees without leaving an offering of rolled tobacco.',
      'https://i.ytimg.com/vi/xpXfy11LT8I/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/xpXfy11LT8I/hqdefault.jpg","title":"กูรูปีรา (ภูตพิทักษ์ป่าเท้ากลับหลังแห่งบราซิล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xpXfy11LT8I","title":"Curupira: Brazil''s Forest Guardian","thumbnail":"https://i.ytimg.com/vi/xpXfy11LT8I/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ahool-giant-bat-java',
      'อาฮูล (ค้างคาวยักษ์ลึกลับแห่งป่าฝนเกาะชวา)',
      'The Ahool (The Giant Primordial Bat Cryptid of Java)',
      'monster',
      'ชวาตะวันตก (อินโดนีเซีย)',
      'West Java (Indonesia)',
      'ภูเขาซาลัก',
      'Mount Salak',
      -6.7144,
      106.7314,
      'jungle_curse',
      'สัตว์มีปีกดึกดำบรรพ์ขนาดยักษ์ที่มีปีกกว้างกว่า 3 เมตร ลำตัวปกคลุมด้วยขนสีเทาเข้ม มีหัวคล้ายลิงหรือมนุษย์ ดวงตากลมโตสีดำสนิท ร่อนลงมาโฉบจับปลาและสัตว์ในแม่น้ำลึก พร้อมส่งเสียงร้องก้องป่าว่า ''อา-ฮูลลล''',
      'A massive flying cryptid with a ten-foot leathery wingspan reported in rainforests around Mount Salak. Possessing flat ape-like facial features, thick dark gray fur, and emitting a piercing cry: ''A-hoool!''.',
      'บันทึกทางวิทยาศาสตร์ครั้งแรกโดยนักธรรมชาติวิทยา ดร. เออร์เนสต์ บาร์เทลส์ ในปี 1925 ขณะกำลังสำรวจน้ำตกบนเนินเขาซาลัก',
      'First chronicled in 1925 by naturalist Dr. Ernest Bartels while surveying waterfalls, theorized to represent either an unclassified giant megabat or surviving pterosaur relict.',
      'ห้ามกางเต็นท์นอนริมน้ำตกในหุบเขาซาลักโดยไม่จุดกองไฟให้สว่างตลอดคืน',
      'Never pitch tents beneath the gorge waterfalls of Mount Salak without an all-night watchfire.',
      'https://i.ytimg.com/vi/-zQf8XVdgTA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-zQf8XVdgTA/hqdefault.jpg","title":"อาฮูล (ค้างคาวยักษ์ลึกลับแห่งป่าฝนเกาะชวา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-zQf8XVdgTA","title":"Cryptozoology | Ahool IS REAL | Cryptid Wiki | Giant Bat Like Creature Spotted in Indonesia","thumbnail":"https://i.ytimg.com/vi/-zQf8XVdgTA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-orang-pendek-sumatra',
      'โอรังเปนเดก (มนุษย์วานรแคระแห่งป่าเกอรินชี)',
      'Orang Pendek (The Short Ground-Dweller of Sumatra)',
      'monster',
      'จัมบี (อินโดนีเซีย)',
      'Jambi (Indonesia)',
      'อุทยานแห่งชาติเกอรินชีเซบลัต',
      'Kerinci Seblat',
      -2.1583,
      101.4478,
      'jungle_curse',
      'สิ่งมีชีวิตคล้ายมนุษย์วานรแคระ ความสูงประมาณ 80-150 เซนติเมตร เดินสองขาได้อย่างมั่นคง ลำตัวปกคลุมด้วยขนสีทองหรือน้ำตาลไหม้ มีพละกำลังมหาศาลสามารถถอนรากต้นไม้ได้ อาศัยอยู่ในป่าดิบชื้นลึกของเกาะสุมาตรา',
      'A ground-dwelling bipedal hominid cryptid standing between 3 to 5 feet tall in Mount Kerinci rainforests. Powerfully built with broad shoulders, short golden-brown hair, and remarkable arm strength.',
      'มีรายงานการพบเห็นโดยชาวดัตช์และนักสำรวจมานานกว่าศตวรรษ การเก็บตัวอย่างเส้นผมและรอยพิมพ์เท้าโดยโครงการวิจัยสัตว์ป่าพบว่ามีดีเอ็นเอที่ไม่ตรงกับสัตว์เลี้ยงลูกด้วยนมชนิดใดในระบบ',
      'Documented by Dutch colonists since the early 1900s, subject to serious field research by National Geographic and the Flora and Fauna International team yielding unclassified primate hairs.',
      'ห้ามพกผลไม้สุกกลิ่นแรงหรือน้ำผึ้งป่าเข้าไปในเขตสงวนเกอรินชียามพลบค่ำ',
      'Do not transport pungent ripe jungle fruits or wild honey deep into Kerinci reserves after dusk.',
      'https://i.ytimg.com/vi/fEhVkWOnpdQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/fEhVkWOnpdQ/hqdefault.jpg","title":"โอรังเปนเดก (มนุษย์วานรแคระแห่งป่าเกอรินชี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=fEhVkWOnpdQ","title":"El Hominido mas Misterioso de Sumatra, el Mitico Orang Pendek","thumbnail":"https://i.ytimg.com/vi/fEhVkWOnpdQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-strigoi-romanian-vampire',
      'สตริกอย (ผีดูดเลือดและวิญญาณกระหายเลือดแห่งทรานซิลเวเนีย)',
      'The Strigoi (The Undead Blood Revenants of Wallachia)',
      'monster',
      'ทรานซิลเวเนีย (โรมาเนีย)',
      'Transylvania (Romania)',
      'บราซอฟ',
      'Brasov',
      45.6579,
      25.6012,
      'whisper',
      'อมนุษย์คืนชีพในคติชนโรมาเนีย สามารถแปลงร่างเป็นสัตว์ ดื่มเลือดเหยื่อ และล่องหนได้ เกิดจากคนบาปที่เสียชีวิตหรือทารกที่เกิดมาพร้อมเยื่อหุ้มรกคลุมศีรษะ ร่างกายในหลุมศพจะไม่เน่าเปื่อยแต่กลับมีใบหน้าแดงก่ำ',
      'The archetypal undead revenant of Romanian folklore capable of shapeshifting into predatory beasts, draining life force, and rising from consecrated graves with ruddy, blood-swollen visages.',
      'ชาวบ้านโรมาเนียในอดีตมีพิธีกรรม ''ขุดศพพิสูจน์'' หากพบศพไม่เน่าเปื่อยจะใช้หมุดเหล็กเผาไฟหรือไม้หนามตอกตรึงหัวใจเพื่อป้องกันไม่ให้ออกมาทำร้ายผู้คน',
      'The foundational ancestor of European vampire myths, culminating in rural grave exhumation rituals and hawthorn stakes practiced well into the 20th century in Oltenian villages.',
      'ห้ามก้าวข้ามหลุมศพที่ดินเพิ่งกลบใหม่ในคืนวันเซนต์แอนดรูว์',
      'Never step across newly mounded graves on the eve of Saint Andrew''s Day.',
      'https://i.ytimg.com/vi/1lSvtir0rwY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/1lSvtir0rwY/hqdefault.jpg","title":"สตริกอย (ผีดูดเลือดและวิญญาณกระหายเลือดแห่งทรานซิลเวเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=1lSvtir0rwY","title":"The Last Vampire Hunter: The Horrifying Exorcism of a Strigoi | Documentary","thumbnail":"https://i.ytimg.com/vi/1lSvtir0rwY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-selkie-seal-folk',
      'เซลกี (มนุษย์แมวน้ำแห่งหมู่เกาะออร์คนีย์)',
      'The Selkies (The Shapeshifting Seal Folk of Orkney)',
      'monster',
      'ออร์คนีย์ (สกอตแลนด์)',
      'Orkney Islands (Scotland)',
      'เซาท์โรนัลด์เซย์',
      'South Ronaldsay',
      58.8,
      -2.95,
      'water_spirit',
      'สิ่งมีชีวิตในตำนานเซลติกที่อาศัยอยู่ในทะเลในร่างแมวน้ำ แต่สามารถถอดคราบหนังแมวน้ำออกเพื่อกลายร่างเป็นมนุษย์หนุ่มสาวรูปงามเต้นรำบนโขดหินใต้แสงจันทร์ หากคราบหนังแมวน้ำถูกขโมยไป เธอจะไม่สามารถกลับลงสู่ทะเลได้อีก',
      'Enchanting marine shapeshifters in Celtic mythology living as seals in the cold northern seas, but shedding their pelts on isolated beaches to dance in human form beneath moonlit tides.',
      'เป็นแกนกลางของนิทานพื้นบ้านสกอตแลนด์และไอริช สะท้อนความผูกพันลึกซึ้งและความเคารพยำเกรงของชุมชนชาวประมงชายฝั่งต่อมหาสมุทรแอตแลนติกเหนือ',
      'Core to Scottish and Nordic maritime narratives, encapsulating romantic longing, ocean conservation ethics, and coastal identity along the stormy North Atlantic coasts.',
      'ห้ามทำลาย ซ่อน หรือเผาคราบหนังแมวน้ำที่พบบนชายหาดหินร้าง',
      'Never burn or desecrate a shed seal skin found upon secluded coastal rocks.',
      'https://i.ytimg.com/vi/olTINyY-DsE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/olTINyY-DsE/hqdefault.jpg","title":"เซลกี (มนุษย์แมวน้ำแห่งหมู่เกาะออร์คนีย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=olTINyY-DsE","title":"The Selkie: A Magical Folktale from the Sea | A Beautiful Celtic Folktale","thumbnail":"https://i.ytimg.com/vi/olTINyY-DsE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-kelpie-loch-waterhorse',
      'เคลปี (ม้าพรายน้ำกลืนวิญญาณแห่งสกอตแลนด์)',
      'The Kelpie (The Deceptive Water Horse of Scottish Lochs)',
      'monster',
      'สเตียร์ลิง (สกอตแลนด์)',
      'Stirling (Scotland)',
      'แม่น้ำฟอร์ธ',
      'River Forth',
      56.0125,
      -3.7556,
      'water_spirit',
      'ม้าพรายน้ำสีขาวบริสุทธิ์หรือสีดำสนิทที่ยืนสง่างามริมทะเลสาบ มีแผงคอเปียกชุ่มไปด้วยสาหร่าย ผิวหนังเหนียวเหมือนกาวดึงดูดให้เด็กหรือผู้คนขึ้นไปขี่ เมื่อเหยื่อขึ้นหลัง ม้าจะพุ่งกระโจนลงสู่น้ำลึกเพื่อจมเหยื่อและกลืนกิน',
      'A predatory aquatic spirit inhabiting Scottish lochs appearing as a magnificent pony beside churning currents. Its adhesive hide traps riders onto its back before plunging violently into abyss waters to devour them.',
      'เป็นนิทานคำเตือนโบราณที่พ่อแม่ชาวสก็อตใช้สั่งสอนบุตรหลานไม่ให้เข้าไปเล่นใกล้แหล่งน้ำลึกและวังน้ำวนที่เชี่ยวกราก',
      'A historic cautionary fable warning children against treacherous currents, celebrated in modern Scotland with the world''s largest equine sculptures, The Kelpies in Falkirk.',
      'ห้ามขึ้นขี่ม้าแปลกหน้าที่ยืนนิ่งไร้เจ้าของริมทะเลสาบร้าง',
      'Never mount an unfamiliar saddled horse standing unattended beside dark Scottish lochs.',
      'https://i.ytimg.com/vi/KgEi4r__LLE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KgEi4r__LLE/hqdefault.jpg","title":"เคลปี (ม้าพรายน้ำกลืนวิญญาณแห่งสกอตแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KgEi4r__LLE","title":"Kelpie - The Mysterious Black Horse of Scottish Folklore","thumbnail":"https://i.ytimg.com/vi/KgEi4r__LLE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-bunyip-murray-river',
      'บันยิป (อสูรกายแห่งบึงมืดในตำนานดรีมไทม์)',
      'The Bunyip (The Billabong Beast of Australian Dreamtime)',
      'monster',
      'นิวเซาท์เวลส์ (ออสเตรเลีย)',
      'New South Wales (Australia)',
      'ลุ่มน้ำเมอร์เรย์',
      'Murray River',
      -34.1167,
      142.15,
      'water_spirit',
      'อสูรกายครึ่งบกครึ่งน้ำสิงสถิตในหนองน้ำและบิลลาบอง (บึงน้ำขัง) มีหัวคล้ายสุนัขหรือจระเข้ เขี้ยวแหลมยาว ขนสีดำหนา และมีเสียงคำรามดังกึกก้องสะท้านบึงในคืนเดือนมืด ดึงสัตว์และมนุษย์ลงไปขย้ำใต้น้ำ',
      'A monstrous amphibious cryptid inhabiting murky billabongs and creek beds across Aboriginal Dreamtime lore. Sporting tusks, flippers, a dog-like snout, and a booming bellow that silences the bushveld at night.',
      'เป็นตำนานที่มีร่วมกันของชนพื้นเมืองอะบอริจินทั่วทวีปออสเตรเลีย นักชีววิทยาคาดว่าอาจมาจากความทรงจำต่อสัตว์มีกระเป๋าหน้าท้องยักษ์ดึกดำบรรพ์ ''ไดโปรโตดอน'' ที่เคยมีชีวิตอยู่ในยุคน้ำแข็ง',
      'Foundational to Aboriginal cosmology and settler folklore alike, frequently correlated by paleontologists with ancestral oral memories of extinct Pleistocene megafauna like Diprotodon.',
      'ห้ามเข้าไปตักน้ำในบึงบิลลาบองในยามวิกาลเมื่อเสียงแมลงเงียบสงัดลง',
      'Never draw water from isolated billabongs when native bird and frog calls suddenly fall dead silent.',
      'https://i.ytimg.com/vi/zSM6QbrvpDc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zSM6QbrvpDc/hqdefault.jpg","title":"บันยิป (อสูรกายแห่งบึงมืดในตำนานดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zSM6QbrvpDc","title":"Bunyip: Australia’s Mysterious Amphibian Monster | Monstrum","thumbnail":"https://i.ytimg.com/vi/zSM6QbrvpDc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-kamaitachi-weasel-wind',
      'คาไมทาจิ (สามพังพอนสายลมกรรไกรแห่งหิมะ)',
      'Kamaitachi (The Sickle-Clawed Wind Weasel Trio)',
      'monster',
      'นีงาตะ (ญี่ปุ่น)',
      'Niigata (Japan)',
      'นาโกะโอกะ',
      'Nagaoka',
      37.4467,
      138.8517,
      'creepy_wind',
      'โยไคพังพอนสามพี่น้องที่เคลื่อนไหวบนพายุหมุนด้วยความเร็วเหนือเสียง ตัวแรกจะพุ่งเข้าชนให้เหยื่อล้มลง ตัวที่สองใช้กรงเล็บคมดั่งเคียวกรีดเนื้อ และตัวที่สามจะทายาวิเศษห้ามเลือด ทำให้เหยื่อถูกกรีดเป็นแผลลึกโดยไม่รู้สึกเจ็บปวดในทันที',
      'A trio of supernatural weasels riding freezing wind vortices. The first pushes the unsuspecting victim down, the second slashes the flesh with razor-sharp scythe claws, and the third applies an anesthetic salve so the wound does not instantly bleed.',
      'กำเนิดในภูมิภาคที่มีหิมะตกหนักของญี่ปุ่น เป็นคำอธิบายปรากฏการณ์แผลแตกจากอากาศหนาวจัดและการถูกลมหมุนกรรโชกพัดจนผิวหนังบาดเจ็บ',
      'A staple of Hokuriku snowy mountain folklore, personifying the stinging lacerations caused by sub-zero vacuum gusts and sudden icy pressure differentials.',
      'ห้ามยืนเผชิญหน้ากับพายุหมุนฝุ่นหรือพายุลมวนหิมะที่พัดผ่านทุ่งโล่ง',
      'Never stand rigid facing dust devils or snow whirlwinds roaring across winter fields.',
      'https://i.ytimg.com/vi/Trp7HiHq2zM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Trp7HiHq2zM/hqdefault.jpg","title":"คาไมทาจิ (สามพังพอนสายลมกรรไกรแห่งหิมะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Trp7HiHq2zM","title":"Exploring Kamaitachi The Legend Yokai Sickle Weasel | Wind Spirits","thumbnail":"https://i.ytimg.com/vi/Trp7HiHq2zM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-jorogumo-spider-woman',
      'โจโรกุโมะ (ปีศาจแมงมุมสาวงามใยสังหาร)',
      'Jorogumo (The Binding Spider Weaver Maiden)',
      'monster',
      'คานากาวะ (ญี่ปุ่น)',
      'Kanagawa (Japan)',
      'คามาคุระ',
      'Kamakura',
      35.3197,
      139.5467,
      'whisper',
      'แมงมุมใยทองที่มีอายุยืนยาวเกิน 400 ปีจนบรรลุเวทมนตร์ สามารถจำแลงกายเป็นหญิงสาวสวยสะพรั่ง เล่นพิณบิวะขับกล่อมชายหนุ่มให้เคลิบเคลิ้ม ก่อนจะพ่นใยเหนียวพันธนาการร่างเหยื่อแล้วฉีดพิษกลืนกินเป็นอาหารในถ้ำมืด',
      'An ancient Golden Orb-Weaver spider living four centuries to attain shapeshifting powers. Transforming into an alluring courtesan playing the biwa lute, she lures samurai and travelers into secluded grottos before trapping them in venomous webs.',
      'ปรากฏในบันทึกนิทานเอโดะเรื่องน้ำตกโจเร็นบนคาบสมุทรอิซุ ซึ่งชาวบ้านสร้างศาลเจ้าเพื่อบูชาและขอความคุ้มครองจากนางพญาแมงมุม',
      'Rooted in Izu and Kamakura historical chronicles, notably tied to Joren Falls where shrines honor the spider spirit to secure protection from catastrophic drowning.',
      'ห้ามหยุดฟังเสียงดนตรีดีดสายพิณที่ดังก้องจากป่าไผ่รกร้างยามค่ำคืน',
      'Never follow the sound of biwa strings echoing from abandoned bamboo groves at twilight.',
      'https://i.ytimg.com/vi/BybUnOscH8U/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/BybUnOscH8U/hqdefault.jpg","title":"โจโรกุโมะ (ปีศาจแมงมุมสาวงามใยสังหาร)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=BybUnOscH8U","title":"Jorogumo - Beautiful Spider Lady | Japanese Urban Legend Yokai","thumbnail":"https://i.ytimg.com/vi/BybUnOscH8U/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-qilin-celestial-beast',
      'กิเลน (สัตว์สวรรค์มงคลห้าธาตุแห่งบูรพาทิศ)',
      'The Qilin (The Benevolent Celestial Chimera of the Orient)',
      'monster',
      'ชานตง (จีน)',
      'Shandong (China)',
      'ชวีฝู',
      'Qufu',
      35.5986,
      116.9839,
      'temple_bell',
      'สัตว์เทพมงคลสรีระผสมผสาน มีหัวมังกร มีเขาเดียว ลำตัวปกคลุมด้วยเกล็ดมังกรสีเขียวมรกตหรือทอง มีกีบม้าและหางวัว เท้าก้าวเดินบนอากาศโดยไม่เหยียบย่ำยอดหญ้าให้ช้ำ ปรากฏตัวเพื่อบอกข่าวมงคลและการกำเนิดของมหาปราชญ์',
      'The revered celestial chimera of East Asian cosmology, sporting a dragon’s head, single horn, iridescent dragon scales, cloven hooves, and ox tail. It treads so lightly upon clouds that it harms not a single blade of grass.',
      'ตามตำนานจีนโบราณ กิเลนปรากฏตัวก่อนการประสูติของขงจื๊อในเมืองชวีฝู เพื่อคายแผ่นหยกพยากรณ์ว่าเขาจะกลายเป็น ''กษัตริย์ไร้มงกุฎ'' ผู้สั่งสอนแผ่นดิน',
      'Recorded in the Book of Rites and Confucian annals, appearing prior to Confucius''s birth in Qufu to spit a jade tablet prophesying his moral mastery.',
      'ห้ามเบียดเบียนสัตว์มีครรภ์หรือทำลายความสงบของผืนป่าที่มีกิเลนปรากฏ',
      'Never harm pregnant wildlife or disrupt ancient groves where the auspicious Qilin is spotted.',
      'https://i.ytimg.com/vi/hS76_Z62HaE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/hS76_Z62HaE/hqdefault.jpg","title":"กิเลน (สัตว์สวรรค์มงคลห้าธาตุแห่งบูรพาทิศ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=hS76_Z62HaE","title":"Qilin | Chinese Beast of Serenity","thumbnail":"https://i.ytimg.com/vi/hS76_Z62HaE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-baize-white-beast',
      'ไป่เจ๋อ (สัตว์สวรรค์ปัญญาญาณผู้รู้แจ้งสรรพสิ่งลี้ลับ)',
      'Bai Ze (The Omniscient Nine-Eyed Beast of Ultimate Lore)',
      'monster',
      'ฉ่านซี (จีน)',
      'Shaanxi (China)',
      'ซีอาน',
      'Xi''an',
      34.3416,
      108.9398,
      'temple_bell',
      'สัตว์สวรรค์สีขาวบริสุทธิ์ มีเขาหลายคู่และมีดวงตา 9 ดวงทั่วลำตัว (สามดวงบนใบหน้า และหกดวงบนสีข้าง) สามารถพูดภาษามนุษย์ได้ มีปรีชาญาณล่วงรู้ข้อมูล รูปร่าง และวิธีปราบภูตผีปีศาจทั้งหมด 11,520 ชนิดในใต้หล้า',
      'A legendary white celestial beast possessing multiple horns and nine eyes across its face and flanks. It speaks all human tongues and comprehends the forms, habits, and banishing rituals of all 11,520 supernatural beings.',
      'เมื่อครั้งจักรพรรดิเหลือง (หวงตี้) เสด็จประพาสชายทะเลตะวันออก ได้พบกับไป่เจ๋อ จึงโปรดให้จดบันทึกภาพและคำอธิบายปีศาจทั้งหมดลงใน ''คัมภีร์ไป่เจ๋อถู'' เพื่อปกป้องราษฎรจากสิ่งชั่วร้าย',
      'Encountered by the Yellow Emperor beside the East Sea, who transcribed its knowledge into the legendary lost encyclopedic grimoire ''Bai Ze Tu'' to protect humanity from demonic deception.',
      'ห้ามบิดเบือนหรือลบล้างตำราบันทึกความรู้โบราณที่สืบทอดจากไป่เจ๋อ',
      'Never falsify or burn transcribed ancestral records regarding mythological wards.',
      'https://i.ytimg.com/vi/I8i2J-vqnGI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/I8i2J-vqnGI/hqdefault.jpg","title":"ไป่เจ๋อ (สัตว์สวรรค์ปัญญาญาณผู้รู้แจ้งสรรพสิ่งลี้ลับ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=I8i2J-vqnGI","title":"Baize — The Wise and Auspicious Divine Beast in Chinese Mythology","thumbnail":"https://i.ytimg.com/vi/I8i2J-vqnGI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sigbin-shadow-kangaroo',
      'ซิกบิน (อสูรเงาเดินถอยหลังดูดเลือดแห่งฟิลิปปินส์)',
      'The Sigbin (The Nocturnal Shadow Hound of the Visayas)',
      'monster',
      'เซบู (ฟิลิปปินส์)',
      'Cebu (Philippines)',
      'อาร์เกา',
      'Argao',
      9.8833,
      123.6,
      'creepy_wind',
      'สัตว์ร้ายลึกลับที่มีรูปร่างคล้ายแพะไม่มีเขาหรือจิงโจ้ เดินก้มหัวต่ำโดยเอาศีรษะมุดไว้ระหว่างขาหลัง เดินถอยหลัง มีหางยาวเหมือนแส้ที่ปล่อยกลิ่นสาบฉุนรุนแรง ออกล่าในคืนวันศุกร์ประเสริฐเพื่อดูดหัวใจและเลือดของเด็ก',
      'A shadow cryptid resembling a hornless goat or canine kangaroo, walking backward with its head tucked between its hind legs. Its whip-like tail emits a foul odor, and it preys on human shadows and hearts during Holy Week.',
      'ความเชื่อพื้นบ้านชาววิซายัสเล่าว่า หมอผีบางคนสามารถเลี้ยงซิกบินไว้ในไหดินเผาเพื่อใช้เป็นข้ารับใช้ในการเสกความมั่งคั่งและขโมยหัวใจของศัตรู',
      'Entrenched in Visayan mythology, where wealthy families were whispered to harbor captive sigbins within clay jars as magical familiars generating prosperity through dark pacts.',
      'ห้ามทิ้งหน้าต่างเปิดทิ้งไว้ในบ้านไม้ชนบทยามค่ำคืนช่วงสัปดาห์ศักดิ์สิทธิ์',
      'Do not leave rural wooden shutters ajar after nightfall during Visayan Holy Week.',
      'https://i.ytimg.com/vi/yrNzToCCzxM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yrNzToCCzxM/hqdefault.jpg","title":"ซิกบิน (อสูรเงาเดินถอยหลังดูดเลือดแห่งฟิลิปปินส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yrNzToCCzxM","title":"EPISODE 3: SIGBIN | VISAYAN NOCTURNES","thumbnail":"https://i.ytimg.com/vi/yrNzToCCzxM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-mahsuri-langkawi',
      'คำสาปพระนางมัสสุหรี (เจ็ดชั่วโคตรเกาะลังกาวี)',
      'The Curse of Mahsuri (The Seven Generations of Langkawi)',
      'curse',
      'เคดาห์ (มาเลเซีย)',
      'Kedah (Malaysia)',
      'เกาะลังกาวี',
      'Langkawi',
      6.3533,
      99.7892,
      'whisper',
      'โศกนาฏกรรมของหญิงสาวผู้บริสุทธิ์ที่ถูกปรักปรำว่าคบชู้และถูกประหารชีวิตด้วยกริชศักดิ์สิทธิ์ ยามคมกริชแทงทะลุอก โลหิตที่หลั่งออกมากลับเป็นสีขาวบริสุทธิ์เพื่อยืนยันความบริสุทธิ์ ก่อนสิ้นใจเธอได้สาปแช่งให้เกาะลังกาวีตกต่ำและไร้ความเจริญไปนานถึง 7 ชั่วอายุคน',
      'The tragic legend of Mahsuri, unjustly executed for adultery with an ancestral kris. White blood miraculously spurted from her mortal wound, and with her dying breath she cursed the isle of Langkawi to remain barren for seven generations.',
      'เกิดขึ้นในช่วงต้นศตวรรษที่ 19 ไม่นานหลังการประหาร กองทัพสยามได้เข้าบุกยึดลังกาวี เกิดทุ่งข้าวดำจากการเผาเสบียง และเกาะตกอยู่ในความซบเซาจนกระทั่งทายาทรุ่นที่ 7 ถือกำเนิดขึ้นในประเทศไทย ลังกาวีจึงพลิกฟื้นเป็นเมืองท่องเที่ยว',
      'Historical invasion by Siam shortly after her execution turned rice fields into ash (''Beras Terbakar''), plunging the island into poverty until the documented birth of her 7th generation descendant in Phuket.',
      'ห้ามนำดินหรือเศษหินจากบริเวณสุสานพระนางมัสสุหรีกลับออกไป',
      'Never take consecrated soil or memorial stones from Mahsuri''s shrine complex.',
      'https://i.ytimg.com/vi/mPqQwhkoL00/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/mPqQwhkoL00/hqdefault.jpg","title":"คำสาปพระนางมัสสุหรี (เจ็ดชั่วโคตรเกาะลังกาวี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=mPqQwhkoL00","title":"พระนางเลือดขาวมัสสุหรี ไขปริศนาคำสาปแห่งเกาะลังกาวี เป็นเรื่องจริงหรือแค่นิทาน !!?","thumbnail":"https://i.ytimg.com/vi/mPqQwhkoL00/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-orang-minyak-grease-man',
      'โอรังมินยัก (คำสาปชายน้ำมันมนต์ดำแห่งมาเลเซีย)',
      'Orang Minyak (The Cursed Oily Shadow Prowler)',
      'curse',
      'เนกรีเซมบีลัน (มาเลเซีย)',
      'Negeri Sembilan (Malaysia)',
      'เซเรมบัน',
      'Seremban',
      2.7258,
      101.9424,
      'creepy_wind',
      'ชายร่างเปลือยที่ชโลมกายด้วยน้ำมันดำมะเมื่อมเหนียวหนืด สามารถล่องหนในเงามืดและปีนป่ายกำแพงสูงได้อย่างคล่องแคล่ว เกิดจากผู้ฝึกมนต์ดำไสยศาสตร์ที่ทำสัญญาปีศาจข่มขืนหญิงสาวบริสุทธิ์ 21 คนเพื่อให้ได้พลังคงกระพัน',
      'A dark entity or black magic sorcerer coated from head to toe in slick petroleum grease. Slipping through secured doors and vanishing into night shadows, bound by a demonic oath to violate maidens to achieve occult mastery.',
      'เป็นตำนานความเชื่อและเหตุการณ์ความตื่นตระหนกทางสังคมที่แพร่หลายในมาเลเซียตั้งแต่ทศวรรษ 1950 โดยชาวบ้านจะแก้เคล็ดด้วยการให้สตรีสวมเสื้อผ้าที่ชุบด้วยน้ำเหงื่อของบิดาเพื่อขับไล่มนต์ดำ',
      'Deeply rooted in Malay Bomoh occultism, causing recurring community alerts in villages where residents guarded dormitories with blessed batik cloths.',
      'ห้ามปล่อยให้หญิงสาวนอนตามลำพังในห้องที่ไม่มีผ้ายันต์หรือคาถากำกับ',
      'Never leave young maidens unattended in unwarded chambers during local Orang Minyak sightings.',
      'https://i.ytimg.com/vi/LMgQ8NnTMXI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/LMgQ8NnTMXI/hqdefault.jpg","title":"โอรังมินยัก (คำสาปชายน้ำมันมนต์ดำแห่งมาเลเซีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LMgQ8NnTMXI","title":"Orang Minyak: The Oily Man Who Haunted 1950s Malaya — Legend or Panic?","thumbnail":"https://i.ytimg.com/vi/LMgQ8NnTMXI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-salem-witch-trials-gallows',
      'เนินเขาประหารแม่มดแห่งเซเลม',
      'Proctor''s Ledge and the Gallows Hill Witch Curse',
      'curse',
      'แมสซาชูเซตส์ (สหรัฐอเมริกา)',
      'Massachusetts (United States)',
      'เซเลม',
      'Salem',
      42.5201,
      -70.9083,
      'whisper',
      'ลานหินที่ผู้บริสุทธิ์ 19 คนถูกแขวนคอในคดีล่าแม่มดปี 1692 กิลส์ คอรีย์ ถูกทรมานด้วยการวางหินทับจนขาดใจตาย โดยก่อนตายเขาได้กล่าวสาปแช่งเมืองเซเลมและนายอำเภอทุกคนว่าจะมีจุดจบด้วยโรคร้ายและความฉิบหาย',
      'The historic execution site where 19 accused witches were hanged during the mass hysteria of 1692. Giles Corey, pressed to death under boulders, famously spat his dying curse: ''I curse you and Salem!'' upon the sheriff.',
      'คำสาปของคอรีย์เป็นจริงเมื่อนายอำเภอ จอร์จ คอร์วิน เสียชีวิตด้วยอาการหัวใจวายฉับพลันในวัย 30 ปี และนายอำเภอเซเลมรุ่นต่อๆ มาต่างเผชิญกับโรคร้ายและอุบัติเหตุกะทันหัน',
      'Corroborated by town mortality records where Sheriff Corwin died suddenly of heart failure at age 30, initiating a 300-year lore of cardiac tragedies among Essex County lawmen.',
      'ห้ามกล่าวคำสบประมาทต่อรายชื่อผู้เสียชีวิตที่จารึกไว้ในอนุสรณ์สถานล่าแม่มด',
      'Do not utter mocking chants before the inscribed memorial stones at Proctor’s Ledge.',
      'https://i.ytimg.com/vi/8gksEuJN04Q/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8gksEuJN04Q/hqdefault.jpg","title":"เนินเขาประหารแม่มดแห่งเซเลม"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8gksEuJN04Q","title":"The Salem Witch Hunt (Full Episode) | Witches: Truth Behind the Trials | National Geographic","thumbnail":"https://i.ytimg.com/vi/8gksEuJN04Q/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-eastern-state-penitentiary',
      'คุกขังเดี่ยวอาถรรพ์แห่งอีสเทิร์นสเตต',
      'The Cursed Isolation Cells of Eastern State Penitentiary',
      'curse',
      'เพนซิลเวเนีย (สหรัฐอเมริกา)',
      'Pennsylvania (United States)',
      'ฟิลาเดลเฟีย',
      'Philadelphia',
      39.9683,
      -75.1728,
      'whisper',
      'เรือนจำแห่งแรกของโลกที่ใช้ระบบ ''ขังเดี่ยวเด็ดขาด'' เพื่อบังคับให้นักโทษสำนึกบาปจนกระทั่งนักโทษจำนวนมากเสียสติและฆ่าตัวตาย ผู้คุมและนักท่องเที่ยวรายงานการพบเห็นใบหน้าหัวเราะเยาะเย้ยในเซลล์บล็อก 12 และเงาเงียบกริบในแดนประหาร',
      'The world''s first true penitentiary designed on strict Quaker solitary confinement, driving hundreds into gibbering madness. Cellblock 12 harbors demonic cackling faces, weeping spectral inmates, and echoing heavy boot steps.',
      'เปิดทำการในปี 1829 เคยคุมขังอัล คาโปน เจ้าพ่อมาเฟียชื่อดัง ซึ่งเขารายงานว่าถูกวิญญาณของเจมส์ คลาร์ก เหยื่อสังหารหมู่วันวาเลนไทน์ตามหลอกหลอนจนกรีดร้องขอความช่วยเหลือทุกคืน',
      'Held Al Capone in 1929, who was reportedly tormented by the shrieking ghost of St. Valentine''s Day Massacre victim James Clark throughout his luxury confinement.',
      'ห้ามปิดประตูล็อคตัวเองไว้ในห้องขังเดี่ยวร้างของเซลล์บล็อก 12',
      'Never latch locked cell doors shut while standing inside isolation block 12.',
      'https://i.ytimg.com/vi/hZsm49GGgQk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/hZsm49GGgQk/hqdefault.jpg","title":"คุกขังเดี่ยวอาถรรพ์แห่งอีสเทิร์นสเตต"},{"type":"youtube","url":"https://www.youtube.com/watch?v=hZsm49GGgQk","title":"RE - Eastern State Penitentiary Pennsylvania, USA","thumbnail":"https://i.ytimg.com/vi/hZsm49GGgQk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-bell-witch-cave-tennessee',
      'ถ้ำแม่มดเบลล์ (วิญญาณพยาบาทเคต แบตส์)',
      'The Bell Witch Cave and Entity of Adams',
      'curse',
      'เทนเนสซี (สหรัฐอเมริกา)',
      'Tennessee (United States)',
      'แอดัมส์',
      'Adams',
      36.5889,
      -87.0547,
      'whisper',
      'คดีการหลอกหลอนที่รุนแรงที่สุดในประวัติศาสตร์สหรัฐฯ ที่ทำให้จอห์น เบลล์ ล้มป่วยและเสียชีวิตจากยาพิษปริศนา วิญญาณแม่มดสามารถพูดคุย โต้เถียง เคลื่อนย้ายสิ่งของ และตบตีนายพลแอนดรูว์ แจ็กสัน จนต้องล่าถอยออกจากบ้าน',
      'America''s most famous poltergeist haunting, culminating in the 1820 poisoning death of family patriarch John Bell. The malevolent entity spoke in multiple voices, assaulted visitors, and routed future President Andrew Jackson.',
      'บันทึกในเอกสารประวัติศาสตร์ของรัฐเทนเนสซี เชื่อว่าเป็นวิญญาณของเคต แบตส์ เพื่อนบ้านที่มีข้อพิพาทเรื่องที่ดิน ถ้ำหินปูนบนที่ดินเดิมยังคงมีกระแสพลังงานอาถรรพ์ที่ทำให้ผู้มาเยือนเกิดอาการคลื่นไส้',
      'Documented in authentic 19th-century county records, the limestone cavern on the Bell farm remains an epicenter of psychokinetic cold spots and optical anomalies.',
      'ห้ามหยิบก้อนหินหรือสิ่งใดก็ตามออกจากถ้ำแม่มดเบลล์กลับไปบ้าน',
      'Strictly taboo to remove stones, fossils, or artifacts from inside Bell Witch Cave.',
      'https://i.ytimg.com/vi/n38FHZDg6_k/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/n38FHZDg6_k/hqdefault.jpg","title":"ถ้ำแม่มดเบลล์ (วิญญาณพยาบาทเคต แบตส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=n38FHZDg6_k","title":"The Mystery Of The Bell Witch Haunting | Boogeymen | Real History","thumbnail":"https://i.ytimg.com/vi/n38FHZDg6_k/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-winchester-mystery-house',
      'คฤหาสน์ปริศนาวินเชสเตอร์ (เขาวงกตหลอกผี 160 ห้อง)',
      'The Winchester Mystery House (The Labyrinth of 160 Rooms)',
      'curse',
      'แคลิฟอร์เนีย (สหรัฐอเมริกา)',
      'California (United States)',
      'แซนโฮเซ',
      'San Jose',
      37.3184,
      -121.9511,
      'creepy_wind',
      'คฤหาสน์เขาวงกตที่สร้างขึ้นอย่างต่อเนื่องตลอด 38 ปีโดยซาราห์ วินเชสเตอร์ ภรรยาหม้ายของทายาทปืนไรเฟิลวินเชสเตอร์ ตามคำเตือนของคนทรงว่าเธอต้องสร้างบ้านเพื่อหลอกและปลอบประโลมวิญญาณของผู้คนที่ถูกปืนวินเชสเตอร์สังหาร',
      'A continuous 38-year architectural labyrinth commissioned by Sarah Winchester. Guided by a medium, she built stairways leading into ceilings and doors opening into sheer drop-offs to bewilder spirits slain by Winchester rifles.',
      'มีห้องทั้งหมด 160 ห้อง ประตู 2,000 บาน และหน้าต่าง 10,000 บาน ลวดลายประดับเต็มไปด้วยเลข 13 และใยแมงมุม ปัจจุบันคนงานและนักท่องเที่ยวยังคงได้ยินเสียงเลื่อยไม้และค้อนตอกตะปูในยามดึก',
      'Spanning 24,000 square feet with spiderweb motifs and the recurrent occult number 13, caretakers report disembodied footsteps and carpenter hammer taps echoing through sealed attics.',
      'ห้ามเดินแยกตัวออกจากกลุ่มทัวร์เข้าไปในห้องลับที่ไม่มีทางออก',
      'Never wander away from designated tour routes into unmapped architectural corridors.',
      'https://i.ytimg.com/vi/Y9L8OUgAgrI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Y9L8OUgAgrI/hqdefault.jpg","title":"คฤหาสน์ปริศนาวินเชสเตอร์ (เขาวงกตหลอกผี 160 ห้อง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Y9L8OUgAgrI","title":"The UnXplained: Secrets of The Winchester Mystery House (Season 1) | History","thumbnail":"https://i.ytimg.com/vi/Y9L8OUgAgrI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-alcatraz-prison-d-block',
      'อาถรรพ์ห้องขังบล็อกดีแห่งคุกอัลคาทราซ',
      'The Phantom of Cell 14-D at Alcatraz Island',
      'curse',
      'แคลิฟอร์เนีย (สหรัฐอเมริกา)',
      'California (United States)',
      'อ่าวซานฟรานซิสโก',
      'San Francisco Bay',
      37.8267,
      -122.423,
      'whisper',
      'ห้องขังลงทัณฑ์ ''บล็อกดี'' (The Hole) ที่มืดสนิทและเย็นเยือกที่สุดในคุกเดอะร็อค ในทศวรรษ 1940 นักโทษรายหนึ่งกรีดร้องตลอดทั้งคืนว่ามีดวงตาสีแดงฉานคืบคลานเข้ามาบีบคอ รุ่งเช้าผู้คุมพบเขาเสียชีวิตเป็นศพโดยมีรอยนิ้วมือดำไหม้บีบรอบคอ',
      'Cell 14-D, the freezing punishment isolation vault of ''The Rock''. In the 1940s, an inmate screamed hysterically all night about an entity with glowing eyes strangling him; guards found him dead by morning with blackened choke marks.',
      'ก่อนการสร้างเรือนจำ ชนเผ่าพื้นเมืองโอห์โลนถือว่าเกาะนี้เป็นสถานที่ต้องคำสาปที่เต็มไปด้วยวิญญาณชั่วร้าย ใช้สำหรับเนรเทศผู้ละเมิดกฎเผ่าเท่านั้น',
      'Regarded by indigenous Ohlone peoples as an accursed rock harboring malevolent spirits used strictly for tribal banishment, predating its federal penitentiary incarnation.',
      'ห้ามยืนในห้องขัง 14-D เพียงลำพังเมื่อแสงไฟทางเดินดับลง',
      'Do not remain enclosed alone inside Cell 14-D when ambient corridor lighting cuts out.',
      'https://i.ytimg.com/vi/jMw1NAwYDbQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jMw1NAwYDbQ/hqdefault.jpg","title":"อาถรรพ์ห้องขังบล็อกดีแห่งคุกอัลคาทราซ"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jMw1NAwYDbQ","title":"The Ghostly Prisoners of Alcatraz • Ghost Files","thumbnail":"https://i.ytimg.com/vi/jMw1NAwYDbQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-stanley-hotel-room-217',
      'ห้อง 217 แห่งโรงแรมสแตนลีย์ (ต้นกำเนิด The Shining)',
      'Room 217 and the Hauntings of The Stanley Hotel',
      'curse',
      'โคโลราโด (สหรัฐอเมริกา)',
      'Colorado (United States)',
      'เอสเตสพาร์ก',
      'Estes Park',
      40.3831,
      -105.5189,
      'whisper',
      'โรงแรมสไตล์จอร์เจียนบนเทือกเขาร็อกกี สถานที่ที่สตีเฟน คิง เข้าพักในห้อง 217 จนได้รับแรงบันดาลใจในการเขียนนวนิยายสยองขวัญระดับโลก The Shining แขกมักพบเห็นวิญญาณแม่บ้านเอลิซาเบธ วิลสัน คอยจัดกระเป๋าเสื้อผ้า และเสียงเปียโนบรรเลงเองในห้องบอลรูม',
      'The historic hotel that inspired Stephen King''s ''The Shining'' during his 1974 stay in Room 217. Head housekeeper Elizabeth Wilson''s ghost packs guests'' clothes, while phantom children giggle along fourth-floor corridors.',
      'ในปี 1911 เกิดเหตุระเบิดของแก๊สในห้อง 217 ขณะที่เอลิซาเบธกำลังจุดตะเกียง แม้เธอจะรอดชีวิตแต่จิตวิญญาณของเธอยังคงผูกพันและคอยดูแลความเรียบร้อยของห้องพักตลอดไป',
      'Tied to a 1911 gas explosion survived by maid Elizabeth Wilson, whose benevolent yet uncanny presence continues to neatly fold clothes and unpack guests'' luggage.',
      'ห้ามเล่นเปียโนโบราณในห้องบอลรูมใหญ่โดยไม่ได้รับอนุญาตจากผู้ดูแล',
      'Do not strike keys on the vintage ballroom grand piano without permission.',
      'https://i.ytimg.com/vi/DGdsBsi8zM8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/DGdsBsi8zM8/hqdefault.jpg","title":"ห้อง 217 แห่งโรงแรมสแตนลีย์ (ต้นกำเนิด The Shining)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=DGdsBsi8zM8","title":"The Stanley Hotel - The Story Of Room 217 And Stephen King","thumbnail":"https://i.ytimg.com/vi/DGdsBsi8zM8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-crying-boy-cursed-painting',
      'ภาพวาดเด็กชายร้องไห้ต้องคำสาป (ไฟไหม้ล้างผลาญ)',
      'The Cursed Painting of the Crying Boy',
      'curse',
      'ยอร์กเชียร์ (สหราชอาณาจักร)',
      'Yorkshire (United Kingdom)',
      'รอเทอร์แฮม',
      'Rotherham',
      53.43,
      -1.35,
      'whisper',
      'ภาพพิมพ์เด็กชายผมทองกำลังหลั่งน้ำตา ผลงานของโจวานนี บราโกลิน ในช่วงทศวรรษ 1980 เกิดเหตุไฟไหม้บ้านเรือนในอังกฤษหลายสิบหลังจนวอดวายทั้งหลัง แต่ที่น่าประหลาดใจคือภาพวาดเด็กชายร้องไห้กลับรอดพ้นจากกองเพลิงโดยไม่มีแม้แต่รอยไหม้',
      'The infamous mass-produced 1980s portrait prints by Giovanni Bragolin. Fire brigades across northern England reported over 50 domestic blazes where houses burned entirely to cinders, yet the painting was pulled from ash untouched.',
      'หนังสือพิมพ์ The Sun ตีพิมพ์รายงานจนเกิดความตื่นตระหนก ประชาชนนับพันนำภาพวาดมามอบให้กองดับเพลิงเพื่อทำพิธีเผาทำลายหมู่เพื่อปลดเปลื้องคำสาป',
      'Investigated by the Yorkshire Fire Service in 1985, leading to widespread tabloid panic where thousands of prints were incinerated in supervised municipal bonfires.',
      'ห้ามแขวนภาพเด็กชายร้องไห้ไว้เหนือกำแพงเตาผิงหรือเครื่องใช้ไฟฟ้า',
      'Never display original prints of The Crying Boy adjacent to domestic heating hearths.',
      'https://i.ytimg.com/vi/ppvJTgycov8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ppvJTgycov8/hqdefault.jpg","title":"ภาพวาดเด็กชายร้องไห้ต้องคำสาป (ไฟไหม้ล้างผลาญ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ppvJTgycov8","title":"Every House That Burned Down Had the Same Painting Inside | The Crying Boy Curse","thumbnail":"https://i.ytimg.com/vi/ppvJTgycov8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-hands-resist-him-ebay-painting',
      'ภาพวาดมือพันธนาการ (ภาพอาถรรพ์แห่งอีเบย์)',
      'The Hands Resist Him (The Haunted eBay Painting)',
      'curse',
      'แคลิฟอร์เนีย (สหรัฐอเมริกา)',
      'California (United States)',
      'โอ๊คแลนด์',
      'Oakland',
      37.8044,
      -122.2712,
      'whisper',
      'ภาพวาดในปี 1972 โดย บิล สโตนแฮม แสดงภาพเด็กชายและตุ๊กตาเด็กหญิงไร้ชีวิต ยืนอยู่หน้าประตูกระจกที่มีมือขนาดเล็กนับสิบคู่ทาบอยู่จากความมืด กลายเป็นข่าวดังระดับโลกเมื่อผู้ขายบนอีเบย์ระบุว่าตัวละครในภาพขยับตัวและก้าวออกมาในยามดึก',
      'Painted in 1972 by Bill Stoneham, depicting a young boy and a lifeless girl doll standing before a glass door pressed with disembodied children''s hands. Sold on eBay in 2000 with warnings that the figures climbed out of the canvas at night.',
      'เจ้าของภาพและแกลเลอรีที่จัดแสดงรายงานว่า ผู้ชมจำนวนมากเกิดอาการเป็นลม คลื่นไส้ ร้องไห้โดยไร้สาเหตุ หรือสัมผัสได้ถึงกระแสลมร้อนพัดผ่านใบหน้า',
      'Achieved viral notoriety in early internet folklore, validated by gallery owners noting physical illness and psychological distress among viewers observing the painting.',
      'ห้ามจ้องมองฝ่ามือหลังประตูกระจกในภาพวาดต่อเนื่องเกินหนึ่งนาที',
      'Avoid fixed unbroken eye contact with the hands pressed against the glass pane.',
      'https://i.ytimg.com/vi/FvyIrijRPkM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/FvyIrijRPkM/hqdefault.jpg","title":"ภาพวาดมือพันธนาการ (ภาพอาถรรพ์แห่งอีเบย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=FvyIrijRPkM","title":"The Haunted Painting That Comes Alive: The Hands Resist Him","thumbnail":"https://i.ytimg.com/vi/FvyIrijRPkM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-james-dean-little-bastard',
      'ลิตเติลบาสตาร์ด (รถพอร์ชต้องสาปของเจมส์ ดีน)',
      'Little Bastard (The Cursed Porsche 550 Spyder of James Dean)',
      'curse',
      'แคลิฟอร์เนีย (สหรัฐอเมริกา)',
      'California (United States)',
      'โชเลม',
      'Cholame',
      35.7247,
      -120.2961,
      'creepy_wind',
      'รถสปอร์ตพอร์ช 550 สไปเดอร์ สีเงิน คันที่นักแสดงดาวรุ่ง เจมส์ ดีน ประสบอุบัติเหตุเสียชีวิตในปี 1955 ชิ้นส่วนอะไหล่ที่ถูกถอดขายต่อให้นักแข่งคนอื่นนำไปสู่การเกิดอุบัติเหตุรุนแรงและเสียชีวิตอย่างต่อเนื่อง ก่อนที่ตัวถังรถจะหายสาบสูญไปอย่างไร้ร่องรอย',
      'The silver Porsche 550 Spyder in which James Dean perished at age 24. Subsequent owners of its engine, transmission, and frame suffered catastrophic fatal crashes and garage fires before the wreckage vanished entirely.',
      'เซอร์อเล็ก กินเนสส์ (นักแสดงผู้รับบทโอบีวัน เคโนบี) เคยพบเจมส์ ดีน ก่อนเกิดเหตุ 7 วัน และเอ่ยปากเตือนอย่างน่าขนลุกว่า ''อย่าขึ้นไปขับรถคันนี้เด็ดขาด ถ้าคุณขับ คุณจะตายในนั้นภายในวันศุกร์หน้า''',
      'Famously forewarned by actor Sir Alec Guinness one week prior: ''Please do not get into it, if you get in that car you will be found dead in it by this time next week.''',
      'ห้ามนำชิ้นส่วนโลหะจากซากรถที่มีประวัติการชนเสียชีวิตมาติดตั้งในรถยนต์คันอื่น',
      'Never salvage mechanical drivetrains from catastrophic fatal vehicular wrecks.',
      'https://i.ytimg.com/vi/TGlLMfEuvkw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TGlLMfEuvkw/hqdefault.jpg","title":"ลิตเติลบาสตาร์ด (รถพอร์ชต้องสาปของเจมส์ ดีน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TGlLMfEuvkw","title":"The Haunting Story Of James Dean''s Cursed Car","thumbnail":"https://i.ytimg.com/vi/TGlLMfEuvkw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-bus-375-midnight-beijing',
      'รถเมล์สาย 375 เที่ยวเที่ยงคืนแห่งปักกิ่ง',
      'Bus 375 (The Midnight Ghost Bus of Beijing)',
      'curse',
      'ปักกิ่ง (จีน)',
      'Beijing (China)',
      'หยวนหมิงหยวน',
      'Yuanmingyuan',
      40.0075,
      116.3056,
      'creepy_wind',
      'ตำนานเมืองปักกิ่งปี 1995 เมื่อรถประจำทางเที่ยวสุดท้ายออกจากประตูพระราชวังฤดูร้อน รับชายลึกลับสามคนในชุดโบราณสมัยราชวงศ์ชิง หญิงชราบนรถสังเกตเห็นว่าพวกเขาลอยตัวเหนือพื้นและไม่มีขา จึงแกล้งโวยวายพาหนุ่มข้างตัวลงจากรถ สองวันต่อมารถคันดังกล่าวถูกพบจมอยู่ในอ่างเก็บน้ำพร้อมศพเน่าเปื่อย',
      'The chilling November 1995 urban legend of the final midnight bus leaving Yuanmingyuan. Three men in Qing dynasty robes boarded; an observant old woman noticed they hovered without feet and saved a youth. The bus was found submerged days later with decomposed remains.',
      'กลายเป็นหนึ่งในเรื่องเล่าสยองขวัญที่โด่งดังที่สุดในอินเทอร์เน็ตจีนยุคแรก มีการถกเถียงเรื่องการตรวจสอบบันทึกตำรวจและถังน้ำมันที่พบว่าเต็มไปด้วยเลือดสดแทนน้ำมัน',
      'A defining modern Chinese urban folklore narrative debated across early BBS forums, blending Qing imperial ghost lore with public transit dread.',
      'ห้ามขึ้นรถโดยสารเที่ยวสุดท้ายของคืนหากผู้โดยสารภายในรถนั่งนิ่งเงียบก้มหน้าทั้งหมด',
      'Do not board midnight buses if all waiting passengers remain unnaturally stiff and bowed.',
      'https://i.ytimg.com/vi/AkTgXO7jg9Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/AkTgXO7jg9Y/hqdefault.jpg","title":"รถเมล์สาย 375 เที่ยวเที่ยงคืนแห่งปักกิ่ง"},{"type":"youtube","url":"https://www.youtube.com/watch?v=AkTgXO7jg9Y","title":"Bus 375: The Last Bus To Fragrant Hills (China''s Most Mysterious Horror Story...)","thumbnail":"https://i.ytimg.com/vi/AkTgXO7jg9Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-cursed-chair-thomas-busby',
      'เก้าอี้มรณะของโทมัส บัสบี (ใครนั่งต้องตาย)',
      'The Busby Stoop Chair (The Dead Man''s Seat)',
      'curse',
      'นอร์ท ยอร์กเชียร์ (สหราชอาณาจักร)',
      'North Yorkshire (United Kingdom)',
      'เธิร์สก์',
      'Thirsk',
      54.2325,
      -1.3444,
      'whisper',
      'เก้าอี้ไม้โอ๊คโบราณของฆาตกร โทมัส บัสบี ผู้ถูกแขวนคอในปี 1702 ก่อนถูกนำตัวไปประหาร เขาได้สาปแช่งว่า ''ใครก็ตามที่กล้ามานั่งบนเก้าอี้ตัวนี้จะต้องตายอย่างทรมาน'' ตลอด 300 ปี มีผู้คนมากกว่า 60 คนที่ท้าทายนั่งบนเก้าอี้แล้วเสียชีวิตจากอุบัติเหตุแปลกประหลาด',
      'An 18th-century oak armchair cursed by murderer Thomas Busby before his 1702 hanging. More than sixty people who dared to sit in it reportedly died shortly after from sudden fatal accidents or aneurysms.',
      'เจ้าของผับท้องถิ่นตัดสินใจมอบเก้าอี้ตัวนี้ให้กับพิพิธภัณฑ์เธิร์สก์ในปี 1972 โดยภัณฑารักษ์ได้นำไปแขวนไว้บนผนังสูงเหนือพื้นดิน 1.5 เมตร เพื่อไม่ให้มีใครสามารถนั่งบนเก้าอี้ได้อีกเด็ดขาด',
      'Donated to Thirsk Museum in 1972 under strict condition that it be suspended high on a wall to prevent anyone from ever seating their mortal weight upon it again.',
      'ห้ามหย่อนตัวนั่งหรือพิงเก้าอี้บัสบีสตูปโดยเด็ดขาด',
      'Strictly forbidden to sit upon or physically contact the Busby chair frame.',
      'https://i.ytimg.com/vi/u6wlhAwim6M/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/u6wlhAwim6M/hqdefault.jpg","title":"เก้าอี้มรณะของโทมัส บัสบี (ใครนั่งต้องตาย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=u6wlhAwim6M","title":"The Curse of the Busby Stoop Chair: A Haunting Legacy","thumbnail":"https://i.ytimg.com/vi/u6wlhAwim6M/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-black-orlov-eye-of-brahma',
      'เพชรแบล็กออร์ลอฟ (คำสาปเนตรพระพรหม)',
      'The Black Orlov (The Cursed Eye of Brahma Diamond)',
      'curse',
      'ทมิฬนาฑู (อินเดีย)',
      'Tamil Nadu (India)',
      'ปอนดิเชอร์รี',
      'Pondicherry',
      11.9416,
      79.8083,
      'temple_bell',
      'เพชรสีเทาดำประกายเหล็กขนาด 67.5 กะรัต เดิมเป็นพระเนตรของเทวรูปพระพรหมในวิหารศักดิ์สิทธิ์ที่ถูกขโมยไป ผู้ครอบครองเพชรเม็ดนี้หลายคน รวมทั้งเจ้าหญิงแห่งรัสเซียและพ่อค้าอัญมณี ต่างจบชีวิตด้วยการกระโดดตึกฆ่าตัวตายอย่างเป็นปริศนา',
      'A mesmerizing 67.5-carat black diamond stolen from the eye of a consecrated Brahma idol in Pondicherry. A trail of subsequent aristocratic owners leaped to their deaths from European rooftops under overwhelming depressive delusions.',
      'เพื่อแก้คำสาป ช่างเจียระไนอัญมณีชื่อดังในนิวยอร์กได้ทำการตัดแบ่งเพชรออกเป็น 3 ส่วนในปี 1950 ทำให้พลังงานอาถรรพ์สลายตัวลงในที่สุด',
      'Re-cut into three distinct gems in 1950 by jewelers to disperse the sacred desecration hex, currently displayed in museums without recorded further casualties.',
      'ห้ามสวมใส่อัญมณีที่ได้มาจากการขโมยเทวรูปศักดิ์สิทธิ์โดยไม่ทำพิธีขอขมา',
      'Never wear consecrated temple jewels severed illicitly from sacred deity sanctums.',
      'https://i.ytimg.com/vi/lzFiz6Q4x9k/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/lzFiz6Q4x9k/hqdefault.jpg","title":"เพชรแบล็กออร์ลอฟ (คำสาปเนตรพระพรหม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=lzFiz6Q4x9k","title":"The Unbelievable Story of the Black Orlov, a Cursed Diamond","thumbnail":"https://i.ytimg.com/vi/lzFiz6Q4x9k/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-val-camonica-cursed-rock',
      'ภาพสลักหินต้องสาปแห่งวัลคามอนิกา',
      'The Cursed Petroglyphs of Val Camonica',
      'curse',
      'ลอมบาร์ดี (อิตาลี)',
      'Lombardy (Italy)',
      'เบรสชา',
      'Brescia',
      45.9556,
      10.3347,
      'creepy_wind',
      'หุบเขาที่มีภาพสลักหินโบราณยุคก่อนประวัติศาสตร์มากกว่า 250,000 ภาพ รวมถึงภาพ ''นักบินอวกาศโบราณ'' ที่สวมหมวกคลุมเรืองแสง ผู้ลักลอบขูดขีดหรือทำลายภาพสลักหินมักเผชิญกับอุบัติเหตุหินถล่มหรืออาการวิงเวียนศีรษะรุนแรงจนตกหน้าผา',
      'A prehistoric alpine valley harboring over 250,000 petroglyphs, including enigmatic helmeted radiant entities. Local folklore recounts violent stone avalanches and crushing vertigo befalling those who deface the sacred rock faces.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกแห่งแรกของอิตาลีโดยยูเนสโกในปี 1979 เป็นศูนย์กลางพิธีกรรมทางศาสนาของชนเผ่าคามุนนีโบราณนานกว่า 8,000 ปี',
      'Designated as Italy’s first UNESCO World Heritage Site in 1979, serving as a continuous sacred sanctuary for the Camunni alpine culture across eight millennia.',
      'ห้ามใช้อุปกรณ์ขูดขีด ลูบคลำ หรือเหยียบย่ำบนรอยสลักหินโบราณ',
      'Do not scrape, rub, or stand upon the prehistoric carved rock surfaces.',
      'https://i.ytimg.com/vi/Dorv5KIIMoo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Dorv5KIIMoo/hqdefault.jpg","title":"ภาพสลักหินต้องสาปแห่งวัลคามอนิกา"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Dorv5KIIMoo","title":"Italy ~ The Mysterious Valcamonica Petroglyphs","thumbnail":"https://i.ytimg.com/vi/Dorv5KIIMoo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-catacomb-capuchin-palermo',
      'สุสานมัมมี่กาปูชินแห่งปาแลร์โม (ความลับโรซาเลีย ลอมบาร์โด)',
      'The Capuchin Catacombs and the Blinking Mummy of Palermo',
      'curse',
      'ซิซิลี (อิตาลี)',
      'Sicily (Italy)',
      'ปาแลร์โม',
      'Palermo',
      38.1117,
      13.34,
      'whisper',
      'สุสานใต้ดินที่เก็บรักษาสภาพมัมมี่มากกว่า 8,000 ร่างที่แขวนเรียงรายบนกำแพงหิน ไฮไลต์คือร่างของ ''โรซาเลีย ลอมบาร์โด'' เด็กหญิงวัย 2 ขวบที่เสียชีวิตในปี 1920 แต่ร่างยังคงสภาพสมบูรณ์เหมือนคนนอนหลับ กล้องไทม์แลปส์จับภาพเปลือกตาของเธอที่ดูเหมือนกะพริบเปิดและปิดเองอย่างน่าอัศจรรย์',
      'An underground catacomb preserving 8,000 mummies standing upright in period attire. It houses Rosalia Lombardo, ''Sleeping Beauty'', whose preserved remains appear to open and close her crystalline eyes under ambient lighting shifts.',
      'สร้างโดยนักบวชคณะกาปูชินในศตวรรษที่ 16 สะท้อนปรัชญา ''Memento Mori'' (จงระลึกว่าเจ้าจะต้องตาย) ที่เตือนสติมนุษย์ถึงความไม่เที่ยงของชีวิต',
      'Maintained by the Capuchin friars as a stark Memento Mori contemplation chamber, exhibiting mummified aristocrats, monks, and children dressed in their finest attire.',
      'ห้ามสัมผัสหรือถ่ายภาพโดยใช้แฟลชต่อร่างมัมมี่ในสุสานใต้ดิน',
      'Strictly prohibited to touch embalmed remains or employ strobe flash photography.',
      'https://i.ytimg.com/vi/_xYv60dWfqw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_xYv60dWfqw/hqdefault.jpg","title":"สุสานมัมมี่กาปูชินแห่งปาแลร์โม (ความลับโรซาเลีย ลอมบาร์โด)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_xYv60dWfqw","title":"The Mystery Of Rosalia Lombardo, The ‘Blinking’ Mummy Who Appears To Open Her Eyes!! 😱","thumbnail":"https://i.ytimg.com/vi/_xYv60dWfqw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-island-of-the-dolls-xochimilco',
      'เกาะตุ๊กตาผีสิงแห่งโซชิมิลโก',
      'La Isla de las Muñecas (The Island of the Dolls)',
      'curse',
      'เม็กซิโกซิตี (เม็กซิโก)',
      'Mexico City (Mexico)',
      'โซชิมิลโก',
      'Xochimilco',
      19.2731,
      -99.0967,
      'whisper',
      'เกาะลอยน้ำ (ชีนัมปา) ที่เต็มไปด้วยตุ๊กตาเด็กเล่นเก่าแขนขาด ตาบอด และเน่าเปื่อยหลายพันตัวถูกแขวนไว้ตามกิ่งไม้ โดยดอน จูเลียน ซันตานา ชายผู้สันโดษที่แขวนตุ๊กตาเพื่อปลอบประโลมวิญญาณของเด็กหญิงที่จมน้ำเสียชีวิตริมตลิ่ง นักท่องเที่ยวรายงานว่าตุ๊กตาขยับหัวและกระซิบคุยกันในความมืด',
      'A mist-shrouded chinampa island hung with thousands of decaying, severed dolls by hermit Don Julián Santana to appease the drowning ghost of a young girl. Visitors report dolls swiveling their heads and whispering in the fog.',
      'ในปี 2001 ดอน จูเลียน ถูกพบจมน้ำเสียชีวิต ณ จุดเดียวกันกับที่เด็กหญิงเคยจมน้ำเสียชีวิตเมื่อ 50 ปีก่อนอย่างน่าขนลุก',
      'In 2001, Don Julián was discovered drowned at the exact same shoreline spot where he claimed to have found the girl’s body decades earlier.',
      'ห้ามปลดหรือขโมยตุ๊กตาออกจากกิ่งไม้บนเกาะเด็ดขาด',
      'Never untie, vandalize, or pocket a hanging doll from the island''s boughs.',
      'https://i.ytimg.com/vi/WkU-UP3JnvQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/WkU-UP3JnvQ/hqdefault.jpg","title":"เกาะตุ๊กตาผีสิงแห่งโซชิมิลโก"},{"type":"youtube","url":"https://www.youtube.com/watch?v=WkU-UP3JnvQ","title":"The Island of Dolls │Places You DON''T Want to Visit","thumbnail":"https://i.ytimg.com/vi/WkU-UP3JnvQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-crying-woman-la-llorona',
      'ลาโยโรนา (สตรีร่ำไห้ผู้สาปแช่งตนเองริมสายน้ำ)',
      'La Llorona (The Weeping Woman of Mexican Waters)',
      'curse',
      'มิโชอากัง (เม็กซิโก)',
      'Michoacán (Mexico)',
      'ทะเลสาบปัตซกวาโร',
      'Lake Pátzcuaro',
      19.5667,
      -101.6167,
      'water_spirit',
      'วิญญาณหญิงสาวในชุดคลุมขาวลอยเหนือน้ำ ร้องไห้คร่ำครวญโหยหวนว่า ''โอ้ ลูกๆ ของข้าอยู่ที่ไหน!'' เธอจมลูกแท้ๆ ของตัวเองลงในแม่น้ำด้วยความโกรธแค้นสามี ก่อนจะกระโดดน้ำตายตาม และต้องคำสาปให้ร่อนเร่หาร่างลูกไปชั่วนิรันดร์',
      'The ubiquitous Latin American weeping shade draped in white, doomed to wander riverbanks lamenting: ''¡Ay, mis hijos!'' after drowning her children in jealous fury. Hearing her wails up close means she is far away; hearing them far means she is beside you.',
      'ผสมผสานระหว่างคติชนสเปนและเทวีซิฮัวโกอัตล์ของชาวแอซเท็ก ซึ่งเคยส่งเสียงร้องเตือนภัยก่อนการล่มสลายของจักรวรรดิแอซเท็ก',
      'Syncretized from Aztec goddess Cihuacoatl who wept omens before the Spanish conquest, representing maternal grief and cautionary child-safety lore.',
      'ห้ามขานตอบรับเสียงสะอื้นไห้ที่ดังก้องริมแม่น้ำยามดึก',
      'Never answer or mimic weeping voices echoing along midnight riverbanks.',
      'https://i.ytimg.com/vi/TUAKQt4hnv8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TUAKQt4hnv8/hqdefault.jpg","title":"ลาโยโรนา (สตรีร่ำไห้ผู้สาปแช่งตนเองริมสายน้ำ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TUAKQt4hnv8","title":"La Llorona: The Weeping Ghost Created by a Mother’s Worst Sin","thumbnail":"https://i.ytimg.com/vi/TUAKQt4hnv8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-cursed-crossroads-robert-johnson',
      'ทางแยกขายวิญญาณให้ปีศาจแห่งโรเบิร์ต จอห์นสัน',
      'The Devil''s Crossroads of Robert Johnson',
      'curse',
      'มิสซิสซิปปี (สหรัฐอเมริกา)',
      'Mississippi (United States)',
      'คลาร์กสเดล',
      'Clarksdale',
      34.2001,
      -90.5709,
      'whisper',
      'สี่แยกถนนไฮเวย์ 61 และ 49 สถานที่ที่ตำนานเล่าว่า โรเบิร์ต จอห์นสัน นักดนตรีบลูส์ระดับตำนาน นำกีตาร์มาทำสัญญาขายวิญญาณให้กับชายร่างสูงสีดำ (ปีศาจ) ในเวลาเที่ยงคืน เพื่อแลกกับทักษะการเล่นกีตาร์ที่เก่งกาจเหนือมนุษย์ ก่อนจะเสียชีวิตอย่างเป็นปริศนาในวัย 27 ปี',
      'The legendary intersection of Highways 61 and 49 where blues genius Robert Johnson allegedly made a midnight pact with a tall shadow man to tune his guitar in exchange for his immortal soul, dying mysteriously at age 27.',
      'เป็นรากฐานของตำนาน ''คลับ 27'' และคติชนความเชื่อวูดู/ฮูดูของชาวแอฟริกัน-อเมริกันในแถบสามเหลี่ยมปากแม่น้ำมิสซิสซิปปี เกี่ยวกับทางแยกที่เป็นประตูเชื่อมสู่โลกวิญญาณ',
      'A mythic cornerstone of Delta Blues and African-American Hoodoo crossroad traditions honoring Papa Legba, launching the worldwide 27 Club music curse mythology.',
      'ห้ามยืนดีดสายกีตาร์ตัวเดียวเปล่าๆ กลางสี่แยกในเวลาเที่ยงคืนตรง',
      'Never tune an acoustic guitar solo at the crossroads precisely at midnight.',
      'https://i.ytimg.com/vi/qhchO_PNfYc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qhchO_PNfYc/hqdefault.jpg","title":"ทางแยกขายวิญญาณให้ปีศาจแห่งโรเบิร์ต จอห์นสัน"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qhchO_PNfYc","title":"Searching for the Crossroads in Mississippi (Where Robert Johnson Sold His Soul to the Devil)","thumbnail":"https://i.ytimg.com/vi/qhchO_PNfYc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-tequendama-falls-hotel',
      'โรงแรมฆ่าตัวตายแห่งน้ำตกเตเกนดามา',
      'The Suicide Hotel of Tequendama Falls',
      'curse',
      'กุนดินามาร์กา (โคลอมเบีย)',
      'Cundinamarca (Colombia)',
      'โซอาชา',
      'Soacha',
      4.5833,
      -74.3,
      'water_spirit',
      'คฤหาสน์หรูหราสไตล์ฝรั่งเศสที่สร้างอยู่ริมหน้าผาสูงชันเหนือน้ำตกเตเกนดามา (สูง 157 เมตร) กลายเป็นจุดหมายยอดนิยมของผู้ที่ต้องการจบชีวิตจนมีผู้กระโดดหน้าผาตายหลายร้อยคน วิญญาณของผู้ตายยังคงวนเวียนอยู่ตามระเบียงและหน้าต่างที่มองลงสู่หุบเหว',
      'A cliffside French-style manor perched over the 515-foot Tequendama Falls. During the mid-20th century it became notorious for hundreds of desperate souls leaping into the misty chasm, leaving spectral silhouettes pacing its stone terraces.',
      'ตามตำนานของชนเผ่ามุยสกาโบราณ เทพบอชิกาได้ใช้คทาผ่าหน้าผาหินเพื่อระบายน้ำท่วม ช่วยเหลือผู้คนจนเกิดเป็นน้ำตกแห่งนี้ ชาวพื้นเมืองจึงถือว่าที่นี่เป็นสถานที่ศักดิ์สิทธิ์ที่วิญญาณเดินทางสู่อีกภพภูมิ',
      'Rooted in pre-Columbian Muisca mythology of the divine god Bochica cracking the cliffs to drain floodwaters, later repurposed into a biodiversity museum to cleanse its tragic past.',
      'ห้ามยืนชะโงกหน้าข้ามราวระเบียงหน้าผาในขณะที่หมอกหนาพัดผ่าน',
      'Never lean over the stone parapets when heavy river vapors blind the gorge below.',
      'https://i.ytimg.com/vi/LbdbxSinQCw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/LbdbxSinQCw/hqdefault.jpg","title":"โรงแรมฆ่าตัวตายแห่งน้ำตกเตเกนดามา"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbdbxSinQCw","title":"The Haunted Hotel at Tequendama Falls","thumbnail":"https://i.ytimg.com/vi/LbdbxSinQCw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-giant-causeway-finn-mccool',
      'ไจแอนต์สคอสเวย์ (ทางเดินหินยักษ์ฟินน์ แมคคูล)',
      'The Giant''s Causeway (Finn McCool''s Hexagonal Basalt Columns)',
      'legend',
      'เคาน์ตีแอนทริม (ไอร์แลนด์เหนือ)',
      'County Antrim (Northern Ireland)',
      'บุชมิลส์',
      'Bushmills',
      55.2408,
      -6.5116,
      'water_spirit',
      'มหัศจรรย์แท่งหินบะซอลต์หกเหลี่ยมมากกว่า 40,000 แท่งที่เรียงซ้อนกันแน่นหนายื่นลงสู่ทะเลไอริช ตามตำนานเล่าว่าสร้างขึ้นโดย ''ฟินน์ แมคคูล'' นักรบยักษ์ชาวไอริช เพื่อสร้างสะพานเดินข้ามทะเลไปต่อสู้กับยักษ์เบนานดอนเนอร์แห่งสกอตแลนด์',
      'A geological and mythological marvel of 40,000 interlocking hexagonal basalt columns descending into the Irish Sea. Gaelic legend attributes the bridge to giant warrior Fionn mac Cumhaill stepping across to duel Scottish titan Benandonner.',
      'แม้ทางธรณีวิทยาจะเกิดจากการเย็นตัวอย่างรวดเร็วของลาวาภูเขาไฟเมื่อ 50-60 ล้านปีก่อน แต่ตำนานการหลอกลวงของอูนาภรรยาของฟินน์ที่แกล้งปลอมตัวสามีเป็นทารกตัวยักษ์จนเบนานดอนเนอร์หวาดกลัวยังคงเป็นมรดกเล่าขานอันเลื่องชื่อ',
      'Designated Northern Ireland''s only UNESCO World Heritage Site in 1986, celebrated worldwide for ancient Gaelic myth-making interwoven with tertiary volcanism.',
      'ห้ามขว้างปาหรือกะเทาะเศษแท่งหินบะซอลต์หกเหลี่ยมกลับไปเป็นที่ระลึก',
      'Strictly forbidden to chip or take hexagonal basalt fragments from the causeway.',
      'https://i.ytimg.com/vi/aQbyVYUob1o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/aQbyVYUob1o/hqdefault.jpg","title":"ไจแอนต์สคอสเวย์ (ทางเดินหินยักษ์ฟินน์ แมคคูล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=aQbyVYUob1o","title":"The Irish myth of the Giant''s Causeway - Iseult Gillespie","thumbnail":"https://i.ytimg.com/vi/aQbyVYUob1o/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-skara-brae-neolithic-orkney',
      'สคารา เบร (หมู่บ้านหินยุคหินใหม่อันสมบูรณ์แห่งออร์คนีย์)',
      'Skara Brae (The Neolithic Pompeii of the British Isles)',
      'legend',
      'ออร์คนีย์ (สกอตแลนด์)',
      'Orkney Islands (Scotland)',
      'แซนด์วิก',
      'Sandwick',
      59.0486,
      -3.3422,
      'whisper',
      'หมู่บ้านยุคหินใหม่อายุเก่าแก่กว่า 5,000 ปี (สร้างขึ้นก่อนปิรามิดอียิปต์) ที่ถูกพายุทรายพัดกระหน่ำจนถูกฝังซ่อนไว้อย่างสมบูรณ์แบบ ทั้งเตียงนอนหิน ตู้หิน และระบบระบายน้ำโบราณ เผยร่องรอยวิถีชีวิตและพิธีกรรมบูชาดวงดาวของบรรพชนผู้ลึกลับ',
      'A remarkably preserved 5,000-year-old Neolithic stone settlement unearthed by a violent storm in 1850. Pre-dating the pyramids of Giza, its stone furniture, hearths, and drainage systems reveal the ritual lives of Europe''s early pastoralists.',
      'ถูกค้นพบหลังพายุฤดูหนาวพัดเอาเนินทรายชายหาดออกในปี 1850 ได้รับการยกย่องให้เป็น ''ปอมเปอีแห่งสกอตแลนด์'' และมรดกโลกของยูเนสโก',
      'Heart of the UNESCO Heart of Neolithic Orkney World Heritage Site, providing unprecedented archaeological insight into communal ancient societies before its abrupt abandonment.',
      'ห้ามปีนป่ายหรือสัมผัสเฟอร์นิเจอร์หินทรายโบราณภายในบ้านใต้ดิน',
      'Never climb inside the enclosed stone dwellings or touch Neolithic flagstone slabs.',
      'https://i.ytimg.com/vi/djavHwSXmD4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/djavHwSXmD4/hqdefault.jpg","title":"สคารา เบร (หมู่บ้านหินยุคหินใหม่อันสมบูรณ์แห่งออร์คนีย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=djavHwSXmD4","title":"Skara Brae on Orkney - a village frozen in time","thumbnail":"https://i.ytimg.com/vi/djavHwSXmD4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-avebury-stone-circle-wiltshire',
      'วงหินโบราณเอฟเบอรี (วงแหวนหินเมกะลิธที่ใหญ่ที่สุดในโลก)',
      'Avebury Henge and Stone Circles (The Megalithic Ring of Wiltshire)',
      'legend',
      'วิลต์เชียร์ (สหราชอาณาจักร)',
      'Wiltshire (United Kingdom)',
      'เอฟเบอรี',
      'Avebury',
      51.4286,
      -1.8542,
      'temple_bell',
      'วงหินเมกะลิธยุคก่อนประวัติศาสตร์ที่ใหญ่ที่สุดในโลก โอบล้อมหมู่บ้านโบราณทั้งหมู่บ้าน ประกอบด้วยหินยักษ์น้ำหนักหลายสิบตันนับร้อยก้อน จัดวางตามแนวพลังงานเส้นเลย์ไลน์ (Ley Lines) ที่เชื่อว่าเป็นศูนย์กลางพิธีกรรมและการเชื่อมต่อพลังงานจักรวาล',
      'The largest prehistoric stone henge monument in the world, encompassing an entire medieval village. Featuring colossal megaliths aligned with subterranean ley line currents and celestial solstices.',
      'สร้างขึ้นเมื่อประมาณ 2,600 ปีก่อนคริสตกาล ในยุคกลางมีความพยายามทุบทำลายหินเพราะเชื่อว่าเป็นสิ่งชั่วร้ายของพวกนอกศาสนา จนเกิดตำนาน ''หมอตัดผมที่ถูกหินทับตาย'' ที่ค้นพบโครงกระดูกและเหรียญโบราณใต้หินยักษ์',
      'Constructed circa 2600 BC, famous for the medieval ''barber-surgeon'' skeleton found crushed under a buried monolith during 1930s Alexander Keiller excavations.',
      'ห้ามขีดเขียนหรือทาขี้ผึ้งลงบนพื้นผิวหินทรายโบราณซาร์เซน',
      'Do not deface, chalk, or affix adhesive candles to the sarsen megaliths.',
      'https://i.ytimg.com/vi/FRm4asydp7U/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/FRm4asydp7U/hqdefault.jpg","title":"วงหินโบราณเอฟเบอรี (วงแหวนหินเมกะลิธที่ใหญ่ที่สุดในโลก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=FRm4asydp7U","title":"Exploring the Avebury Landscape | Walking Through Prehistory","thumbnail":"https://i.ytimg.com/vi/FRm4asydp7U/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-tintagel-castle-king-arthur',
      'ปราสาททินทาเจล (จุดกำเนิดกษัตริย์อาร์เธอร์และพ่อมดเมอร์ลิน)',
      'Tintagel Castle and Merlin’s Cave (Birthplace of King Arthur)',
      'legend',
      'คอร์นวอลล์ (สหราชอาณาจักร)',
      'Cornwall (United Kingdom)',
      'ทินทาเจล',
      'Tintagel',
      50.6678,
      -4.7578,
      'creepy_wind',
      'ซากปราสาทหินโบราณบนแหลมหน้าผาสูงชันที่ยื่นออกสู่คลื่นลมแรงของมหาสมุทรแอตแลนติก ตามตำนานคือสถานที่ปฏิสนธิและถือกำเนิดของกษัตริย์อาร์เธอร์ โดยมี ''ถ้ำพ่อมดเมอร์ลิน'' อยู่เบื้องล่างหน้าผาที่น้ำทะเลซัดเข้าออกในยามน้ำขึ้น',
      'The dramatic clifftop ruins perched on the wild Cornish coast. Revered since Geoffrey of Monmouth as the conception site of legendary King Arthur, with Merlin''s Sea Cave echoing hollow oceanic swells beneath the chasm.',
      'เป็นศูนย์กลางการค้าและป้อมปราการของราชวงศ์คอร์นิชโบราณตั้งแต่ยุคหลังโรมัน มีการค้นพบแผ่นหินจารึกชื่อ ''อาร์โทกนู'' ซึ่งอาจเป็นต้นเค้าทางประวัติศาสตร์ของตำนานกษัตริย์อาร์เธอร์',
      'A vibrant 5th-to-7th century stronghold of the kings of Dumnonia; 1998 excavations yielded the ''Artognou Stone'', lending tantalizing weight to Arthurian lore.',
      'ห้ามลงไปในถ้ำเมอร์ลินในขณะที่น้ำทะเลกำลังหนุนสูงอย่างรวดเร็ว',
      'Never enter Merlin''s Cave without monitoring incoming Cornish Atlantic tides.',
      'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"ปราสาททินทาเจล (จุดกำเนิดกษัตริย์อาร์เธอร์และพ่อมดเมอร์ลิน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"The Entire History of Tintagel // Arthurian Castle Documentary","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-carnac-stones-megalith',
      'ทุ่งเสาหินคาร์แนค (กองทัพหินยืนยุคก่อนประวัติศาสตร์แห่งบริตตานี)',
      'The Carnac Stones (The Prehistoric Megalithic Alignments)',
      'legend',
      'บริตตานี (ฝรั่งเศส)',
      'Brittany (France)',
      'คาร์แนค',
      'Carnac',
      47.5858,
      -3.0781,
      'creepy_wind',
      'แนวหินตั้งโบราณมากกว่า 3,000 ก้อนที่เรียงรายขนานกันเป็นแนวยาวกว่า 4 กิโลเมตร ตามตำนานท้องถิ่นเล่าว่า นักบุญคอร์เนลีได้เสกทหารกองทัพโรมันที่กำลังไล่ล่าพระองค์ให้กลายเป็นแท่งหินยืนแข็งทื่อไปตลอดกาล',
      'Over 3,000 prehistoric standing stones stretching in meticulous geometric rows across the Breton countryside. Breton folklore claims Saint Cornély turned an invading Roman army into stone columns where they stood.',
      'สร้างขึ้นเมื่อประมาณ 4,500 ปีก่อนคริสตกาล เก่าแก่กว่าสโตนเฮนจ์และปิรามิด ถือเป็นหนึ่งในปริศนาทางวิศวกรรมและการดูดาวที่ยิ่งใหญ่ที่สุดของมนุษยชาติยุคโบราณ',
      'Erected during the Neolithic era around 4500 BC, functioning as celestial observation instruments, ancestral burial grounds, and markers of seismic energy lines.',
      'ห้ามเคลื่อนย้ายหินคาร์แนคขนาดเล็กหรือจุดไฟบูชาในบริเวณแนวหินตั้ง',
      'Never displace alignment rocks or light unapproved campfires among the stone rows.',
      'https://i.ytimg.com/vi/o_i8PBQZBUE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/o_i8PBQZBUE/hqdefault.jpg","title":"ทุ่งเสาหินคาร์แนค (กองทัพหินยืนยุคก่อนประวัติศาสตร์แห่งบริตตานี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=o_i8PBQZBUE","title":"The mystery behind the megaliths of France’s Brittany region","thumbnail":"https://i.ytimg.com/vi/o_i8PBQZBUE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-fosse-dionne-bottomless-spring',
      'ฟอสส์ ดิออน (ตาน้ำลึกไร้ก้นและตำนานงูยักษ์แห่งตงแนร์)',
      'Fosse Dionne (The Bottomless Karst Spring of Tonnerre)',
      'legend',
      'ยอน (ฝรั่งเศส)',
      'Yonne (France)',
      'ตงแนร์',
      'Tonnerre',
      47.8558,
      3.9742,
      'water_spirit',
      'บ่อน้ำพุธรรมชาติสีฟ้าอมเขียวมรกตอันงดงามที่สร้างเป็นบ่อซักผ้ายุคศตวรรษที่ 18 มีน้ำพวยพุ่งออกมาวันละหลายล้านลิตรโดยไม่มีใครทราบว่าต้นน้ำมาจากไหน นักประดาน้ำหลายคนต้องสละชีวิตในถ้ำหินปูนใต้ดินอันลึกชันจนได้ชื่อว่าตาน้ำไร้ก้น',
      'A mesmerizing circular spring of turquoise water discharging 300 liters per second from an unexplored subterranean cave system. Multiple speleologists died attempting to map its uncharted karst depths.',
      'ในยุคกลางเชื่อว่าเป็นที่อยู่ของงูยักษ์บาซิลิสก์ที่ถูกสังหารโดยนักบุญฌองแห่งเรโอม น้ำในบ่อได้รับการบูชาในฐานะเทพีดีโอนาแห่งน้ำพุศักดิ์สิทธิ์ของชาวเคลต์โบราณ',
      'Venerated by the Celts as the sacred spring of spring goddess Divona, later tied to Christian legends of Saint John of Réome banishing a deadly subterranean basilisk.',
      'ห้ามโยนเหรียญหรือสิ่งแปลกปลอมลงไปในใจกลางช่องถ้ำน้ำพุ',
      'Do not toss metallic refuse or foreign objects into the subterranean spring basin.',
      'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"ฟอสส์ ดิออน (ตาน้ำลึกไร้ก้นและตำนานงูยักษ์แห่งตงแนร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"The Horrifying Incidents in This Bottomless Cave","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-neuschwanstein-curse-ludwig',
      'ปราสาทนอยชวานชไตน์ (คำสาปและโศกนาฏกรรมของกษัตริย์ลุดวิกที่ 2)',
      'Neuschwanstein Castle and the Tragic Fate of King Ludwig II',
      'legend',
      'บาวาเรีย (เยอรมนี)',
      'Bavaria (Germany)',
      'ชวานเกา',
      'Schwangau',
      47.5576,
      10.7498,
      'creepy_wind',
      'ปราสาทเทพนิยายที่งดงามที่สุดในโลก สร้างขึ้นบนยอดเขาสูงชันโดยกษัตริย์ลุดวิกที่ 2 แห่งบาวาเรีย เพื่อหลบหนีจากโลกความจริงสู่โลกแห่งอุปรากรของวากเนอร์ พระองค์ถูกถอดถอนจากราชบัลลังก์ในข้อหาวิกลจริต และถูกพบจมน้ำเสียชีวิตอย่างเป็นปริศนาในทะเลสาบชตาร์นแบร์ก',
      'The archetypal fairy-tale castle crowning the Bavarian Alps, built by ''Mad King'' Ludwig II as an operatic homage to Richard Wagner. Deposed on grounds of insanity, Ludwig died mysteriously days later submerged in Lake Starnberg.',
      'สร้างขึ้นระหว่างปี 1869-1886 ลุดวิกได้นอนพักในปราสาทเพียง 11 คืนเท่านั้นก่อนจะสิ้นพระชนม์ กลายเป็นต้นแบบของปราสาทซินเดอเรลลาของดิสนีย์',
      'Inspiring Disney’s Sleeping Beauty Castle, its unfinished gothic halls remain an enduring monument to romantic obsession, financial ruin, and unsolved state assassination theories.',
      'ห้ามก้าวข้ามแนวกั้นเพื่อเข้าไปในห้องบัลลังก์ที่ยังสร้างไม่เสร็จ',
      'Never bypass stanchions into the unfinished Byzantine Throne Hall.',
      'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"ปราสาทนอยชวานชไตน์ (คำสาปและโศกนาฏกรรมของกษัตริย์ลุดวิกที่ 2)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"The Madness of King Ludwig II","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-brocken-mountain-walpurgis',
      'ยอดเขาบร็อกเคิน (ชุมนุมแม่มดแห่งคืนวัลเพอร์กิส)',
      'The Brocken Spectre and Walpurgis Night of the Harz Mountains',
      'legend',
      'แซกโซนี-อันฮัลต์ (เยอรมนี)',
      'Saxony-Anhalt (Germany)',
      'เทือกเขาฮาร์ซ',
      'Harz Mountains',
      51.8,
      10.6156,
      'creepy_wind',
      'ยอดเขาที่สูงที่สุดในเทือกเขาฮาร์ซ ปกคลุมด้วยหมอกหนาทึบตลอดปี เป็นสถานที่รวมตัวของเหล่าแม่มดใน ''คืนวัลเพอร์กิส'' (30 เมษายน) และเป็นต้นกำเนิดของปรากฏการณ์ ''บร็อกเคินสเปกเตอร์'' เงาร่างมนุษย์ยักษ์ลอยอยู่กลางม่านหมอกล้อมรอบด้วยวงแสงสีรุ้ง',
      'The mist-cloaked crown of the Harz Mountains, legendary assembly site of witches dancing with the devil on Walpurgis Night. Home to the optical Brocken Spectre—a colossal shadowy apparition crowned by a rainbow halo (glory) in fog.',
      'ได้รับการถ่ายทอดในวรรณกรรมชิ้นเอก Faust ของเกอเธอ และเป็นสถานที่ทางดาราศาสตร์และมานุษยวิทยาที่อธิบายการสะท้อนเงาของตนเองลงบนม่านหมอกย้อนแสง',
      'Immortalized in Goethe’s masterpiece ''Faust'', celebrated every spring with costumed pagan festivals and scientific study of atmospheric optical phenomena.',
      'ห้ามเดินป่าออกนอกเส้นทางบนยอดเขาบร็อกเคินในคืนวันที่ 30 เมษายน',
      'Avoid hiking off-trail on the Brocken summit during Walpurgisnacht.',
      'https://i.ytimg.com/vi/gTaGDlvTuzo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/gTaGDlvTuzo/hqdefault.jpg","title":"ยอดเขาบร็อกเคิน (ชุมนุมแม่มดแห่งคืนวัลเพอร์กิส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=gTaGDlvTuzo","title":"Walpurgis Night on Brocken Mountain","thumbnail":"https://i.ytimg.com/vi/gTaGDlvTuzo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-pompeii-ruins-vesuvius',
      'เมืองปอมเปอี (คำสาปและเถ้าถ่านแห่งภูเขาไฟวิสุเวียส)',
      'Pompeii (The Entombed City of Mount Vesuvius)',
      'legend',
      'กัมปาเนีย (อิตาลี)',
      'Campania (Italy)',
      'เนเปิลส์',
      'Naples',
      40.7508,
      14.4869,
      'whisper',
      'นครโรมันโบราณที่ถูกฝังทั้งเป็นใต้เถ้าถ่านภูเขาไฟวิสุเวียสในปี ค.ศ. 79 ผู้คนนับหมื่นถูกสตัฟฟ์ไว้ในอิริยาบถสุดท้ายแห่งชีวิต หุ่นปูนปลาสเตอร์ของเหยื่อสะท้อนความเจ็บปวดและความตกใจอย่างน่าสะพรึงกลัว นักท่องเที่ยวที่ขโมยหินหรือกระเบื้องโมเสกมักส่งคืนพร้อมจดหมายสารภาพว่าต้องคำสาปจนครอบครัวพังพินาศ',
      'The ancient Roman metropolis frozen in time by the cataclysmic eruption of Mount Vesuvius in 79 AD. The museum receives hundreds of stolen mosaic tiles mailed back annually with letters detailing the horrific curses and ill luck suffered by thieves.',
      'จดหมายเหตุของพลินีผู้เยาว์บันทึกภาพควันภูเขาไฟที่พุ่งขึ้นคล้ายต้นสนไพน์ ก่อนที่คลื่นความร้อนไพโรคลาสติกจะกวาดล้างทุกสิ่งในเวลาเพียงไม่กี่วินาที',
      'Documented by Pliny the Younger, the excavated ruins offer an astounding portal into Roman street life, alongside the famous ''Curse of Pompeii'' affecting relic smugglers.',
      'ห้ามหยิบฉวยก้อนหิน กระเบื้อง หรือเศษเถ้าถ่านใดๆ ออกจากโบราณสถานปอมเปอี',
      'Never steal mosaic fragments, pottery, or volcanic pumice stones from Pompeii.',
      'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"เมืองปอมเปอี (คำสาปและเถ้าถ่านแห่งภูเขาไฟวิสุเวียส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"Why Tourists FEAR the Pompeii Curse (And Return Stolen Artifacts!)","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-oracle-of-delphi-apollo',
      'วิหารแห่งเดลฟี (คำทำนายแห่งเทพอะพอลโลและรอยแยกพยากรณ์)',
      'The Oracle of Delphi (The Pythia and Apollo’s Prophetic Chasm)',
      'legend',
      'โฟซิส (กรีซ)',
      'Phocis (Greece)',
      'เดลฟี',
      'Delphi',
      38.4824,
      22.501,
      'temple_bell',
      'ศูนย์กลางของโลกโบราณ (ออมฟาลอส) ตามคติกรีก ที่ซึ่งนักบวชหญิงไพเธียจะนั่งบนเก้าอี้สามขาเหนือรอยแยกของแผ่นดิน สูดดมไอระเหยลึกลับจนเข้าสู่ภวังค์และกล่าวคำทำนายที่กำหนดชะตากรรมของกษัตริย์และมหาสงคราม',
      'The spiritual navel (Omphalos) of the ancient Mediterranean world. High priestess Pythia inhaled ethylene vapors rising from a geological chasm beneath Apollo''s temple, delivering ambiguous prophecies that shaped kingdoms and empires.',
      'ตามตำนาน เทพอะพอลโลได้สังหารงูยักษ์ไพธอนเพื่อชิงวิหารแห่งนี้ นักธรณีวิทยาสมัยใหม่ยืนยันว่าใต้ซากวิหารมีรอยเลื่อนตัดกันสองเส้นที่ปล่อยก๊าซเอทิลีนที่มีฤทธิ์ทำให้เคลิบเคลิ้ม',
      'Archaeological and geological surveys by Jelle de Boer confirmed active intersecting fault lines beneath the adyton releasing sweet-smelling neurotoxic ethylene gas.',
      'ห้ามกล่าวคำทำนายสาบแช่งหรือดูหมิ่นแท่นหินออมฟาลอสแห่งเดลฟี',
      'Do not mock prophetic utterances before the sacred naval Omphalos stone.',
      'https://i.ytimg.com/vi/RGG2rDNX_xU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/RGG2rDNX_xU/hqdefault.jpg","title":"วิหารแห่งเดลฟี (คำทำนายแห่งเทพอะพอลโลและรอยแยกพยากรณ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=RGG2rDNX_xU","title":"The Oracle of Delphi - The Temple of Apollo - Mythological Curiosities - See U in History","thumbnail":"https://i.ytimg.com/vi/RGG2rDNX_xU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-knossos-labyrinth-minotaur',
      'พระราชวังคนอสซอส (เขาวงกตและอสูรคนอร์สมิโนทอร์)',
      'The Palace of Knossos and the Labyrinth of the Minotaur',
      'legend',
      'ครีต (กรีซ)',
      'Crete (Greece)',
      'เฮราคลิออน',
      'Heraklion',
      35.2979,
      25.1631,
      'whisper',
      'ศูนย์กลางอารยธรรมมิโนอันโบราณ พระราชวังหลายชั้นที่มีโครงสร้างซับซ้อนคล้ายเขาวงกต ตามตำนานคือสถานที่คุมขังมิโนทอร์ อสูรกายร่างมนุษย์หัววัวที่กินมนุษย์เป็นอาหาร ก่อนจะถูกสังหารโดยเจ้าชายธีซิอุสด้วยความช่วยเหลือของด้ายนำทางจากเจ้าหญิงอาริแอดเน',
      'The multi-tiered Bronze Age palace of King Minos, renowned as the mythological maze designed by Daedalus to imprison the flesh-eating bull-headed Minotaur, ultimately slain by Theseus using Ariadne''s thread.',
      'ขุดค้นโดยเซอร์อาร์เธอร์ อีแวนส์ ในปี 1900 พบภาพเขียนฝาผนังการกระโดดข้ามวัวกระทิง (Bull-leaping) บ่งบอกถึงการบูชาวัวกระทิงเป็นสัตว์ศักดิ์สิทธิ์ของชาวครีตโบราณ',
      'Excavated in 1900 by Sir Arthur Evans, unearthing vivid frescoes of sacred bull-leaping rituals, elaborate water engineering, and Linear B clay tablets.',
      'ห้ามหยิบจับเศษปูนปลาสเตอร์หรือทำลายเสาไม้สีแดงจำลองในพระราชวัง',
      'Do not touch the restored Minoan frescoes or the painted red fluted columns.',
      'https://i.ytimg.com/vi/7P5XdKoK5d8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7P5XdKoK5d8/hqdefault.jpg","title":"พระราชวังคนอสซอส (เขาวงกตและอสูรคนอร์สมิโนทอร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7P5XdKoK5d8","title":"One Archaeologist''s Hunt For Ancient Crete''s Legendary Minotaur","thumbnail":"https://i.ytimg.com/vi/7P5XdKoK5d8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-parthenon-acropolis-athens',
      'วิหารพาร์เธนอน (อนุสรณ์ศรัทธาแห่งเทพีอะธีนา)',
      'The Parthenon of the Acropolis (Temple of Pallas Athena)',
      'legend',
      'เอเธนส์ (กรีซ)',
      'Athens (Greece)',
      'อะโครโพลิส',
      'Acropolis',
      37.9715,
      23.7266,
      'temple_bell',
      'มหาเทวสถานหินอ่อนเพนเทลิกบนเนินเขาอะโครโพลิส สร้างขึ้นเพื่ออุทิศแด่เทพีอะธีนาผู้พิทักษ์ประชาธิปไตยและปัญญาญาณของชาวเอเธนส์ การออกแบบใช้สัดส่วนทองคำและเทคนิคการลวงตาของเสาหินดอริกที่ไม่มีเส้นตรงสมบูรณ์แบบเพื่อสร้างความสมมาตรทางสายตา',
      'The pinnacle of classical Doric architecture atop the rocky Acropolis plateau, dedicated to patron goddess Athena Parthenos. Engineered with golden ratio entasis curvature where no horizontal or vertical line is entirely straight.',
      'สร้างขึ้นในศตวรรษที่ 5 ก่อนคริสตกาลในยุคทองของเพริคลีส ผ่านประวัติศาสตร์การเป็นโบสถ์คริสต์ มัสยิด และคลังแสงระเบิดในยุคออตโตมันจนได้รับความเสียหาย',
      'Commissioned under Pericles with sculptures directed by Phidias, weathering Venetian bombardments in 1687 and remaining an immortal global emblem of civilization.',
      'ห้ามหยิบเศษหินอ่อนหรือเหยียบย่ำบนรอยฐานรากโบราณรอบเทวสถาน',
      'Strictly prohibited to collect marble pebbles or stand on protected pediment foundations.',
      'https://i.ytimg.com/vi/gQmEpx1uFsY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/gQmEpx1uFsY/hqdefault.jpg","title":"วิหารพาร์เธนอน (อนุสรณ์ศรัทธาแห่งเทพีอะธีนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=gQmEpx1uFsY","title":"The UnXplained: The DIVINE Perfection of the Parthenon (Season 5) | History","thumbnail":"https://i.ytimg.com/vi/gQmEpx1uFsY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-trolltunga-troll-tongue',
      'โทรลล์ทุงกา (แผ่นหินลิ้นโทรลล์แห่งนอร์เวย์)',
      'Trolltunga (The Stone Tongue of the Mountain Trolls)',
      'legend',
      'เวสต์ลันด์ (นอร์เวย์)',
      'Vestland (Norway)',
      'ออดดา',
      'Odda',
      60.1242,
      6.74,
      'creepy_wind',
      'แผ่นหินผาบางเฉียบที่ยื่นขนานออกไปในอากาศเหนือทะเลสาบริงเกดาลสวัทเนต์ที่ความสูง 700 เมตร ตำนานนอร์สเล่าว่า เป็นลิ้นของโทรลล์ร่างยักษ์ที่โอ้อวดท้าทายแสงอาทิตย์ แต่เมื่อแสงแดดยามเช้าสัมผัส ร่างของโทรลล์จึงกลายเป็นหินแข็งไปชั่วนิรันดร์',
      'A dramatic horizontal rock sliver jutting 700 meters above Lake Ringedalsvatnet. Norse folklore tells of an arrogant troll who stuck out his giant tongue to mock the rising sun, turning permanently to granite at dawn.',
      'ก่อตัวขึ้นจากการกัดเซาะของธารน้ำแข็งยุคน้ำแข็งเมื่อกว่า 10,000 ปีก่อน กลายเป็นหนึ่งในเส้นทางเดินป่าที่ท้าทายและมีทัศนียภาพงดงามที่สุดในสแกนดิเนเวีย',
      'Sculpted by glacial freeze-thaw cycles during the last Ice Age, embodying Norwegian outdoor culture and profound folk reverence for troll spirits residing in stone.',
      'ห้ามกระโดดหรือหยอกล้อโลดโผนบนขอบปลายแหลมของชะง่อนผา',
      'Never attempt acrobatics or reckless jumps at the sheer cliff lip.',
      'https://i.ytimg.com/vi/B1m_YyWhv_4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/B1m_YyWhv_4/hqdefault.jpg","title":"โทรลล์ทุงกา (แผ่นหินลิ้นโทรลล์แห่งนอร์เวย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=B1m_YyWhv_4","title":"Hiking to Trolltunga (the Troll Tongue) | VISIT NORWAY","thumbnail":"https://i.ytimg.com/vi/B1m_YyWhv_4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-reynisdrangar-black-sand-trolls',
      'เรย์นิสดรังการ์ (เสาหินโทรลล์ดำแห่งหาดทรายดำเรย์นิสฟยารา)',
      'Reynisdrangar (The Petrified Sea Trolls of the Black Sand Beach)',
      'legend',
      'ซูดือร์ลันด์ (ไอซ์แลนด์)',
      'Southern Region (Iceland)',
      'วิก อูร์ มีร์ดาล',
      'Vik i Myrdal',
      63.4022,
      -19.0308,
      'water_spirit',
      'แท่งหินบะซอลต์สีดำมะเมื่อมสูงกว่า 66 เมตรที่โผล่ขึ้นมาจากคลื่นยักษ์ริมหาดทรายดำ ตามตำนานเล่าว่า โทรลล์สองตนพยายามลากเรือสามเสากลับเข้าฝั่งก่อนพระอาทิตย์ขึ้น แต่เกิดความล่าช้าจนแสงอาทิตย์สาดส่อง ทั้งโทรลล์และเรือจึงกลายเป็นเสาหินกลางทะเล',
      'Towering 66-meter black basalt sea stacks rising violently from North Atlantic surf. Icelandic folklore recounts two trolls attempting to drag a three-masted ship to shore who were caught by dawn’s sun rays and turned to stone.',
      'หาดเรย์นิสฟยาราเป็นหาดทรายดำจากเถ้าภูเขาไฟที่ขึ้นชื่อเรื่องคลื่นยักษ์ลักซ่อน (Sneaker Waves) ที่พัดกลืนนักท่องเที่ยวลงสู่ทะเลน้ำแข็งได้ในพริบตา',
      'Formed by volcanic basalt magma cooling against icy tides, framed by columnar cliffs and notorious for lethal oceanic sneaker waves.',
      'ห้ามหันหลังให้กับคลื่นทะเลบนหาดทรายดำ หรือเข้าไปใกล้แนวเสาหินในวันที่คลื่นลมแรง',
      'Never turn your back to the surf or approach the sea stack base during turbulent swells.',
      'https://i.ytimg.com/vi/J17_RpARMsY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/J17_RpARMsY/hqdefault.jpg","title":"เรย์นิสดรังการ์ (เสาหินโทรลล์ดำแห่งหาดทรายดำเรย์นิสฟยารา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=J17_RpARMsY","title":"BLACK SAND BEACH | Reynisfjara Shore, Iceland","thumbnail":"https://i.ytimg.com/vi/J17_RpARMsY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-eye-of-the-sahara-richat',
      'ดวงตาแห่งซาฮารา (โครงสร้างริชาตและตำนานนครแอตแลนติส)',
      'The Eye of the Sahara (The Richat Structure and Atlantis Theory)',
      'legend',
      'อดราร์ (มอริเตเนีย)',
      'Adrar (Mauritania)',
      'อัวดาเน',
      'Ouadane',
      21.1269,
      -11.4016,
      'creepy_wind',
      'โครงสร้างวงแหวนหินซ้อนกันขนาดเส้นผ่านศูนย์กลาง 40 กิโลเมตรกลางทะเลทรายซาฮาราที่มองเห็นได้อย่างชัดเจนจากอวกาศ มีวงแหวนศูนย์กลางสามชั้นตรงกับคำบรรยายของเพลโตเรื่องผังเมืองนครแอตแลนติสที่สาบสูญ',
      'A deeply eroded 40-kilometer geological dome in the Mauritanian desert visible from orbit. Featuring concentric rings of stone and ridges closely matching Plato’s physical description of circular lost Atlantis.',
      'เดิมทีนักธรณีวิทยาเชื่อว่าเป็นหลุมอุกกาบาต แต่ปัจจุบันพบว่าเป็นโดมภูเขาไฟโบราณที่ยกตัวขึ้นและสึกกร่อนตามธรรมชาติ ชนเผ่าเร่ร่อนเบดูอินถือเป็นดินแดนแห่งความลึกลับของบรรพบุรุษ',
      'Initially thought to be a meteorite impact crater, now classified as an eroded hydrothermal alkaline dome with persistent archeological and mythological debates.',
      'ห้ามเดินทางข้ามใจกลางโครงสร้างริชาตโดยปราศจากน้ำดื่มและไกด์ท้องถิ่น',
      'Never attempt desert crossings across the Richat center without local navigation escorts.',
      'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"ดวงตาแห่งซาฮารา (โครงสร้างริชาตและตำนานนครแอตแลนติส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"Lost Roman Map has ATLANTIS at Eye of Sahara Africa! (Richat Structure)","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-abu-simbel-ramses-temple',
      'มหาวิหารอาบูซิมเบล (ปาฏิหาริย์แสงสุริยะแห่งฟาโรห์รามเสสที่ 2)',
      'Abu Simbel Temples (The Solar Miracle of Pharaoh Ramesses II)',
      'legend',
      'อัสวาน (อียิปต์)',
      'Aswan (Egypt)',
      'อาบูซิมเบล',
      'Abu Simbel',
      22.3372,
      31.6258,
      'temple_bell',
      'วิหารหินทรายขนาดมหึมาที่เจาะเข้าไปในหน้าผาหิน มีรูปสลักรามเสสที่ 2 ขนาดยักษ์สูง 20 เมตรนั่งตระหง่าน 4 องค์ ออกแบบทางดาราศาสตร์อย่างแม่นยำเพื่อให้แสงแดดส่องทะลุผ่านโถงวิหารลึก 65 เมตร เข้าไปส่องสว่างรูปสลักภายในห้องศักดิ์สิทธิ์เพียงปีละ 2 วันเท่านั้น',
      'Colossal rock temples carved directly into sandstone cliffs beside Lake Nasser, fronted by four 66-foot seated colossi of Ramesses the Great. Solar alignment channels sunlight into the sanctuary sanctuary on just two days annually.',
      'แสงอาทิตย์จะส่องสว่างองค์รามเสส เทพรา และเทพอามุน แต่จะปล่อยให้เทพบทาห์ (เทพแห่งโลกบาดาล) อยู่ในความมืดเสมอ ในทศวรรษ 1960 ยูเนสโกได้ระดมวิศวกรทั่วโลกตัดย้ายวิหารทั้งหลังหนีน้ำท่วมเขื่อนอัสวานได้อย่างน่าอัศจรรย์',
      'Relocated block-by-block by UNESCO in the 1960s to save it from drowning beneath Lake Nasser, preserving the celestial illumination phenomenon on February 22 and October 22.',
      'ห้ามสัมผัสหรือพิงรูปสลักหินโบราณในห้องศักดิ์สิทธิ์ชั้นในสุด',
      'Do not touch or lean against the carved sandstone deities inside the inner sanctum.',
      'https://i.ytimg.com/vi/5VjJOS6a2q8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/5VjJOS6a2q8/hqdefault.jpg","title":"มหาวิหารอาบูซิมเบล (ปาฏิหาริย์แสงสุริยะแห่งฟาโรห์รามเสสที่ 2)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=5VjJOS6a2q8","title":"Rare illumination of Ramesses II statue in Abu Simbel at sunrise","thumbnail":"https://i.ytimg.com/vi/5VjJOS6a2q8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-petra-treasury-jordan',
      'นครศิลาเพตรา (มหาวิหารอัลคาซเนห์แห่งชาวนาบาเทียน)',
      'Petra and Al-Khazneh (The Rose-Red City of the Nabataeans)',
      'legend',
      'มาอัน (จอร์แดน)',
      'Ma''an (Jordan)',
      'วาดีมูซา',
      'Wadi Musa',
      30.3285,
      35.4444,
      'creepy_wind',
      'นครหินสลักสีชมพูกุหลาบที่ซ่อนตัวอยู่หลังช่องแคบหินผาอัลสิก มหาวิหารอัลคาซเนห์ (คลังสมบัติ) สลักเสลาอย่างประณีตบนหน้าผาหินทราย ตำนานเบดูอินเล่าว่า โกศหินบนยอดวิหารบรรจุขุมสมบัติทองคำของฟาโรห์อียิปต์ในอดีต',
      'The legendary Rose-Red City carved into sheer sandstone gorges by Nabataean nomadic architects. The Treasury (Al-Khazneh) features an iconic ornamental urn mythologized by Bedouins as concealing ancient pharaonic gold.',
      'เจริญรุ่งเรืองในฐานะศูนย์กลางเส้นทางการค้าเครื่องเทศและกำยาน ก่อนจะสูญหายไปจากความทรงจำของโลกตะวันตกนานกว่า 600 ปี จนกระทั่งโยฮันน์ บวร์กฮาร์ดท์ ปลอมตัวเป็นชาวอาหรับเข้าไปค้นพบในปี 1812',
      'Flourished from the 4th century BC as an oasis capital, rediscovered in 1812 by Swiss traveler Johann Ludwig Burckhardt and celebrated as one of the New Seven Wonders of the World.',
      'ห้ามขูดขีดหรือปีนป่ายขึ้นไปบนระเบียงด้านหน้าของวิหารอัลคาซเนห์',
      'Strictly prohibited to climb onto the facade plinths of the Treasury facade.',
      'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"นครศิลาเพตรา (มหาวิหารอัลคาซเนห์แห่งชาวนาบาเทียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"Petra: Lost City of Stone | Full Documentary | NOVA | PBS","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-lake-titicaca-inca-creation',
      'ทะเลสาบติติกากา (จุดกำเนิดสุริยะเทพและอารยธรรมอินคา)',
      'Lake Titicaca and Isla del Sol (The Birthplace of the Inca Sun)',
      'legend',
      'ลาปาซ (โบลิเวีย)',
      'La Paz (Bolivia)',
      'โคปากาบานา',
      'Copacabana',
      -16.0333,
      -69.15,
      'water_spirit',
      'ทะเลสาบน้ำจืดที่อยู่สูงที่สุดในโลกที่เรือพาณิชย์สามารถเดินเรือได้ (สูง 3,812 เมตร) ตามเทพปกรณัมอินคา สุริยเทพวีราโคชาได้ผุดขึ้นมาจากผืนน้ำเพื่อสร้างดวงอาทิตย์ ดวงจันทร์ และส่งบุตรชายมังโก คาปัค มาก่อตั้งจักรวรรดิอินคา ณ เกาะแห่งดวงอาทิตย์ (Isla del Sol)',
      'The highest navigable freshwater lake on Earth (3,812m). In Andean cosmology, creator god Viracocha rose from its waters after the great flood to command the sun and stars into being, birthing the founding Inca emperors on Isla del Sol.',
      'นักโบราณคดีค้นพบวิหารหินโบราณยุคก่อนอินคาจมอยู่ใต้ผิวน้ำใกล้เกาะดวงอาทิตย์ สะท้อนประวัติศาสตร์การเคารพบูชาผืนน้ำศักดิ์สิทธิ์ของชาวไอมาราและเคชัว',
      'Submerged ruins of an underwater temple dating back 1,500 years confirm pre-Inca Tiwanaku religious devotion along the sacred Andean lake.',
      'ห้ามทิ้งสิ่งปฏิกูลหรือส่งเสียงเอะอะลบหลู่ศิลาศักดิ์สิทธิ์บนเกาะแห่งดวงอาทิตย์',
      'Do not desecrate sacred rock outcrops or ancestral stone labyrinths on Isla del Sol.',
      'https://i.ytimg.com/vi/yCx1VwVcg6E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yCx1VwVcg6E/hqdefault.jpg","title":"ทะเลสาบติติกากา (จุดกำเนิดสุริยะเทพและอารยธรรมอินคา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yCx1VwVcg6E","title":"The Magic of Lake Titicaca: Exploring the Sacred Inca Site","thumbnail":"https://i.ytimg.com/vi/yCx1VwVcg6E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-uluru-ayers-rock-dreamtime',
      'อุลูรู (มหาศิลาศักดิ์สิทธิ์สีแดงแห่งบรรพชนดรีมไทม์)',
      'Uluru (The Sacred Red Monolith of Anangu Tjukurpa)',
      'legend',
      'นอร์เทิร์นเทร์ริทอรี (ออสเตรเลีย)',
      'Northern Territory (Australia)',
      'ยูลารา',
      'Yulara',
      -25.3444,
      131.0369,
      'creepy_wind',
      'เขาหินทรายสีแดงขนาดยักษ์สูง 348 เมตรกลางทุ่งทะเลทรายสีแดงของออสเตรเลีย เปลี่ยนสีตามแสงแดดตลอดทั้งวัน เป็นศูนย์รวมจิตวิญญาณของชาวอนันกูโบราณ รอยแตกและถ้ำบนหินคือร่องรอยการต่อสู้และการเดินทางของสิ่งมีชีวิตในยุกดรีมไทม์ (จูกูร์ปา)',
      'A massive 348-meter red arkosic sandstone monolith dominating central Australia''s desert. Deeply sacred to the Anangu people, every fissure, cave, and weathering scar represents creation exploits of ancestral Dreamtime beings.',
      'มี ''คำสาปอุลูรู'' อันโด่งดัง ผู้ที่ขโมยเศษหินหรือทรายสีแดงกลับไป มักประสบเคราะห์ร้าย เจ็บป่วย หรือสูญเสียทรัพย์สิน จนต้องส่งพัสดุหินคืนอุทยานแห่งชาตินับพันชิ้นต่อปี ทางการได้สั่งปิดการปีนเขาอย่างถาวรตั้งแต่ปี 2019',
      'Infamous for the ''Sorry Rocks'' phenomenon where stolen pebbles are mailed back with desperate apology letters; climbing was officially and permanently banned in October 2019.',
      'ห้ามเก็บหรือนำหินและทรายสีแดงจากอุลูรูกลับไปเป็นของสะสม และห้ามปีนขึ้นบนยอดหินศักดิ์สิทธิ์',
      'Strictly forbidden to remove sandstone rocks or climb upon the sacred surface of Uluru.',
      'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"อุลูรู (มหาศิลาศักดิ์สิทธิ์สีแดงแห่งบรรพชนดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"Why Is Uluru Sacred? Australia’s Timeless Red Rock Explained | Curious Minds","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-nan-madol-venice-of-pacific',
      'นันมาดอล (เวนิสแห่งแปซิฟิกและนครเสาหินลอยน้ำต้องสาป)',
      'Nan Madol (The Megalithic Venice of the Pacific)',
      'legend',
      'โปนเป (ไมโครนีเซีย)',
      'Pohnpei (Micronesia)',
      'มาโดเลนีห์มว์',
      'Madolenihmw',
      6.845,
      158.335,
      'water_spirit',
      'นครโบราณที่สร้างขึ้นจากแท่งหินบะซอลต์ขนาดยักษ์หนักรวมกันกว่า 750,000 ตัน เรียงตัวเป็นเกาะเทียมเกือบ 100 เกาะเหนือบึงน้ำตื้นริมชายฝั่งทะเลแปซิฟิก ตำนานเล่าว่าสร้างขึ้นโดยสองพี่น้องนักเวทที่ใช้เวทมนตร์เหาะนำหินยักษ์มาวางลอยตัวเหนือน้ำ',
      'A ruined megalithic city constructed from 750,000 tons of columnar basalt atop nearly 100 artificial islets interconnected by canals. Oral lore tells of twin sorcerers Olisihpa and Olosohpa flying giant basalt logs with dragon magic.',
      'สร้างขึ้นในสมัยราชวงศ์เซาเดเลอร์ระหว่างศตวรรษที่ 12-13 เป็นเมืองหลวงและสุสานของชนชั้นปกครอง ชาวพื้นเมืองเชื่อว่าเป็นสถานที่ต้องสาปที่มีเสียงผีสิงและดวงวิญญาณบรรพชนวนเวียนอยู่หลังพระอาทิตย์ตก',
      'Designated a UNESCO World Heritage site, considered by H.P. Lovecraft enthusiasts as an inspiration for R''lyeh due to its cyclopean basalt architecture.',
      'ห้ามค้างคืนบนเกาะสุสานนันดัววาส หรือส่งเสียงรบกวนในลำคลองยามค่ำคืน',
      'Do not camp overnight on the Nandauwas mortuary islet after dusk.',
      'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"นันมาดอล (เวนิสแห่งแปซิฟิกและนครเสาหินลอยน้ำต้องสาป)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"Ancient City of Nan Madol | Lost Cities With Albert Lin","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
    );